/** Greek chapter bodies. In-app names stay in English so they match the classroom screen. */

export const EL_CHAPTERS = {
  '00-why-we-quest.md': `# Γιατί κάνουμε Quest

Είσαι ακόμα ο δάσκαλος αγγλικών. Το Quest δεν αντικαθιστά την κρίση σου, το μάθημα ή τη φωνή σου. Δίνει στην ώρα έναν **κόσμο που τα παιδιά βλέπουν** — ώστε η αρετή να έχει όνομα, ο κόπος ίχνος, και η χρονιά κορυφές που αξίζει να θυμάσαι.

Αυτό είναι το **γιατί**. Το επόμενο κεφάλαιο, Προσανατολισμός, είναι ο **χάρτης**: ποια οθόνη, ποια καρτέλα, ποια τελετή, και ποιος άλλος στο σχολείο χρησιμοποιεί το Quest.

## Το πρόβλημα που θέλαμε να λύσουμε

Μια τάξη έχει περισσότερες μορφές επιτυχίας από όσες μπορεί να δείξει ένας βαθμός. Η ακαδημαϊκή μάθηση είναι σημαντική και πρέπει να παραμένει ορατή. Αν όμως η αναγνώριση ακολουθεί μόνο το υψηλότερο αποτέλεσμα, πολλά παιδιά έχουν ελάχιστους ορατούς τρόπους να συνεισφέρουν: να βοηθήσουν έναν συμμαθητή, να ξαναπροσπαθήσουν, να ακούσουν προσεκτικά, να συμπεριλάβουν κάποιον, να βρουν δημιουργικό τρόπο να χρησιμοποιήσουν τη γλώσσα ή να επιμείνουν σε κάτι δύσκολο.

Το The Great Class Quest δημιουργήθηκε για να **διευρύνει αυτόν τον φακό**. Δίνει στον εκπαιδευτικό έναν σταθερό τρόπο να παρατηρεί και να επιβραβεύει **παρατηρήσιμη συμπεριφορά, life skills, προσπάθεια, πρόοδο και belonging** παράλληλα με την ακαδημαϊκή μάθηση. Δεν είναι αντι-ακαδημαϊκό σύστημα και δεν υπόσχεται ότι κάθε παιδί θα ανταποκριθεί με τον ίδιο τρόπο. Είναι ένα παιδαγωγικό επίπεδο της τάξης που κάνει περισσότερες ουσιαστικές στιγμές ορατές και άξιες συζήτησης.

## Ένας κόσμος σαν παιχνίδι γύρω από το μάθημα

Το Quest είναι ένας **κόσμος που κρατά όλη τη χρονιά**, όχι μια συλλογή από άσχετα κουμπιά. Σύννεφα, χάρτες, σπίτια, τελετές, ιστορίες, ανέβασμα επιπέδων, επιλογές και μια μικρή οικονομία δίνουν στην καθημερινή ώρα αγγλικών ένα κοινό νήμα από μάθημα σε μάθημα. Ένα μάθημα μπορεί να τροφοδοτεί την πορεία του τμήματος, το προσωπικό μονοπάτι ενός παιδιού, την ταυτότητα του guild, μια κοινή ιστορία και την επόμενη αποστολή.

Ο στόχος δεν είναι τα παιδιά να κάθονται και να παίζουν μόνα τους την εφαρμογή. Οι μαθητές δεν συνδέονται. Βλέπουν το Quest στην οθόνη της τάξης — σύννεφα, χάρτη, σπίτια, γιορτές και ιστορίες — ενώ εσύ το τρέχεις από τον υπολογιστή της τάξης. Το κομμάτι του παιχνιδιού υπηρετεί το μάθημα· το μάθημα δεν γίνεται αφορμή για άσκοπα κλικ.

## Εσύ είσαι ο Quest Master

Τα αστέρια δεν είναι αυτοκόλλητα σε πίνακα, ούτε επίσημος βαθμός. Είναι **συγκεκριμένη αναγνώριση που επιλέγεις να δώσεις** όταν ένα παιδί κάνει κάτι που αξίζει να ονομαστεί. Ο εκπαιδευτικός παρατηρεί την τάξη, αποφασίζει τι μετράει, εξηγεί το γιατί και προσαρμόζει την πρακτική στην ομάδα.

Σε κάθε πλάνο, **εσύ** αποφασίζεις ποιος παίρνει αστέρια. Στο Elite η AI μπορεί να γράψει το ημερολόγιο, να ζωγραφίσει, ή να προτείνει σελίδα Chronicle — και εσύ κρατάς, διορθώνεις, ή αγνοείς. Η περιπέτεια υπηρετεί την τάξη αγγλικών. Η τάξη δεν υπηρετεί την περιπέτεια.

Οι μαθητές δεν συνδέονται. **Βλέπουν το Quest** στην οθόνη της τάξης — σύννεφα, χάρτη, σπίτια, τελετές — ενώ το τρέχεις εσύ από **υπολογιστή τάξης** (και συμπαγές κινητό όταν περπατάς την αίθουσα).

## Τέσσερις life skills, ονομασμένες στη στιγμή

Τα τέσσερα κουμπιά του Award Stars είναι **δεξιότητες ζωής (life skills)** που μπορείς να ονομάσεις *τη στιγμή που συμβαίνουν* στην ώρα αγγλικών — όχι βαθμοί γραμματικής, και όχι αυτοκόλλητα «καλό παιδί».

| Life skill | Τι ονομάζεις |
|------------|----------------|
| **Teamwork** | Βοήθεια, συνεργασία, ακρόαση και χώρος για έναν συμμαθητή |
| **Creativity** | Νέα ιδέα, έκπληξη σε πρόταση ή δημιουργικό παιχνίδι με τη γλώσσα |
| **Respect** | Καλοσύνη, συμπερίληψη, φροντίδα των ανθρώπων και της αίθουσας |
| **Focus** | Προσπάθεια, προσοχή, αυτορρύθμιση και επιμονή σε κάτι δύσκολο |

Η καλύτερη γλώσσα της τάξης δείχνει την πράξη, όχι μια ταμπέλα προσωπικότητας. «Περίμενες, άκουσες και έβαλες τον συμμαθητή σου στην απάντηση — Teamwork» είναι πιο χρήσιμο από το «είσαι υπέροχος». Αυτή είναι η λογική της συγκεκριμένης ανατροφοδότησης για τη συμπεριφορά και τη διαδικασία: η επόμενη χρήσιμη πράξη γίνεται πιο εύκολο να αναγνωριστεί και να επαναληφθεί ([Hattie & Timperley, 2007](https://doi.org/10.3102/003465430298487)· [IES WWC, 2024](https://ies.ed.gov/ncee/WWC/PracticeGuide/31/Published)).

Το Welcome Back είναι ο χαιρετισμός σε παιδί που έλειπε. Scholar’s Bonus και αστέρια Story Weaver έρχονται από **διαγωνίσματα** και **κοινή γραφή** — δικά τους τελετουργικά, όχι έξτρα πετράδια στο σύννεφο.

Ένας συμμαθητής μπορεί να ξοδέψει **Gold** για να στηρίξει κάποιον που μένει πίσω αυτόν τον μήνα (**Hero’s Boon — peer gift**) — γενναιοδωρία με κανόνες δικαιοσύνης που βλέπει όλη η τάξη. Κοντά στο τέλος του μήνα, το **Teacher Boon** σου επιτρέπει να ονομάσεις έναν χαρακτήρα που τα τέσσερα καθημερινά κουμπιά δεν πιάνουν ακριβώς. Κανένα από αυτά δεν γίνεται μόνιμη ετικέτα· σημειώνει μια στιγμή ή ένα μοτίβο που η τάξη μπορεί να καταλάβει.

## Η ακαδημαϊκή μάθηση παραμένει εδώ

Το GCQ διευρύνει την αναγνώριση· δεν αφαιρεί τον ακαδημαϊκό σκοπό. Η ώρα αγγλικών συνεχίζει να διδάσκει γλώσσα, γραμματισμό, γνώση και αυτοπεποίθηση. Το **Scholar’s Scroll** υποστηρίζει διαγωνίσματα και υπαγορεύσεις, το **Quiz of the Week** επανάληψη και ανάκληση της ύλης, το **Story Weavers** κάνει τη γραφή συλλογική και το **Quest Assignment** μεταφέρει τη μάθηση στο επόμενο μάθημα.

Η διάκριση έχει σημασία: ένα παιδί δεν χρειάζεται να είναι ο μαθητής με την υψηλότερη επίδοση για να είναι πολύτιμο μέλος της τάξης, ενώ ένα life-skill star δεν αντικαθιστά την ακαδημαϊκή ανατροφοδότηση. Οι δύο διαδρομές μπορούν να ενισχύουν η μία την άλλη, όταν παραμένουν και οι δύο ειλικρινείς και ξεχωριστές.

## Τρεις ανάγκες. Τρεις απαντήσεις

Τα παιδιά μένουν όταν νιώθουν ότι **διαλέγουν**, ότι **τα καταφέρνουν**, και ότι **ανήκουν** (αυτοπροσδιορισμός: Ryan & Deci, 2000· Niemiec & Ryan, 2009). Το Quest δίνει σε καθεμία έναν κόσμο που φαίνεται:

| Ανάγκη | Τι κάνει ορατό το Quest |
|--------|-------------------------|
| **Αυτονομία** | Εσύ δίνεις το αστέρι. Το παιδί διαλέγει vocation, ξοδεύει Gold, χτίζει avatar. |
| **Ικανότητα** | Σύννεφο, χάρτης, επίπεδα, αύρα. Η πρόοδος δεν είναι μυστικό του βαθμολογίου. |
| **Ανήκειν** | Το τμήμα στον χάρτη, το παιδί στον πίνακα, σπίτι για ζωή — τρεις κύκλοι, όχι ένας. |

Avatar Forge, Hero Path και μότο σπιτιού είναι πώς ένα παιδί *γίνεται κάποιος* στα αγγλικά, όχι γραμμή σε κρυφό λογιστικό φύλλο (Dörnyei, 2009).

## Γιατί σχεδιάστηκαν έτσι

Ο σχεδιασμός ενημερώνεται από συμπληρωματικές ιδέες για το κίνητρο και τη διδασκαλία. Οι πηγές τεκμηριώνουν τις αρχές του σχεδιασμού· δεν αποτελούν απόδειξη ότι το ίδιο το GCQ έχει ήδη αξιολογηθεί πειραματικά.

| Αρχή | Πώς φαίνεται στο Quest |
|------|------------------------|
| **Αυτονομία** | Το παιδί κάνει περιορισμένες, ουσιαστικές επιλογές: Hero Path, κλαδί στο Skill Tree, αγορά με Gold ή συμβολή σε κοινή ιστορία. |
| **Ικανότητα** | Σύννεφα, χάρτες, επίπεδα, αύρες, ιστορίες και δίκαια ορόσημα κάνουν την πρόοδο ορατή — όχι μόνο κρυμμένη σε ένα βαθμολόγιο. |
| **Relatedness / Ανήκειν** | Το παιδί ανήκει σε τάξη, guild, ιστορία και σχολική κοινότητα, ακόμη κι όταν δεν συναντά όλους τους συμμαθητές του στο ίδιο μάθημα. |
| **Δομημένη συνεργασία** | Guild Hall, Bounties, Team Quest και Story Weavers κάνουν τη συμμετοχή κοινωνική· ο εκπαιδευτικός δίνει ρόλους και χώρο και στους πιο ήσυχους μαθητές. |
| **Στοχευμένη ανατροφοδότηση** | Τα Award Stars ονομάζουν μια παρατηρήσιμη πράξη εκείνη τη στιγμή, ενώ το Hero’s Chronicle βοηθά να φανούν μοτίβα σε βάθος χρόνου. |

Η Self-Determination Theory συνδέει την ενεργή και θετική συμμετοχή με την αυτονομία, την ικανότητα και το relatedness ([Niemiec & Ryan, 2009](https://journals.sagepub.com/doi/10.1177/1477878509104318)· [SDT in education](https://selfdeterminationtheory.org/topics/application-education/)). Η δομημένη συνεργατική μάθηση χρειάζεται κοινό στόχο και σωστή οργάνωση· ο ανταγωνισμός μπορεί να βοηθήσει, αλλά η υπερβολική έμφαση στη νίκη μπορεί να τραβήξει την προσοχή μακριά από τη μάθηση ([EEF](https://educationendowmentfoundation.org.uk/education-evidence/teaching-learning-toolkit/collaborative-learning-approaches?search_term=collab)).

Η gamification μπορεί να υποστηρίξει γνωστικά, ως προς το κίνητρο και συμπεριφορικά αποτελέσματα, όμως τα αποτελέσματα διαφέρουν ανάλογα με τον σχεδιασμό και το πλαίσιο. Γι’ αυτό το GCQ συνδυάζει συνεργασία με πρόκληση, πρόοδο με αναστοχασμό και θέαμα με την κρίση του εκπαιδευτικού· δεν αντιμετωπίζει τους πόντους ή τα βραβεία ως καθολική λύση ([Sailer & Homner, 2020](https://doi.org/10.1007/s10648-019-09498-w)).

## Τρεις αγώνες. Τρία είδη ανταγωνισμού

Όχι μία αόριστη «τριπλή κλίμακα». Τρεις **διαφορετικές κοινωνικές λογικές**, επίτηδες χωριστές:

1. **Hero’s Challenge — ένας προς έναν, αυτόν τον μήνα.** Προσωπική ευθύνη δίπλα στον χάρτη. Το παιδί βλέπει τον εαυτό του απέναντι στους συμμαθητές *αυτού* του τμήματος. Κορυφή: **Prodigy of the Month**. Τρέχει *δίπλα* στον ομαδικό, όχι αντί γι’ αυτόν.
2. **Team Quest — ομάδα προς ομάδα, αυτόν τον μήνα.** Το τμήμα είναι μία μονάδα στον χάρτη, μέσα στο ίδιο **Quest League** (Junior B δεν τρέχει με Class C). Μέσα στην αίθουσα συνεργάζονται· απέναντι στα άλλα τμήματα του league συναγωνίζονται. Κορυφή: το μισό της **Ceremony of the Month** για τα τμήματα.
3. **Guild Hall — ετήσια διευρυμένη ταυτότητα.** Σπίτι για ζωή: Dragon Flame, Grizzly Might, Owl Wisdom, Phoenix Rising. Μέλη από *κάθε* ηλικιακή ζώνη — παιδιά που μπορεί να μην μοιράζεσαι ποτέ μάθημα. Κορυφή: **Grand Guild Ceremony** τον Ιούνιο.

Ένα αστέρι στο μάθημα τρέφει και τους τρεις, αλλιώς ο καθένας. Γι’ αυτό τα ονόματα των στεμμάτων μένουν χωριστά.

## Gold ως οικονομία, όχι ως καλλυντικό

Τα αστέρια είναι **μόνιμο ίχνος χαρακτήρα**. Το **Gold** ξοδεύεται (1 αστέρι = 1 Gold). Δύο νούμερα, δύο δουλειές.

- **Να κρατήσεις:** το παιδί μαθαίνει να μαζεύει για Crown, Familiar, μεγάλο artifact — και η επιλογή είναι αληθινή **επειδή το ξόδεμα δεν αγοράζει κατάταξη**.
- **Μικρές αποφάσεις:** προϋπολογισμός, σπανιότητα (**2 legendary / μαθητή / μήνα**), **Hero’s Boon** ως κοινωνική δαπάνη **15 Gold** (έως **4** ανά τμήμα τη μέρα).

Σε αυτό το κεφάλαιο το Hero’s Boon είναι *οικονομία γενναιοδωρίας*. Ποιος δικαιούται, και η καρδιά στο σύννεφο, μένουν στο Award Stars.

## Κόσμος που η τάξη βλέπει

Η πρόοδος δεν είναι κρυφό λογιστικό φύλλο. Η αίθουσα κοιτάει ψηλά και *νιώθει* τη χρονιά:

- **Σύννεφα μαθητών** όσο διδάσκεις
- **League Map** που ταξιδεύει μαζί το τμήμα
- **Projector Mode** — ζωντανή **ταπετσαρία** που ανοίγεις *όποτε βοηθά το μάθημα* (ουρανός, ρολόγια, χρόνος που μένει, κάρτες ιστορίας)
- Χρωματιστές **αύρες** καθώς μεγαλώνει ένα Hero Path
- Πλάσματα που **εκκολάπτονται και εξελίσσονται**
- Δύο είδη **τελετής** (μηνιαία διπλή τελετή· στέψη σπιτιών τον Ιούνιο)

Ό,τι βλέπουν τα παιδιά, μπορούν να το πουν αγγλικά. Αυτός είναι ο λόγος του θεάματος.

## Πώς δένουν μεταξύ τους όλα

| Στρώμα | Features | Τι υπηρετεί |
|--------|----------|-------------|
| **Notice / Παρατηρώ** | Award Stars, Bounties, Welcome Back | Ονομάζει μια παρατηρήσιμη συνεισφορά, προσπάθεια, επιστροφή ή κοινό στόχο. |
| **Belong / Ανήκω** | Team Quest, Guild Hall, Hero’s Boon | Δίνει κοινή ταυτότητα στην τάξη και στο σχολείο χωρίς μία κατάταξη να γίνεται όλη η ιστορία. |
| **Grow / Αναπτύσσομαι** | Hero Path, Skill Tree, Gold, Mystic Market, Familiars | Μετατρέπει την πρόοδο σε επιλογή, ταυτότητα, υπομονή και σχέση με τον κόσμο του Quest. |
| **Remember / Θυμάμαι** | Adventure Log, Hero’s Chronicle, ceremonies | Δίνει μνήμη στο μάθημα, ιδιωτικό αρχείο στον εκπαιδευτικό και κορυφές στη χρονιά. |
| **Create and learn / Δημιουργώ και μαθαίνω** | Scholar’s Scroll, Quiz of the Week, Story Weavers, Quest Assignment | Κρατά στο κέντρο τη γλωσσική μάθηση, την εξάσκηση, τη γραφή και τη συνέχεια. |

Ένα Award Star μπορεί να τροφοδοτεί πολλά σημεία του κόσμου, αλλά κάθε μέρος του Quest έχει διαφορετική δουλειά. Το Team Quest είναι μηνιαίος αγώνας τμημάτων, το Hero’s Challenge μηνιαίος αγώνας μαθητών, ενώ το Guild Hall είναι η ετήσια ταυτότητα των σπιτιών. Η **Ceremony of the Month**, ο **Hero of the Day** και η **Grand Guild Ceremony** είναι διαφορετικές τελετουργίες με διαφορετικό νόημα.

## Το Hero’s Chronicle ξεκινά από την πρώτη μέρα

Το **Hero’s Chronicle** είναι το ιδιωτικό τετράδιο του εκπαιδευτικού από την πρώτη ημέρα του Σεπτεμβρίου. Υπάρχει δίπλα στο roster και στην καθημερινή ρουτίνα. Εκεί καταγράφεις παρατηρήσεις, μοτίβα, στόχους, στρατηγικές και σημαντικές στιγμές· δημοσιεύεις μόνο ό,τι επιλέξεις συνειδητά να μοιραστείς. Οι μαθητές δεν το βλέπουν ποτέ, και δεν είναι το Adventure Log που διαβάζει η τάξη.

Ο καθημερινός κορμός είναι απλός: διδάσκεις, παρατηρείς, απονέμεις όταν υπάρχει λόγος, κρατάς ορατή την επόμενη αποστολή και κλείνεις το μάθημα με το Adventure Log όταν το πλάνο το περιλαμβάνει. Το υπόλοιπο Quest προσθέτει σταδιακά βάθος· δεν πρέπει ποτέ να κάνει ένα καλό μάθημα δυσκολότερο.

## Ο χρόνος έχει κορυφές

Η χρονιά δεν είναι επίπεδος πίνακας βαθμολογίας.

- **Κάθε μάθημα** στέφει **αυτόματα** έναν **Hero of the Day** όταν πατάς **Crown Today’s Hero** (ημερήσιο φως, αρχείο στο **Hall of Heroes**). Δεν διαλέγεις το όνομα στο χέρι.
- **Κάθε νέος μήνας** ανοίγει την **Ceremony of the Month**: πρώτα ο αγώνας χάρτη των τμημάτων, μετά Prodigy of the Month γι’ αυτή την ομάδα (αρχείο στο **Hall of Prodigies**).
- **Τον Ιούνιο** στέφονται τα σπίτια στην **Grand Guild Ceremony**.

Ημερήσιος ήρωας ≠ μηνιαίος prodigy. Hall of Heroes ≠ Hall of Prodigies. Πες τα ονόματα με τον ίδιο τρόπο κάθε φορά.

### Προτεινόμενη πορεία εισαγωγής

Η παρακάτω σειρά είναι μια **ενδεικτική αφετηρία** για μια σχολική χρονιά που δίνει σταθερά κάτι νέο στην τάξη, χωρίς να φορτώνει τον εκπαιδευτικό ή τα παιδιά από την πρώτη εβδομάδα:

- **Σεπτέμβριος:** Scholar’s Scroll, Adventure Log, Hero’s Chronicle ως εργαλείο του εκπαιδευτικού από την πρώτη ημέρα και ο βασικός καθημερινός κορμός.
- **Οκτώβριος:** Ceremony of the Month, Hero’s Challenge, Hero Path, Skill Tree και Bounties — πρώτα οι προσωπικές διαδρομές και οι ορατές κορυφές.
- **Νοέμβριος:** Guild Hall, όλοι οι μηχανισμοί του Fortune’s Wheel, Quiz of the Week, Quest Events και Hero’s Boon ως peer gift — κοινότητα, ρυθμός και συνεργατική πρόκληση.
- **Δεκέμβριος:** Gold economy και Mystic Market χωρίς Familiars — επιλογή και υπομονή, αφού τα παιδιά έχουν ήδη συγκεντρώσει Gold.
- **Ιανουάριος:** Familiars — ένα νέο επίπεδο σχέσης με την πρόοδο, πάνω σε οικονομία που έχει γίνει οικεία.
- **Φεβρουάριος:** Story Weavers — συλλογική γραφή, όταν ο κόσμος και οι ρουτίνες είναι ήδη γνωστά.
- **Μάρτιος–Ιούνιος:** πλήρης χρήση, εδραίωση, πειραματισμός με νέα features και Grand Guild Ceremony τον Ιούνιο.

Η πορεία αυτή είναι **προτεινόμενη, όχι υποχρεωτική**. Αν νιώσεις έτοιμος, μπορείς να υιοθετήσεις, να συνδυάσεις ή να δοκιμάσεις κάτι νωρίτερα ή αργότερα. Η σταδιακή εισαγωγή ακολουθεί την καθοδήγηση για αποτελεσματική επαγγελματική ανάπτυξη: λογική σειρά, χρόνος για εξάσκηση και σταδιακή εδραίωση των νέων ρουτινών ([EEF Effective Professional Development](https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/effective-professional-development%20)).

## Οικογένειες στην πόρτα, όχι στο γραφείο

Σε Pro και Elite, κάθε παιδί μπορεί να έχει είσοδο **Family Portal**. Οι οικογένειες βλέπουν την εβδομάδα με μια ματιά, εργασίες από Quest Assignment με τα τεστ που έρχονται, πρόοδο και παρουσίες, και μπορούν να γράψουν στο σχολείο. **Δεν** βλέπουν το ιδιωτικό **Hero’s Chronicle** εκτός αν δημοσιεύσεις σελίδα.

Το **School Office** (γραμματεία Elite) κρατά αργίες και τη σχολική χρονιά τίμια, ώστε ο στόχος χάρτη κάθε δασκάλου να ταιριάζει στο ίδιο ημερολόγιο.

## Τι δεν είναι αυτό

- Όχι παιχνίδι που τα παιδιά παίζουν μόνα στο σπίτι. Δεν συνδέονται.
- Όχι «καλό παιδί», ούτε επίσημος βαθμός ή κρίση για την αξία ενός παιδιού.
- Όχι αυθαίρετη ή αόριστη απονομή: τα αστέρια συνδέονται με παρατηρήσιμη πράξη ή πρόοδο και συγκεκριμένη ανατροφοδότηση.
- Όχι τρόπος να αγοράσεις κατάταξη με Gold. Το Gold είναι ξεχωριστό από το rank.
- Όχι δημόσια ταπείνωση, δημοφιλία ως κριτήριο ή μόνιμη ετικέτα. Η δίκαιη εναλλαγή, η συν-αναγνώριση και οι κανόνες του Hero’s Boon προστατεύουν τον σκοπό.
- Όχι αντικατάσταση των επαγγελματικών σου σημειώσεων — το Chronicle είναι *δικό σου* ιδιωτικό τετράδιο και η AI παραμένει προαιρετική και επεξεργάσιμη.
- Όχι μία τελετή με τρία ονόματα. Η μηνιαία διπλή τελετή, το ημερήσιο στέμμα και η στέψη σπιτιών τον Ιούνιο είναι διαφορετικές κορυφές.
- Αν το κομμάτι του παιχνιδιού αποσπά από τη μάθηση, το απλοποιείς. Ο εκπαιδευτικός επιστρέφει πάντα στον τίμιο πυρήνα του μαθήματος.

## Πώς μοιάζει η επιτυχία στην πράξη

Η επιτυχία δεν είναι «όλοι κερδίζουν κάθε leaderboard». Μοιάζει περισσότερο με αυτά:

- Τα παιδιά μπορούν να περιγράψουν στα αγγλικά μια βοηθητική πράξη, όχι μόνο ένα score.
- Περισσότερες από μία μορφές συνεισφοράς γίνονται ορατές μέσα στον μήνα.
- Οι μαθητές μαθαίνουν να προσέχουν την προσπάθεια των συμμαθητών τους και να κάνουν χώρο ο ένας για τον άλλον.
- Ο εκπαιδευτικός έχει πιο καθαρό και ανθρώπινο αρχείο μοτίβων και επόμενων βημάτων.
- Η ακαδημαϊκή εξάσκηση και η κουλτούρα της τάξης ενισχύουν η μία την άλλη χωρίς να γίνονται το ίδιο πράγμα.
- Η τάξη κρατά κοινή ιστορία από τον Σεπτέμβριο έως τον Ιούνιο και παραμένει ανοιχτή σε νέες δυνατότητες, ιδέες και πειραματισμό.

## Τι να διαβάσεις μετά

Ο **Προσανατολισμός** ακολουθεί: τρία περιβάλλοντα, τυπικό μάθημα, οι δέκα καρτέλες, τα πλάνα με μία πρόταση και τα ονόματα που πρέπει να μένουν διακριτά. Τα κεφάλαια μετά από αυτόν εξηγούν ένα προς ένα τι πατάς, πότε συμβαίνει, πώς τροφοδοτείται το υπόλοιπο Quest και τι περιλαμβάνει κάθε πλάνο.

### Σημείωση τεκμηρίωσης

Οι εκπαιδευτικές πηγές παραπάνω τεκμηριώνουν επιλογές σχεδιασμού όπως η υποστήριξη της αυτονομίας, η συγκεκριμένη ανατροφοδότηση, η δομημένη συνεργασία, η κοινωνικο-συναισθηματική ανάπτυξη και η σταδιακή επαγγελματική μάθηση. Δεν αποτελούν αξιολόγηση του ίδιου του The Great Class Quest. Χρησιμοποίησε την επαγγελματική σου κρίση, παρατήρησε τη δική σου τάξη και προσάρμοσε το σύστημα στα παιδιά που έχεις μπροστά σου.
`,

  '00-the-quest.md': `# Προσανατολισμός: πώς είναι στημένος ο κόσμος της τάξης

Έχεις το **γιατί** (το προηγούμενο κεφάλαιο). Αυτό είναι ο **χάρτης**: ποιος χρησιμοποιεί ποια οθόνη, πώς μοιάζει ένα τυπικό μάθημα, πού ζουν οι δέκα καρτέλες, και ποια ονόματα δεν ανακατεύονται ποτέ.

Οι αριθμοί, οι τιμές και τα όρια των πλάνων στα επόμενα κεφάλαια ταιριάζουν με όσα βλέπεις στην εφαρμογή.

## Ποιος χρησιμοποιεί το Quest

Το σχολείο έχει **τρία περιβάλλοντα**. Η ίδια σχολική χρονιά ζει και στα τρία· ο καθένας βλέπει μόνο ό,τι χρειάζεται.

| Περιβάλλον | Ποιος | Σε τι χρησιμεύει |
|-----------|------|------------------|
| **Teacher** | Ο δάσκαλος της τάξης | Το πλήρες Quest σε **υπολογιστή τάξης**. Το βάθος μεγαλώνει με το πλάνο: **Starter**, **Pro**, και **Elite**. |
| **Secretary** (School Office) | Όποιος τρέχει τη χρονιά | Τμήματα για κάθε δάσκαλο, νέοι μαθητές, τοποθέτηση, αργίες, άνοιγμα/κλείσιμο χρονιάς, προεπιλογές βαθμών, μηνύματα οικογενειών. **Elite.** |
| **Parent** (Family Portal) | Μία είσοδος ανά παιδί | Η εβδομάδα με μια ματιά, εργασίες, πρόοδος, παρουσίες, μηνύματα με το σχολείο. **Pro και Elite.** |

Οι μαθητές δεν συνδέονται. **Βλέπουν το Quest** στην οθόνη της τάξης — σύννεφα, χάρτη, σπίτια, τελετές — ενώ το τρέχεις εσύ.

## Τυπικό μάθημα

Στον υπολογιστή τάξης:

1. **Follow today’s schedule** (ήδη ανοιχτό όταν ανοίγεις την εφαρμογή) ώστε η εφαρμογή να αλλάζει στο τμήμα που έχει μάθημα *τώρα*, ή **General view** όταν δεν υπάρχει μάθημα. Μπορείς πάντα να διαλέξεις τμήμα στο χέρι· τότε το follow σταματά μέχρι να το ξαναπατήσεις.
2. **Award Stars** — Teamwork, Creativity, Respect ή Focus, ένα έως τρία αστέρια. Καλωσόρισε όποιον επιστρέφει. Πρόσεξε γενέθλια. Άσε συμμαθητή να χαρίσει Hero’s Boon όταν προσφέρεται η καρδιά.
3. Προς το τέλος: **Quest Assignment** (εργασία για την επόμενη φορά) και **Attendance** αν δεν έχεις σημειώσει απουσίες.
4. **Crown Today’s Hero** — με ένα πάτημα το Quest στέφει **αυτόματα** τον **Hero of the Day** (δεν διαλέγεις εσύ το όνομα). Μόλις πατήσεις **Huzzah!**, η κάρτα **Today’s Page** ρωτά πώς θα γραφτεί το ημερολόγιο: **Auto** (Elite, ο AI Chronicler), **Manual** (δικά σου λόγια) ή **Later**. Αφού διαλέξεις, το **Gather at the Campfire** (Pro, προαιρετικό) είναι δίλεπτος στοχασμός στον projector για τις λέξεις και τα Ember Oaths.
5. Την κατάλληλη εβδομάδα: **Quiz of the Week** (Home, Elite), **Fortune’s Wheel** (Guild Hall, τελευταίο μάθημα της εβδομάδας), ή ένα παιχνίδι στο **Training Grounds**.

**Όποτε θέλεις μέσα στο μάθημα** μπορείς να πατήσεις **TV** για **Projector Mode**. Είναι **ταπετσαρία** για την οθόνη της αίθουσας (ουρανός, ρολόγια, χρόνος που μένει, κάρτες ιστορίας) — άνοιξέ την όταν βοηθά, άφησέ την να τρέχει όσο διδάσκεις στις συνηθισμένες καρτέλες. Δεν είναι βήμα που πρέπει να γίνει πριν το Award Stars.

Τα αστέρια του βήματος 2 τροφοδοτούν χάρτη, κατάταξη, Guild Glory, Gold, Familiar, Hero Path, και τη μηνιαία τελετή. Τα *γιατί* αυτών των τελετών είναι στο **Γιατί κάνουμε Quest**.

## Οι δέκα καρτέλες

Είναι τα δέκα σύννεφα του **cloud dock** στο κάτω μέρος της οθόνης του δασκάλου (υπολογιστής), με το **Home** πρώτο αριστερά. Οι **Settings** είναι το γρανάζι στην κεφαλίδα, όχι ενδέκατο σύννεφο.

| Καρτέλα | Ρόλος στη χρονιά |
|---------|------------------|
| **Home** | Καιρός, χαιρετισμός, υπενθυμίσεις, συντομεύσεις, Quiz of the Week |
| **Team Quest** | Αγώνας χάρτη τμήμα εναντίον τμήματος αυτόν τον μήνα |
| **Hero’s Challenge** | Κατάταξη μαθητή εναντίον μαθητή, Trophy Room, αρχείο Prodigy |
| **Mystic Market** | Ξόδεμα Gold: power-ups, εποχιακά, αυγά Familiar |
| **Guild Hall** | Σπίτια όλης της χρονιάς, Wheel, Ledger, Analytics |
| **Award Stars** | Η καρδιά κάθε μαθήματος |
| **Adventure Log** | Ημερολόγιο τέλους μαθήματος, Hero of the Day, Hero Campfire, απουσίες, εργασία |
| **Scholar’s Scroll** | Διαγωνίσματα και υπαγορεύσεις |
| **Quest Calendar** | Μαθήματα, αργίες, Quest Events |
| **Training Grounds** | Τέσσερα ομαδικά παιχνίδια, ένα ανά δεξιότητα (μαζί με το Story Weavers) |

**My Classes**, Family Access, Quiz, Hero Path και βαθμοί ζουν στις **Teacher Settings**.

## Πλάνα με μία πρόταση

| Πλάνο | Αίσθηση τάξης |
|------|----------------|
| **Starter** | Αστέρια, οι δύο μηνιαίοι αγώνες, Market power-ups, bounties, Projector, τελετές |
| **Pro** | Σπίτια, ημερολόγιο, Scholar’s Scroll, Adventure Log (χειροκίνητο), Hero Campfire και Ember Oaths, Hero Path, Family Access, Attendance Chronicle |
| **Elite** | AI χρονικογράφος και εικόνες, Training Grounds, Familiars, Quiz of the Week, School Office |

Πλήρης πίνακας: το κεφάλαιο Starter · Pro · Elite στο τέλος του βιβλίου. Κάθε κεφάλαιο τάξης κλείνει με τα ίδια τρία πλάνα, με τα λόγια εκείνου του κεφαλαίου.

## Ονόματα που δεν ανακατεύονται

| Όνομα | Τι είναι πραγματικά |
|------|---------------------|
| **Hero of the Day** | Στέφεται αυτόματα όταν πατάς **Crown Today’s Hero**. Ημερήσιο φως. |
| **Hall of Heroes** | Αρχείο νικών Hero of the Day αυτής της χρονιάς. |
| **Prodigy of the Month** | Μηνιαίος νικητής μαθητή μέσα στην Ceremony of the Month. |
| **Hall of Prodigies** | Αρχείο μηνιαίων Prodigies. |
| **Hero’s Boon** | Συμμαθητής ξοδεύει Gold για **+0.5 αστέρια** (δώρο ομήλικου). |
| **Teacher Boon** | Το δικό σου δώρο **2 αστεριών**, τελευταία εβδομάδα του μήνα. |
| **Guild Champion** | Κορυφαίος *μέσα σε ένα σπίτι* αυτόν τον μήνα. |
| **Grand Guild Ceremony** | Στέψη σπιτιών τέλους χρονιάς. Όχι η μηνιαία τελετή. |

Το γλωσσάρι είναι η πλήρης λίστα. Το **Includes Hero’s Boon (+1)** στον βασιλεύοντα Hero of the Day είναι αυτόματο μπόνους πρώτου αστέρα — όχι το δώρο των 15 Gold.

## Κινητό, σύντομα

Στο κινητό, οι καρτέλες κάθονται σε μια σειρά από πέντε σύννεφα. Οι λεπτομέρειες είναι στο τέλος του κεφαλαίου **Η οθόνη της τάξης** — όχι εδώ.

## Τι ακολουθεί

Άνοιξε **Η οθόνη της τάξης** για την κεφαλίδα, το cloud dock και την ταπετσαρία Projector, μετά **Award Stars** για το ίδιο το μάθημα. Κράτα το **Γιατί κάνουμε Quest** δίπλα σου όποτε ένα όνομα ή τελετή μοιάζει με «ακόμα έναν βαθμό».
`,

  'teacher/03-team-quest.md': `# Team Quest

Το Team Quest είναι **τμήμα εναντίον τμήματος**, μέσα στην ίδια **Quest League**. Δύο Junior B τρέχουν κάθε μήνα ποιος θα τελειώσει πρώτος τον χάρτη. Ο νικητής γιορτάζεται στο πρώτο μισό της **Ceremony of the Month**.

## Σκοπός

Κοινωνική συνοχή. Κανείς δεν μένει μόνος «πρώτος»: κάθε αστέρι κινεί και το πιόνι της τάξης. Ο χάρτης δείχνει σε επτάχρονο «πάμε καλά».

## Τι βλέπεις

- **Λωρίδα league** και επιλογέας αν διδάσκεις περισσότερες.
- Τον **League Map**: την ίδια περγαμηνή με τις τέσσερις ζώνες που βλέπει η τάξη.
- Κάθε τμήμα ως κινούμενο πιόνι. Η θέση είναι **πρόοδος προς τον στόχο του μήνα**, όχι γυμνό άθροισμα.
- Λίστα με αστέρια, στόχο, **επίπεδο δυσκολίας**, ζώνη.
- **History**: ανοίγει το **League Archive**, έναν άτλαντα με τους περασμένους μήνες. Ξεκινά από τον τελευταίο μήνα που έκλεισε, στη league σου (ή **All leagues**). Άλλαξε μήνα με τα βέλη ή πάτα έναν μήνα πάνω στη διακεκομμένη διαδρομή· άλλαξε league με τα chips ή γράψε στο **Find a class**. Το **Your parties** δείχνει πού τερμάτισε κάθε τμήμα σου. Κάθε φύλλο league έχει το λάβαρο του **Month champion**, ένα **διάγραμμα αγώνα** με το σημείο του δρόμου όπου σταμάτησε κάθε τμήμα (ζώνες και σημαία στόχου) και μετά κάθε τμήμα με σημαιάκι θέσης, % του στόχου, αστέρια / στόχο, τη ζώνη που έφτασε ή πόσα αστέρια του έλειψαν, πόσα αστέρια ήθελε για να φτάσει το τμήμα μπροστά, επίπεδο δυσκολίας, "Goal reached" και χαμένες μέρες μαθήματος. Τμήματα χωρίς αστέρια περιμένουν στο **Still at the start line**. Φαίνονται μόνο οι κλεισμένοι μήνες της τρέχουσας σχολικής χρονιάς.
- Υπενθύμιση στο **Home** όταν δεν έχει τρέξει ακόμα η **Ceremony of the Month** του προηγούμενου μήνα· η τελετή ανοίγει από εκεί.

Μόνο τμήματα της **ίδιας Quest League** τρέχουν μεταξύ τους. Το Junior B δεν τρέχει με το C.

### Quest Leagues

Ζώνη ηλικίας / προγράμματος όταν δημιουργείς το τμήμα. **Δεν** είναι guild και **δεν** είναι Hero Path.

Pre-Junior (5–7) · Junior A (7–8) · Junior B (8–9) · A (9–10) · B (10–11) · C (11–12) · D (12–13).

Η πρόοδος ενός τμήματος είναι τα αστέρια του μήνα (μαζί με μπόνους Team Quest όπως το Pathfinder’s Map ή το Quiz) διαιρεμένα με τον στόχο του μήνα. Οι τέσσερις τόποι κάθονται πάνω στον χάρτη, όπως στην τάξη: **Bronze Meadows** από 0%, **Silver Peaks** από 30%, **Golden Citadel** από 60%, **Crystal Realm** από 85%.

Οι θέσεις δεν μοιράζονται: ακόμα και με το ίδιο ποσοστό, κάθε τμήμα παίρνει τη δική του θέση.

## Επίπεδα δυσκολίας

Κάθε τμήμα έχει ένα **επίπεδο quest** που ξεκινά από το **Level 1**. Κάθε φορά που το τμήμα **πιάνει τον στόχο του μήνα**, το επίπεδό του ανεβαίνει κατά ένα, οπότε οι επόμενοι μήνες ζητούν λίγο περισσότερα. Το επίπεδο φαίνεται ως σήμα στην καρτέλα και ως chip στην τελετή (Levels 1–6: 🌱 💧 🛡️ 🔮 🔥 🐉· η ένδειξη σταματά στο 6). Το History και η τελετή δείχνουν το επίπεδο που ίσχυε *εκείνον* τον μήνα, όχι το σημερινό, πιο δύσκολο.

Το επίπεδο δεν έχει σχέση με το Quest League: δύο Junior B μπορούν να έχουν διαφορετικό Level, αν το ένα τέλειωσε τον χάρτη πιο συχνά.

## Πώς μπαίνει ο μηνιαίος στόχος

Δεν τον πληκτρολογείς. Για κάθε μαθητή ο στόχος ξεκινά από **18** αστέρια, συν **2,5** για κάθε επίπεδο πάνω από το Level 1. Το ποσό αυτό προσαρμόζεται για τις αργίες (παρακάτω), πολλαπλασιάζεται με τον αριθμό των μαθητών και στρογγυλοποιείται. Ο στόχος του τμήματος **δεν πέφτει ποτέ κάτω από 18** αστέρια συνολικά.

### Αργίες και ακυρώσεις

**Μέρες που χάνονται** αυτόν τον μήνα υπολογίζονται από δύο πράγματα:

1. Οι μέρες του μήνα που πέφτουν μέσα σε **σχολική αργία**, που ορίζει το School Office στα School Details· **συν**
2. Τα **ακυρωμένα μαθήματα** του τμήματος αυτόν τον μήνα που δεν είναι ήδη μέσα σε αργία (ακυρώνονται από το Day Planner).

**Πόσο μετράει ο μήνας**

- Ο **Ιούνιος** μετράει πάντα ως μισός μήνας (**0,5**), γιατί η σχολική χρονιά τελειώνει.
- Οποιοσδήποτε άλλος μήνας: οι μέρες που μένουν αφού αφαιρεθούν οι μέρες που χάθηκαν, διαιρεμένες με τις μέρες του μήνα, αλλά ποτέ κάτω από 60% και ποτέ πάνω από 100%.

Ένα παράδειγμα (όχι υπόσχεση για συγκεκριμένο τμήμα): 10 μαθητές στο Level 1 σε γεμάτο μήνα έχουν στόχο περίπου **180** αστέρια. Το ίδιο τμήμα στο Level 3 (δύο επίπεδα πιο πάνω) περίπου **230**. Τον Ιούνιο τα νούμερα μισώνουν, και ποτέ δεν πέφτουν κάτω από 18.

## Τι μπορείς να κάνεις

- Να δείτε τον αγώνα στον projector.
- **History** για την περσινή σειρά τερματισμού.
- **Ceremony of the Month** όταν προσφέρεται.
- Διάλεξε τμήμα στην κεφαλίδα για να φωτίζεται το πιόνι μπροστά σου.

Δεν «βαραίνεις το Team Quest» με το χέρι. Τα Award Stars, το Pathfinder’s Map, το Quiz of the Week και κάποια Wheel / γεγονότα προσθέτουν τους αριθμούς για σένα.

## Πώς ταΐζει το υπόλοιπο Quest

| Είσοδος | Αποτέλεσμα |
|---------|------------|
| Αστέρια στο Award Stars | Μηνιαία αστέρια, άθροισμα τμήματος |
| Pathfinder’s Map | **+10** αστέρια τάξης, μία φορά ανά τμήμα ανά μήνα |
| Quiz of the Week | Έξτρα μπόνους ανά επίδοση |
| 2x Star Day | Περισσότερα αστέρια, πιο γρήγορο πιόνι |
| Αργίες / ακυρώσεις | Χαμηλότερος στόχος, δικαιότερος αγώνας |

Το Team Quest **μηδενίζει κάθε ημερολογιακό μήνα**. Το Guild Hall **όχι**.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Χάρτης, Quest League, τίμιος στόχος, Ceremony of the Month | Ο ίδιος χάρτης. Το Guild Hall είναι άλλος, ετήσιος αγώνας | Ο ίδιος χάρτης. Quiz of the Week και κάποια Wheel bonuses μπορούν να προσθέσουν αστέρια quest |
`,

  'teacher/05-ceremony-of-the-month.md': `# Ceremony of the Month

Η Ceremony of the Month διαλέγει μόνη της το σωστό ύφος:

- **Pre-Junior:** **Growth Festival**, μια γλυκιά γιορτή κήπου.
- **Όλες οι άλλες τάξεις:** **Classic Arena**, η γνωστή διπλή τελετή με Team Quest και Hero’s Challenge.

Δεν είναι η Grand Guild Ceremony (Ιούνιος, σπίτια). Δεν είναι Hero of the Day (κάθε καταγεγραμμένο μάθημα).

## Σκοπός

Δημόσιο, μουσικό, δίκαιο κλείσιμο του μήνα. Η δομή λέει: *κερδίσαμε μαζί* και *κάποιος έλαμψε*. Και τα δύο ισχύουν.

## Πότε εμφανίζεται

- Έκλεισε ο **προηγούμενος ημερολογιακός μήνας**.
- Το τμήμα υπήρχε στο τέλος εκείνου του μήνα.
- Δεν έχει ήδη σημειωθεί ολοκληρωμένη τελετή γι’ αυτόν τον μήνα.
- Το Home δείχνει λαμπερή υπενθύμιση· το κουμπί Home στη μπάρα μπορεί να φορά ένα αστεράκι.

Τρέξε την μία φορά ανά τμήμα ανά μήνα, στην αρχή του νέου μήνα, με projector αν μπορείς.

## Τι βλέπεις

Πλήρης οθόνη, φτιαγμένη για τον projector — όχι μικρό αναδυόμενο παράθυρο. Στην πάνω μπάρα υπάρχει **Exit Ceremony** (Esc) και το κουμπί **sound**· σε ευρεία οθόνη φαίνεται και η υπόδειξη **Space** Next. Τα **Space**, **Enter** ή το δεξί βελάκι πατούν το μεγάλο κουμπί. Αν το πατήσεις ενώ παίζει μια αποκάλυψη, πηγαίνει κατευθείαν στο τέλος της.

### Classic Arena

Μια αρένα με πυρσούς το σούρουπο: φεγγάρι, λάβαρα της league, κοινό που ζητωκραυγάζει στις κερκίδες και δύο πυρσοί που καίνε **χρυσοκόκκινοι** για το Team Quest και γίνονται **βιολετί** για το Hero’s Challenge.

**Intro.** Χρυσή ασπίδα με το έμβλημα του τμήματος μέσα σε δάφνινο στεφάνι, **Ceremony of the Month**, ο μήνας, chips για τη Quest League και το τμήμα, και ένας μικρός χάρτης διαδρομής: **Team Quest → Hero’s Challenge**. Πάτα **Start Ceremony**.

**Φάση 1 — Team Quest.** Τα τμήματα της league αποκαλύπτονται **από το χαμηλότερο**. Κάθε θέση έρχεται ως **σφραγισμένη κάρτα**: ένα λάβαρο λέει τη θέση, η κάρτα πέφτει, η βουλοκέρι σφραγίδα σπάει και η κάρτα γυρίζει. Χρυσό, ασημί και χάλκινο έχουν το δικό τους μέταλλο· οι άλλες θέσεις είναι ατσάλι. Η κάρτα δείχνει Stars Collected (μετράνε προς τα πάνω), ετικέτα **Your class**, το μονοπάτι στόχου και chips για **επίπεδο δυσκολίας**, **ζώνη χάρτη**, μέσο όρο αστεριών, **Pathfinder** και **κορυφαία αρετή**. Σε ευρεία οθόνη μια **σκάλα** στο πλάι κρατά όσα τμήματα έχουν ήδη αποκαλυφθεί.

**League Duel.** Οι δύο πρώτοι στέκονται απέναντι ως κρυφές κάρτες **Finalist** με σταυρωμένα σπαθιά, χωρίς σκορ. Πάτα **🥁 Drumroll…**: οι προβολείς πηγαινοέρχονται και σταματούν στον πρωταθλητή, που στέφεται ενώ ο δεύτερος παίρνει το ασημένιο σκαλί. Σε πραγματική ισοπαλία γράφει **Shared Champions!**

**Μετάβαση.** Οι πυρσοί γίνονται βιολετί και η πύλη γράφει **Hero’s Challenge**. Πάτα **Begin Hero’s Challenge**.

**Φάση 2 — Hero’s Challenge.** Μόνο οι μαθητές του επιλεγμένου τμήματος, με τον ίδιο τρόπο, με μετάλλιο-πορτρέτο αντί για έμβλημα. Αν κάποιος έλαβε **Teacher Boon**, η κάρτα του έχει **κορδέλα**: τιμή, όχι θέση. Οι δύο πρώτοι συναντιούνται στο **Hero Duel**· το **Crown the Champion** παίζει τα τύμπανα και στέφει τον **Prodigy of the Month** (ή δύο **Co-Prodigy**).

**Final Standings.** Ένας Roll of Honour με κάθε ήρωα, τα αστέρια του μήνα και τις δυνάμεις του. Αν κανείς δεν πήρε αστέρια, εμφανίζεται **Our Whole Class Quest**. Το **Finish Ceremony** κλείνει τον μήνα· η τελευταία οθόνη λέει **Well fought** στο τμήμα και ονομάζει τα στέμματα.

### Ο κήπος του Growth Festival

Ένας κήπος παραμυθιού σε ηλιόλουστη μέρα: λόφοι, σημαιάκια, σύννεφα, πεταλούδες και ένα παρτέρι στο κάτω μέρος της οθόνης.

**Η πύλη του κήπου.** Αψίδα με τριαντάφυλλα, το έμβλημα του τμήματος, **Growth Festival** και ο μήνας. Το **Enter the Garden 🌸** ανοίγει τις πόρτες.

**Our League Garden.** Μία γλάστρα για κάθε τμήμα, με το έμβλημά του, μια τρυφερή φράση προόδου και την κοινή του δύναμη ως **bloom**. Το τμήμα που οδήγησε τον μήνα φυτρώνει τελευταίο, σε χρυσό φως, ως **League Pathfinder**. Χωρίς αριθμούς.

**Every Garden Grows Together.** Ουράνιο τόξο και ποτιστήρι. Μετά **Begin the Bloom Parade 🌺**.

**Parade of Blooms.** Για κάθε παιδί ένας σπόρος πέφτει, φυτρώνει και ανοίγει σε λουλούδι με το αρχικό του, και μια κάρτα-σακουλάκι σπόρων λέει την όμορφη ιστορία του. Το **Bloom X of Y** και τα βελάκια περνούν τις κάρτες. Με κάθε κάρτα, το λουλουδάκι του παιδιού φυτεύεται στο παρτέρι, οπότε ο κήπος της τάξης γεμίζει όσο προχωρά η παρέλαση.

**The Golden Bloom.** Το μεγαλύτερο μπουμπούκι μεγαλώνει, λάμπει και ανοίγει: **Prodigy of the Month**, ή **Co-Prodigies** δίπλα-δίπλα, ή **Whole Class Garden** όταν δεν υπάρχει ατομικός νικητής. Με το **Finish Ceremony 🌿** ο ήλιος δύει στον κήπο.

### Σε πιο αργά laptop

Η τελετή ελέγχει πόσο γρήγορος είναι ο υπολογιστής. Σε πιο αργό laptop κρατά το σκηνικό ακίνητο (χωρίς τρεμόπαιγμα αστεριών, σύννεφα που κινούνται ή πυρσούς που τρεμοπαίζουν) και βγάζει λιγότερες σπίθες, αλλά κάθε αποκάλυψη παίζει κανονικά. Δεν χρειάζεται καμία ρύθμιση.

## Τι κάνεις (δάσκαλος)

1. Διάλεξε τμήμα στην κεφαλίδα. Το **μισό των τάξεων** είναι όλη η **Quest League**. Το **μισό των μαθητών** είναι μόνο το επιλεγμένο τμήμα.
2. Άνοιξε την τελετή από τη λαμπερή υπενθύμιση στο Home.
3. Intro → **Start Ceremony** (Classic Arena) ή **Enter the Garden 🌸** (Growth Festival).
4. Στο Classic Arena περπάτα τη **Team Quest** με Next, μετά το League Duel.
5. Στο Growth Festival πάτησε **Explore Our Blooms 🌸**, μετά **Begin the Bloom Parade 🌺**, μετά **Next Bloom 🌸** (ή **Reveal Our Golden Bloom ✨** στην τελευταία κάρτα). Τα βέλη δίπλα στο **Bloom X of Y** αλλάζουν κάρτα· το επόμενο βέλος στην τελευταία κάρτα μένει κλειστό ώστε το **Reveal Our Golden Bloom ✨** να ανοίξει το φινάλε. Στο Classic Arena συνέχισε με το **Hero’s Challenge**.
6. **Finish Ceremony**. Πριν από αυτό, ένα refresh ή μια έξοδος απλώς συνεχίζει την αποθηκευμένη τελετή την επόμενη φορά που θα την ανοίξεις.

Εσύ ορίζεις μόνο τον ρυθμό: **Start Ceremony** ή **Enter the Garden 🌸**, μετά το επώνυμο επόμενο κουμπί όταν η τάξη είναι έτοιμη. Δεν χρειάζεται να διαλέξεις λουλούδια, να γράψεις κείμενο ή να ετοιμάσεις βραβεύσεις. Τα σχόλια έχουν ύφος σταδίου, όχι σύσκεψης βαθμολογίας. Στο Elite τα γράφει με περισσότερη φαντασία το AI· η τελετή είναι σε κάθε πλάνο.

## Πώς κρίνονται οι νικητές

### Φάση 1 — Τμήμα (Team Quest)

Το σκορ ενός τμήματος είναι τα αστέρια των μαθητών του μήνα συν τα μπόνους Team Quest, σε σχέση με τον στόχο εκείνου του μήνα (με το επίπεδο και τις αργίες εκείνου του μήνα). Κάθε τμήμα παίρνει τη δική του θέση.

### Φάση 2 — Prodigy (αυτό το τμήμα)

1. Μηνιαία αστέρια
2. Πόσες φορές **3 αστέρια**
3. Πόσες φορές **2 αστέρια**
4. Πόσοι **διαφορετικοί λόγοι** (εύρος αρετής)
5. Ακαδημαϊκός μέσος (αν υπάρχει)

**Co-Prodigy** όταν ταιριάζουν αληθινά τα αστέρια *και* τα 3άρια, τα 2άρια και η ποικιλία των λόγων.

Η κορδέλα **Teacher Boon** δεν προσθέτει κρυφή θέση και δεν σπάει ισοπαλία από μόνη της. Τα 2 αστέρια ήταν ήδη στα σύνολα.

Οι νικητές μπαίνουν στο **Hall of Prodigies** και φαίνονται ως **Prodigy of the Month** (ή **Co-Prodigy** μετά από ισοβαθμία) σε μέντα σύννεφο στο Award Stars, και ως **Reigning Prodigy** στο Hero’s Challenge, μέχρι την επόμενη τελετή. Το finish **δεν** σβήνει αστέρια.

### Αν σταματήσεις στη μέση

Όταν ανοίγει η τελετή, η εφαρμογή υπολογίζει αθόρυβα τα αποτελέσματα του μήνα και τα αποθηκεύει. Δεν χρειάζεται να επιλέξεις ή να γράψεις τίποτα. Αν γίνει refresh ή βγεις στη μέση, ανοίγοντας ξανά την τελετή από το Home συνεχίζεις από εκεί που σταμάτησες, με τα ίδια αποτελέσματα. Μόλις πατήσεις **Finish Ceremony**, ο μήνας κλείνει γι’ αυτό το τμήμα και η υπενθύμιση φεύγει.

### Growth Festival (Pre-Junior)

Η πρώτη φάση είναι το **Our League Garden**. Τα τμήματα εμφανίζονται στην οθόνη σε ήρεμη, δίκαιη σειρά, το καθένα με το έμβλημά του, μια απλή περιγραφή της πορείας του και μια κοινή δύναμη — ποτέ αριθμητική θέση ή σκορ. Το τμήμα που οδήγησε τον μήνα αποκαλύπτεται τελευταίο ως **League Pathfinder** (ή **Our League Pathfinder** όταν είναι το μοναδικό). Δεν υπάρχει duel: η μετάβαση γράφει **Every Garden Grows Together**.

Ακολουθεί η **Parade of Blooms**: μία ζεστή κάρτα για κάθε παιδί, που διαλέγεται αυτόματα, μαζί με το παιδί που θα ονομαστεί Prodigy. Η τελική αποκάλυψη είναι το **Golden Bloom — Prodigy of the Month** (ή δύο Golden Blooms για Co-Prodigies). Αν ο μήνας δεν έχει θετική αναγνώριση, το φινάλε είναι το **Whole Class Garden**, όχι ένας φτιαχτός νικητής. Όλα τα παιδιά μαζεύονται γύρω από το έμβλημα της τάξης στον κήπο που κλείνει την τελετή.

Οι κάρτες δεν δείχνουν ποτέ θέσεις, αστέρια, βαθμούς, ασημένια/χάλκινα μετάλλια, συγκρίσεις με άλλα παιδιά ή τις ιδιωτικές σου σημειώσεις. Οι γονείς δεν βλέπουν πίνακα κατάταξης ούτε σημειώσεις της τελετής.

**Πώς διαλέγεται η κάρτα κάθε παιδιού.** Το Growth Festival δεν χρησιμοποιεί ποτέ αποτελέσματα διαγωνισμάτων ή υπαγορεύσεων. Για κάθε παιδί η εφαρμογή παίρνει το πρώτο από τα παρακάτω που ταιριάζει:

1. **Teacher’s Special Bloom** — το παιδί πήρε Teacher Boon.
2. **Growing Stronger** — το παιδί παρακολούθησε τουλάχιστον δύο μαθήματα μέσα στον τρέχοντα και τον προηγούμενο μήνα και κερδίζει πλέον σαφώς περισσότερα θετικά αστέρια ανά μάθημα από πριν (τουλάχιστον 20% και 0,25 αστέρια περισσότερα), με ενδείξεις σε δύο ημερομηνίες αυτού του μήνα.
3. **Rainbow of Strengths** — το παιδί αναγνωρίστηκε για τουλάχιστον τρεις από τις Teamwork, Creativity, Respect και Focus.
4. **Steady Little Light** — το παιδί πήρε θετική απονομή σε τουλάχιστον 60% από τρία ή περισσότερα μαθήματα που παρακολούθησε.
5. **Η ισχυρότερη αρετή του** — η αρετή για την οποία αναγνωρίστηκε συχνότερα, με τουλάχιστον δύο θετικές στιγμές. Αν δύο αρετές ισοβαθμούν, η εφαρμογή διαλέγει δίκαια μία.
6. **A Special Part of Our Garden** — μια ζεστή κάρτα που απλώς περιλαμβάνει το παιδί όταν δεν αρκούν τα στοιχεία για τις άλλες. Δεν παρουσιάζεται ποτέ ως επίτευγμα.

Μετρούν μόνο τα μαθήματα που παρακολούθησε το παιδί· οι καταγεγραμμένες απουσίες μένουν έξω και δεν παρουσιάζονται ποτέ ως αδυναμία. Αν ένα παιδί άλλαξε τμήμα, η αναγνώριση μένει στο τμήμα όπου κερδήθηκε. Αν τα αρχεία παρουσιών είναι πολύ ελλιπή για μια δίκαιη εικόνα, η εφαρμογή απλώς διαλέγει άλλη ζεστή κάρτα.

Αυτή η τελετή **δεν** είναι:

- **Grand Guild Ceremony** (Ιούνιος, Guild Hall)
- **Hero of the Day** (Adventure Log)
- **Guild Champion** (μέσα σε ένα σπίτι)

## Αξιοπρέπεια στην αίθουσα

- Μην προσπερνάς τις χαμηλότερες θέσεις στον projector.
- Μην προσθέτεις «ένα αστέρι ακόμα» αφού έκλεισε ο μήνας.
- Πες τα Co-Prodigy δυνατά όταν η εφαρμογή δείχνει δύο στέμματα.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Διπλή τελετή: Team Quest, μετά Prodigy | Οι ίδιες δύο φάσεις | Πλουσιότερος AI σχολιασμός. Οι δύο φάσεις δεν εξαρτώνται από το Elite |
`,

  'teacher/01-classroom-chrome.md': `# Η οθόνη της τάξης: κεφαλίδα, Projector Mode, καιρός, κινητό

Αυτό το κεφάλαιο είναι ό,τι βρίσκεται **γύρω** από τις δέκα καρτέλες: η κορυφή της οθόνης, το cloud dock στο κάτω μέρος, η τηλεόραση της αίθουσας, ο ουρανός, και πώς νιώθει το ίδιο Quest στο κινητό.

Η διεπαφή δασκάλου είναι φτιαγμένη για **υπολογιστή τάξης**. Χρησιμοποίησε το κινητό όταν περπατάς στην αίθουσα ή καλύπτεις μάθημα μακριά από την έδρα. Το Projector Mode μένει στη μεγάλη οθόνη.

## Σκοπός

Να δώσει στην αίθουσα ζωντανή ατμόσφαιρα (ώρα, καιρός, μια γραμμή σοφίας της ημέρας) και πρόσβαση με ένα άγγιγμα στο τμήμα, στον οδηγό του παιχνιδιού, στον projector και στις Teacher Settings — χωρίς να φύγεις από το μάθημα.

## Τι βλέπεις (κεφαλίδα υπολογιστή)

Από αριστερά προς τα δεξιά:

| Κομμάτι | Τι κάνει |
|-------|----------------|
| **Τίτλος** | «The Great Class Quest» |
| **Φράση ημέρας** | Μια σύντομη εμπνευσμένη φράση, καινούργια κάθε μέρα, που δεν επαναλαμβάνει πρόσφατες φράσεις. Την ίδια φράση βλέπει όλο το σχολείο. Αν η φράση της ημέρας δεν μπορεί να δημιουργηθεί, εμφανίζεται μία από 60 έτοιμες. Στον υπολογιστή εμφανίζεται στην κεφαλίδα· στο κινητό μεταφέρεται σε κάρτα **Daily Wisdom** στο Home. |
| **Ημερομηνία και ζωντανό ρολόι** | Πάντα ορατά. Τα χρώματα **μέρας / νύχτας** ακολουθούν την πραγματική ανατολή και δύση εκεί που βρίσκεται το σχολείο. |
| **Επιλογέας τμήματος** | Το **Follow today’s schedule** είναι το προεπιλεγμένο όταν ανοίγεις την εφαρμογή: αλλάζει αυτόματα στο τμήμα που έχει μάθημα, και γυρίζει στο **General view** όταν δεν υπάρχει μάθημα. Μπορείς ακόμα να διαλέξεις στο χέρι **General view** ή ένα τμήμα — τότε το follow σταματά μέχρι να ξαναπατήσεις Follow today’s schedule. Σχεδόν κάθε καρτέλα ακολουθεί αυτή την επιλογή. |
| **Πληροφορίες** (i) | Ανοίγει το **The Adventurer’s Guide**, έναν οδηγό τσέπης για το Quest (δες παρακάτω). Οι νέοι δάσκαλοι τον βλέπουν μία φορά, στο κεφάλαιο **Start here**. |
| **Projector Mode** (εικονίδιο TV) | Προβολή τάξης σε πλήρη οθόνη. Δεν υπάρχει στην κεφαλίδα του κινητού. |
| **School Office** (ασπίδα) | Μόνο όταν το σχολείο έχει πρόσβαση Secretary (Elite). Ανοίγει το School Office. |
| **Settings** (γρανάζι) | **Teacher Settings** (τμήματα, εργαλεία μαθητολογίου, Family Access, ρύθμιση Quiz, και άλλα). |
| **Αποσύνδεση** | Σε αποσυνδέει από αυτή τη συσκευή. |

Πίσω από την κεφαλίδα περνούν ζωγραφιστά **σύννεφα**. Πόσα είναι και πόσο γρήγορα κινούνται ακολουθεί την πραγματική νεφοκάλυψη και τον άνεμο έξω. Το χρώμα του ουρανού ακολουθεί το φως: ροζ την αυγή, γαλάζιο τη μέρα, χρυσό πριν τη δύση, μωβ το σούρουπο, έναστρο τη νύχτα. Με ζωντανό καιρό βρέχει, χιονίζει, πέφτει ομίχλη, χαλάζι ή καταιγίδα· μετά από μπόρα μπορεί να βγει ουράνιο τόξο, και η παγωμένη βροχή κρεμάει παγοκρυστάλλους στην κεφαλίδα. Σε πιο αργό laptop ο ουρανός ζωγραφίζει λιγότερα σύννεφα ώστε το μάθημα να μένει ομαλό.

Το **Sky Theater** είναι ένα ήσυχο έξτρα: κάθε τόσο μικροί «επισκέπτες» emoji πετούν πάνω από την κεφαλίδα (πύραυλος τη Δευτέρα, κουκουβάγια την Τετάρτη, δράκος το Σάββατο, κ.ο.κ.). Είναι μόνο διακόσμηση και σταματούν αν η συσκευή ζητά μειωμένη κίνηση.

Ένα **update pill** μπορεί να εμφανιστεί όταν είναι έτοιμη νέα έκδοση της εφαρμογής.

### The Adventurer’s Guide (i)

Ένας οδηγός πεδίου δεμένος σε πράσινο ύφασμα, με μπρούντζινη πυξίδα στο εξώφυλλο και ένα ταμπελάκι με το πλάνο σου. Δίνει τη σύντομη απάντηση στο «τι είναι αυτό και πού βρίσκεται;». Αυτό το βιβλίο είναι η μεγάλη απάντηση.

- **Καρτέλες κεφαλαίων** στο πλάι, η καθεμία με το χρώμα της: **Start here** (ένα μάθημα από την αρχή ως το τέλος, οι τρεις αγώνες και ονόματα που δεν πρέπει να μπερδεύεις), Stars in the lesson, The three races, Gold and the Market, Heroes and identity, End of the lesson, Learning and records, Screens and settings, Families and the Office και Your plan.
- Κάθε λήμμα είναι μια **σημείωση πεδίου**: πού βρίσκεται η λειτουργία, τι κάνει και γιατί μετρά.
- Το **Search the guide** ψάχνει σε όλα τα λήμματα. Πάτα **/** για να πας κατευθείαν στην αναζήτηση.
- Το **Take me there** κλείνει τον οδηγό και ανοίγει εκείνη την καρτέλα ή την ενότητα των Settings. Ό,τι δεν περιλαμβάνει το πλάνο σου έχει λουκέτο και λέει ποιο πλάνο το ξεκλειδώνει.
- Το **For the class** δείχνει μια παιδική εκδοχή με μεγάλα γράμματα, φτιαγμένη για τον projector: Welcome, hero, Earning stars, Our races, Gold and treasures, Your hero και Class adventures. Το **Quest Master** γυρίζει πίσω.
- Θυμάται το κεφάλαιο που διάβαζες. Κλείνει με **Esc**, ✕ ή ένα κλικ έξω από αυτόν.
- Στο κινητό, το **Game Guide** τον ανοίγει ως φύλλο, με τα κεφάλαια σε μια λωρίδα που κυλά.

## Το cloud dock (κάτω πλοήγηση)

Οι δέκα καρτέλες ζουν σε ένα **cloud dock** κατά μήκος της κάτω άκρης της οθόνης: ένα απαλό, χρωματιστό σύννεφο για κάθε καρτέλα, που επικαλύπτονται σε μία συνεχή σειρά. Κάθε σύννεφο έχει το εικονίδιο της καρτέλας του — το **Home** είναι το πρώτο σύννεφο αριστερά, μετά Team Quest, Hero’s Challenge, Mystic Market, Guild Hall, Award Stars, Adventure Log, Scholar’s Scroll, Quest Calendar και Training Grounds. Το σύννεφο όπου βρίσκεσαι λάμπει, σηκώνει το εικονίδιό του και δείχνει το όνομα της καρτέλας· δείξε με τον δείκτη οποιοδήποτε άλλο σύννεφο για να δεις το όνομά του. Οι **Settings** δεν είναι σύννεφο: μένουν το **γρανάζι** στην κεφαλίδα.

Σε υπολογιστή με ποντίκι, τα σύννεφα **βυθίζονται και χάνονται** λίγα δευτερόλεπτα αφού ο δείκτης φύγει από το κάτω μέρος της οθόνης, ώστε το μάθημα να έχει όλη την οθόνη. Φέρε τον δείκτη στην **κάτω άκρη** και ξαναβγαίνουν. Σε οθόνη αφής δεν κρύβονται ποτέ, και ένα άγγιγμα κοντά στο κάτω μέρος ή η εστίαση πληκτρολογίου σε ένα σύννεφο τα φέρνει πάντα πίσω. Το Projector Mode χρησιμοποιεί το ίδιο dock.

Όποια καρτέλα κι αν ανοίξεις, ξεκινά πάντα **από την κορυφή** — ποτέ στη μέση, εκεί όπου είχε κυλήσει η προηγούμενη καρτέλα.

## Τίτλοι καρτελών

Κάθε καρτέλα ανοίγει με έναν τίτλο σχεδιασμένο ως **δικό της αντικείμενο** αντί για απλή επικεφαλίδα: διπλωμένος χάρτης αποστολής για το Team Quest, βασιλικό λάβαρο για το Hero’s Challenge, πέτρινη αψίδα για το Guild Hall, μετάλλιο με αστέρι σε νυχτερινό ουρανό για το Award Stars, ραμμένο δερμάτινο ημερολόγιο για το Adventure Log, περγαμηνή για το Scholar’s Scroll, επιτραπέζιο ημερολόγιο με κρίκους για το Quest Calendar, ξύλινη πινακίδα προπονητηρίου με τέσσερα σημαιάκια για το Training Grounds, και μαυροπίνακας για τις Teacher Settings. Μόνο το **Mystic Market** κρατά ταμπέλα μαγαζιού. Το Team Quest και το Hero’s Challenge έχουν επίσης μια επίχρυση κορδέλα μήνα που γράφει *this month’s race* ή *this month’s challenge*. Οι τίτλοι είναι διακόσμηση· δεν πατιούνται.

## Projector Mode (ταπετσαρία αίθουσας)

Πάτα το **TV** στην κεφαλίδα (μόνο στον υπολογιστή τάξης — δεν υπάρχει Projector στο κινητό του δασκάλου). Το Quest γεμίζει την οθόνη: μια ζωντανή **ταπετσαρία ουρανού** πίσω από ένα τεράστιο ρολόι.

Άνοιξέ το **όποτε βοηθά το μάθημα** — αγγλικά στον πίνακα, παιδιά που κοιτάζουν ψηλά για αντίστροφη μέτρηση, ήρεμη ατμόσφαιρα στο pair work. Δεν είναι βήμα που πρέπει να γίνει πριν το Award Stars. Άφησέ το να τρέχει στην τηλεόραση ή στον projector της αίθουσας, ενώ εσύ χρησιμοποιείς το Award Stars, το Market και τις τελετές στη δική σου οθόνη. Η ταπετσαρία είναι για **να δείχνει**, όχι για να πατάς κάθε μαθητή.

Η ταπετσαρία ανοίγει με ένα σύντομο εφέ και διπλώνει πίσω με τον ίδιο τρόπο όταν φεύγεις: μέσα από την κάρτα χαιρετισμού στο Home, ή σαν κύκλος που μεγαλώνει από το κουμπί **TV** σε οποιαδήποτε άλλη καρτέλα.

Έξοδος με **Esc** ή το κουμπί **power** στο τηλεχειριστήριο πάνω δεξιά.

### Τι βλέπει η αίθουσα

- **Ουρανός.** Ακολουθεί την **πραγματική ανατολή και δύση** για την τοποθεσία καιρού του σχολείου. Μέρα: ήλιος και φωτεινός ουρανός. Νύχτα: φεγγάρι και έναστρος ουρανός. Τα ίδια σύννεφα, η βροχή, το χιόνι, η ομίχλη, το χαλάζι και οι αστραπές της κεφαλίδας, στο μέγεθος της μεγάλης οθόνης, ακολουθούν τον ζωντανό καιρό όταν έχει οριστεί τοποθεσία.
- **Το βασίλειο στον ορίζοντα.** Λόφοι και ένα μικρό κάστρο με σημαία. Τη νύχτα τα παράθυρα φωτίζονται· με χιόνι οι λόφοι ασπρίζουν.
- **Το κέντρο με τα ρολόγια.** Γυάλινο πάνελ με το **τόξο της μέρας** επάνω (ο ήλιος ταξιδεύει από την ανατολή στη δύση, το φεγγάρι τη νύχτα), το **τεράστιο ψηφιακό ρολόι**, την ημερομηνία και το **αναλογικό ρολόι**.
- **Δαχτυλίδι μαθήματος.** Όταν γίνεται μάθημα, το παράθυρό του σχεδιάζεται πάνω στο αναλογικό ρολόι και γεμίζει χρυσό όσο προχωρά. Από κάτω γράφει **Lesson ends in … min**· τα τελευταία 10 λεπτά γίνεται ροζ και πάλλεται.
- **Κορδέλα τμήματος** όταν έχει επιλεγεί τμήμα: έμβλημα, όνομα και Quest League.
- **Κορδέλα σοφίας** κάτω: η φράση της ημέρας. Κρύβεται από το Sky Deck.
- **Sky Cards.** Οι κάρτες **αλλάζουν περίπου κάθε λεπτό** (ή με τον ρυθμό που διαλέγεις), ώστε η ταπετσαρία να μη βαρεθεί ποτέ. Το κομμάτι της εφαρμογής που τις διαλέγει λέγεται **The Director**· φτιάχνει τη μίξη από το αν έχεις επιλέξει τμήμα, πόσο έχει προχωρήσει το μάθημα και το πλάνο σου.

### Sky Cards

Κάθε καρτέλα έχει το ίδιο σχήμα: **έμβλημα** με το emoji της σε κορδέλα, το όνομα της **οικογένειας**, τον **τίτλο**, το περιεχόμενο και μια λεπτή **μπάρα χρόνου** κάτω που αδειάζει σιγά σιγά μέχρι την επόμενη. Κάθε οικογένεια έχει το χρώμα της:

| Οικογένεια | Χρώμα | Τι έχει |
|--------|--------|---------------|
| **Hall of Heroes** | Χρυσό | Προβολές μαθητών, πρόσφατα αστέρια, γενέθλια, Star of the Week, αστέρια της ημέρας, first light, rising star, virtue champions, name poems |
| **Class Quest** | Μπλε | Πρόοδος Team Quest, θησαυροφυλάκιο, σερί, bounties, ζώνη χάρτη, Familiars, ιστορία, το star trail, ο αστερισμός και ο μήνας μέχρι τώρα του τμήματος |
| **Time & Tides** | Ροζ | Lesson Timekeeper, επόμενο μάθημα, αργίες, διαγωνίσματα, η πορεία της σχολικής χρονιάς, η διαδρομή της εβδομάδας, το ημερολόγιο του μήνα, ρολόγια του κόσμου |
| **Word Workshop** | Τιρκουάζ | Αγγλικά από το μάθημα του τμήματος, λέξεις, φράσεις, ορθογραφία και παιχνίδια λέξεων |
| **Puzzle Nook** | Ματζέντα | Αινίγματα, μαθηματικά, True or False, Odd one out, Letter hunt, Quick draw, μοτίβα, κρυπτογράφηση, Who am I?, Simon says |
| **Wonders** | Λουλακί | Γεγονότα, ιστορία, επιστήμη, μύθοι, ονομαστικές γιορτές, ζώα, χώρες, διάστημα, εφευρέσεις |
| **Mind & Heart** | Πράσινο | Mindfulness, υγιεινές συνήθειες, Would you rather, δημιουργικές ιδέες, αναπνοές, ευγνωμοσύνη, αποστολές καλοσύνης, διαλείμματα για τέντωμα |
| **Sky Watch** | Γαλάζιο | Ζωντανός καιρός, το φεγγάρι απόψε, φως της ημέρας, η εποχή, ο αστερισμός της βραδιάς, ο πλανήτης της εβδομάδας |
| **The Realm** | Βιολετί | Όλο το σχολείο: παλμός, θησαυροφυλάκιο, κορυφαία τμήματα, κατάταξη guild, αστέρια της ημέρας, λάβαρα των guild |

Ο Director έχει περίπου **160 είδη καρτών** στις εννέα οικογένειες. Οι κάρτες που διαβάζουν τα δεδομένα του τμήματος εμφανίζονται μόνο όταν έχουν κάτι αληθινό να δείξουν, οπότε ένα καινούριο τμήμα βλέπει περισσότερα παιχνίδια και θαύματα μέχρι να έρθουν τα πρώτα του αστέρια.

Οι καρτέλες με απάντηση (αινίγματα, True or False, Odd one out, Spell it right, Quiz rewind, Word scramble, τα παιχνίδια λέξεων και τα νέα puzzles) την κρατούν **θολή** και γράφουν **Answer in 0:38**. Η απάντηση καθαρίζει σιγά σιγά και είναι ευκρινής τα τελευταία 10 δευτερόλεπτα. Κλικ πάνω στην καρτέλα ή **R** για να φανεί νωρίτερα.

### Το τηλεχειριστήριο

Κούνησε το ποντίκι και εμφανίζεται πάνω δεξιά ένα μικρό τηλεχειριστήριο. Σβήνει μαζί με τον κέρσορα μετά από λίγα δευτερόλεπτα ησυχίας.

- **⏮ Προηγούμενη** (**←**) φέρνει πίσω την καρτέλα που μόλις πέρασε.
- **📌 Καρφίτσωμα** (**Space**) κρατά την καρτέλα στον ουρανό μέχρι να το ξαναπατήσεις.
- **⏭ Επόμενη** (**→**) φέρνει αμέσως καινούρια καρτέλα.
- **Sky Deck** (**D**), **πλήρης οθόνη** (**F**) και **power** (**Esc**).

### Το Sky Deck

Οι ρυθμίσεις μένουν σε αυτόν τον υπολογιστή τάξης.

- **Οικογένειες.** Πάτα μια οικογένεια για να την κλείσεις ή να την ανοίξεις. Γενέθλια και το τέλος ενός timer bounty περνούν πάντα. Αν κλείσεις όλες, επιστρέφει ολόκληρη η τράπουλα.
- **Κάθε καρτέλα μένει** 30 δευτερόλεπτα, 1, 2 ή 5 λεπτά.
- **Κορδέλα σοφίας** ανοιχτή ή κλειστή.

Το **Sky Theater** (μικρές πτήσεις emoji στην *κεφαλίδα*) είναι άλλο παιχνίδι. Δεν είναι Projector Mode.

### Χρόνος που απομένει (όταν είναι χρήσιμος)

Η ταπετσαρία δεν είναι άδεια αφίσα. Λέει στην αίθουσα πόσο κρατούν τα πράγματα — αλλά μόνο όταν αυτά τα ρολόγια είναι πραγματικά:

- Κάρτα **Lesson Timekeeper**: λεπτά **μέχρι το προγραμματισμένο τέλος του μαθήματος** αυτού του τμήματος (ο αναλογικός δακτύλιος αδειάζει καθώς τελειώνει το μάθημα). Εμφανίζεται όταν έχει επιλεγεί τμήμα, το τμήμα έχει ώρα λήξης, και μένουν ακόμα **1–120 λεπτά**. Δεν θα δείξει ξεχασμένο χρονόμετρο από χθες.
- Κάρτα **Next Adventure**: η **επόμενη προγραμματισμένη ημέρα μαθήματος** και η ώρα έναρξης γι’ αυτό το τμήμα.
- **Bounty timer pill** (πάνω αριστερά): αν τρέχει bounty **Race the Clock** για το επιλεγμένο τμήμα, μια ζωντανή αντίστροφη μέτρηση κάθεται στην ταπετσαρία. Το εικονίδιο είναι ήρεμο, μετά προειδοποιεί (⏳), μετά καίει (🔥) στα τελευταία δευτερόλεπτα. Όταν μηδενίσει, μια μεγάλη καρτέλα **Time’s Up!** παίρνει το κέντρο για οκτώ δευτερόλεπτα και μετά ο ουρανός συνεχίζει κανονικά. Το **Time Warp Hourglass** προσθέτει **+5 λεπτά** στην ίδια αντίστροφη μέτρηση (και στον πίνακα bounties στην κορυφή της οθόνης σου).
- Αντίστροφη μέτρηση **αργίας** και **προ-αργιακός ενθουσιασμός** όταν μια σχολική αργία απέχει λιγότερο από μια εβδομάδα.
- Αντίστροφη μέτρηση **επερχόμενου διαγωνίσματος** (Scholar’s Scroll, Pro) όταν έχει προγραμματιστεί γραπτό τις επόμενες επτά μέρες — και επιπλέον κάρτες «καλής τύχης» αν το διαγώνισμα είναι **σήμερα**.
- **Our year of adventure**: πόσο από τη σχολική χρονιά έχετε διανύσει, μήνα με μήνα.

### Τι δείχνουν οι κάρτες

Οι κάρτες εναλλάσσονται. Ο Director αποφεύγει να δείξει το ίδιο *είδος* κάρτας δύο φορές στη σειρά. Γενέθλια και ονομαστικές γιορτές **προηγούνται** ώστε η αίθουσα να επευφημήσει.

**Περισσότερες κάρτες τμήματος**: **Stars so far today** (σύνολο και βάθρο των τριών πρώτων της ημέρας), **Star of the Week** (τα περισσότερα αστέρια τις τελευταίες 7 μέρες) και **Birthday coming up**. Μαζί τους, κάρτες που διαβάζουν το ημερολόγιο αστεριών, το μαθητολόγιο και το πρόγραμμα του τμήματος:

- **First light**: ο πρώτος ήρωας που κέρδισε αστέρι σήμερα, με την ώρα και τον λόγο
- **Rising star**: το παιδί που ανέβηκε περισσότερο αυτή την εβδομάδα σε σχέση με την προηγούμενη
- **Almost there!**: ένας ήρωας που απέχει ένα έως τρία αστέρια από έναν στρογγυλό αριθμό αυτόν τον μήνα
- **Virtue champions**: ο κορυφαίος ήρωας του μήνα σε Teamwork, Creativity, Respect και Focus
- **Steady flame**: ο ήρωας που κέρδισε αστέρια στις περισσότερες διαφορετικές μέρες του μήνα
- **Kindness spotted**: το πιο πρόσφατο αστέρι Respect, Teamwork ή Hero’s Boon των δύο τελευταίων εβδομάδων
- **Γενέθλια του μήνα** και ένα **Name poem** (ακροστιχίδα με το μικρό όνομα ενός παιδιού)
- **Our star trail** (αστέρια ανά μάθημα αυτόν τον μήνα), **Our best lesson this month**, **Where our stars came from** (ένας τροχός αρετών), **Our class constellation** (κάθε ήρωας ένα αστέρι, πιο λαμπερό όσο περισσότερα αστέρια έχει), **Every hero counts** (πόσα παιδιά έχουν κερδίσει αστέρια αυτόν τον μήνα), **Our guilds this month** και **Month so far**
- **This week’s path** (οι μέρες μαθήματος αυτής της εβδομάδας) και ένα **ημερολόγιο του μήνα** που σημειώνει τις μέρες μαθήματος με αστέρια και τις αργίες

**Με επιλεγμένο τμήμα** συνήθως βλέπεις: πρόοδο Team Quest (ποσοστό προς τον χάρτη του μήνα, μαζί με το μπόνους Pathfinder), θησαυροφυλάκιο τμήματος (Gold), παρουσίες / «heroes assembled», σερί «super days» (μαθήματα με περισσότερα από 5 αστέρια), ζώνη χάρτη, πώς στέκεται το τμήμα σε σχέση με το σχολείο, κορυφαίο Gold στο τμήμα, **reigning Hero of the Day** (Pro), τελευταία γραμμή Story Weavers (Elite), παρέλαση Familiar / αναμονή εκκόλαψης (Elite), ποιος λείπει, προβολές μόνο **παρόντων** μαθητών, πρόσφατα αστέρια, και πρόσφατες εικόνες περιπέτειας.

**Σε όλο το σχολείο** (ή ανακατεμένα): παλμός σχολείου, θησαυροφυλάκιο σχολείου, κορυφαίοι ήρωες, ενεργά bounties, **ζωντανός καιρός** (θερμοκρασία, μέγιστη και ελάχιστη), **το φεγγάρι απόψε**, **φως της ημέρας** (ανατολή, δύση, πόσο φως μένει), **η εποχή**, επόμενη αργία, ελληνική ονομαστική γιορτή, ορθόδοξο εορτολόγιο, κατάταξη guild (Pro, με την ίδια σειρά όπως στο Guild Hall: Crowns και Glory ανά μέλος αυτού του μήνα), **The school today** (αστέρια σε όλο το σχολείο σήμερα), **Brightest classes** του μήνα, **το βασίλειο σε αριθμούς**, **Guild banners** (τα αστέρια κάθε guild αυτόν τον μήνα), **Weekend watch** (πόσοι ύπνοι μέχρι το Σαββατοκύριακο), **Around the English-speaking world** (τέσσερα ρολόγια πόλεων και τι κάνουν εκεί οι άνθρωποι), **Tonight’s constellation**, **The turning year** (μέρες μέχρι την επόμενη εποχή), **Planet of the week**, και — στο Elite — γεγονότα, αστεία, αινίγματα, ιδιωματισμοί, γλωσσοδέτες και σπαζοκεφαλιές. Πρωί, απόγευμα, Δευτέρα και Παρασκευή γέρνουν λίγο τη μίξη.

**Κάρτες εκμάθησης αγγλικών** μπαίνουν στη μίξη και έρχονται από το ίδιο το μάθημα του τμήματος:

- **Today we are learning**: θέματα και λέξεις από το What we learned today
- **Quiz rewind** (Elite): μια ερώτηση που έχασε το τμήμα στο τελευταίο Quiz of the Week, με την απάντηση να αποκαλύπτεται σιγά σιγά
- **Word scramble**: μία από τις λέξεις του τμήματος, με ανακατεμένα γράμματα
- **Story recall** (Elite): η τελευταία γραμμή Story Weavers με τη Word of the Day να λείπει
- **Next quest**: η εργασία από το Quest Assignment
- **Growth Starfall** (Pro): ένα παιδί που ανέβηκε αρκετά πάνω από τον δικό του μέσο όρο αυτή την εβδομάδα (μόνο όνομα, χωρίς βαθμούς)
- Σε κάθε πλάνο, ανάλογα με τη league: **Finish the sentence**, **Think · Pair · Share**, **Grammar nugget**, **Say it right** (ελάχιστα ζεύγη όπως *ship/sheep*, όχι για Pre-Junior), και **Classroom English**
- **Γρήγορα παιχνίδια** σε κάθε πλάνο, ανάλογα με τη league: **True or False?**, **Odd one out**, **Spell it right**, **Letter hunt** (πες πέντε … που αρχίζουν από ένα γράμμα πριν αδειάσει η μπάρα), **Quick draw** (ζωγράφισε και περίγραψε στα Αγγλικά) και **Would you rather…**
- **Παιχνίδια λέξεων** σε κάθε πλάνο, ανάλογα με τη league: **Opposites**, **Rhyme time**, **Word maths** (δύο λέξεις φτιάχνουν μια καινούρια), **One… two…** (πληθυντικοί που δεν παίρνουν απλώς -s), **Say what?** (ένας ιδιωματισμός για να μαντέψετε), **Emoji translator** (πες την πρόταση των emoji στα Αγγλικά) και **Words inside words**
- **Puzzles** σε κάθε πλάνο: **What comes next?**, **Quick count**, **Code breaker** (A = 1, B = 2 …), **Who am I?** και **Simon says**
- **Θαύματα και ήρεμα διαλείμματα** σε κάθε πλάνο: ένα **ζώο**, μια **χώρα όπου μιλούν Αγγλικά**, ένα **θαύμα του διαστήματος**, **Who invented it?**, **Bubble breathing**, μια **Thankful moment**, **Today’s kindness quest** και ένα **Stretch break**

Οι κάρτες αιωρούνται στον ελεύθερο χώρο γύρω από το ρολόι. Δεν καλύπτουν ποτέ το κέντρο με τα ρολόγια, την κορδέλα τμήματος, την κορδέλα σοφίας ή το τηλεχειριστήριο, και μικραίνουν αντί να βγουν έξω σε μικρότερη οθόνη projector.

Τα πρώτα ~20 λεπτά του μαθήματος ευνοούν μια πιο ήρεμη μίξη «ανοίγματος»· μετά τα ~70 λεπτά η μίξη χαλαρώνει (mindfulness, συμβουλές μελέτης, μια ματιά στην εποχή).

Αν έχεις επιλέξει **Follow today’s schedule** ή ένα τμήμα, η ταπετσαρία είναι η ιστορία *εκείνου* του τμήματος. Το **General view** γέρνει προς όλο το σχολείο.

### Πώς το τρέχεις στην αίθουσα

1. Στον υπολογιστή τάξης, το Follow today’s schedule είναι ήδη ανοιχτό (ή διάλεξε τμήμα).
2. Πάτα **TV**. Επίτρεψε πλήρη οθόνη αν τη ζητήσει ο browser.
3. Στείλε αυτό το παράθυρο (cast / HDMI) στην οθόνη της αίθουσας.
4. Δίδαξε στις συνηθισμένες καρτέλες. Η TV κρατά τον ουρανό, τα ρολόγια και τις κάρτες. Θέλεις μια κάρτα να μείνει για συζήτηση; Κούνησε το ποντίκι και πάτα **📌** (ή **Space**).
5. Όταν μετρά ένα bounty ή το ρολόι του μαθήματος, κοίτα ψηλά — τα παιδιά το βλέπουν ήδη.

Μην προσπαθείς να δώσεις αστέρια *πάνω* στην ταπετσαρία. Γύρνα στο Award Stars γι’ αυτό.

## Ζωντανός καιρός και μέρα / νύχτα

Ο καιρός δεν είναι παιχνίδι. Δένει την τάξη με το πραγματικό πρωινό έξω.

- Η κάρτα καιρού στο **Home** είναι ένα μικρό παράθυρο στον ίδιο ουρανό: δικά της σύννεφα και βροχή ή χιόνι, ένα ζωγραφιστό εικονίδιο καιρού (με την πραγματική φάση του φεγγαριού τη νύχτα), θερμοκρασία και συνθήκες, μέγιστη / ελάχιστη, τον **άνεμο** (ταχύτητα και από πού φυσάει) και τις **επόμενες ώρες** με την πιθανότητα βροχής.
- Η **κεφαλίδα**, ο ουρανός του **Award Stars** και ο **Projector** μοιράζονται έναν ουρανό: ο αριθμός των σύννεφων ακολουθεί την πραγματική νεφοκάλυψη, ο άνεμος ορίζει την ταχύτητα, την κατεύθυνση και την κλίση της βροχής, και το φως αλλάζει από αυγή σε μέρα, χρυσή ώρα, σούρουπο και νύχτα.
- Ο καιρός ελέγχεται ξανά κάθε λίγα λεπτά όσο η εφαρμογή είναι ανοιχτή, ώστε μια μπόρα που ξεκινά μέσα στο μάθημα να φτάνει στον ουρανό.
- Η τοποθεσία του καιρού ορίζεται μία φορά για όλο το σχολείο, στο School Office (School Details, Elite). Αν δεν έχει οριστεί, ο ουρανός εξακολουθεί να αλλάζει μέρα/νύχτα από το ρολόι.

Το **Award Stars** αποκτά επίσης έναν καθηλωτικό ουρανό μετά από λίγο στην καρτέλα: ο ουρανός της κεφαλίδας απλώνεται προς τα κάτω πίσω από τα σύννεφα και διπλώνει πάλι όταν φεύγεις. Τα αστέρια φαίνονται μόνο όσο το επιτρέπει η πραγματική νεφοκάλυψη, και το φεγγάρι δείχνει τη σημερινή του φάση.

## Ήχοι και μικρές λιχουδιές

Τα αστέρια, το Gold, το Market, η εκκόλαψη/εξέλιξη Familiar, το Quiz και οι τελετές έχουν ο καθένας τους ήχους του. Κράτα τους ανοιχτούς· τα παιδιά διαβάζουν την αίθουσα από τον ήχο όσο και από την οθόνη.

Άλλες ήσυχες λιχουδιές που θα συναντήσεις σε αυτόν τον οδηγό:

- Πλωτά **σύννεφα μαθητών** στο Award Stars
- **Ύμνοι guild** (στίχοι σε χρόνο karaoke) στο Guild Hall
- **Μουσική τελετής** και τύμπανα
- Κινούμενα **Familiar** δίπλα στα avatars

## Κινητό: διάταξη δασκάλου

| Υπολογιστής | Κινητό |
|---------|--------|
| Cloud dock δέκα σύννεφων (βυθίζεται όταν δεν το χρησιμοποιείς) | Μια σειρά από **πέντε σύννεφα** που μένει πάντα στη θέση της: Home, Team Quest, Hero’s Challenge, Award Stars, **More**. Το σύννεφο της ανοιχτής καρτέλας σηκώνεται και λάμπει |
| Φράση στην κεφαλίδα | **Daily Wisdom** στο Home |
| Κάρτα χαιρετισμού με λόφους και day ring | Οι ίδιοι ζωγραφιστοί λόφοι και το ζωντανό **day ring** γύρω από το λογότυπο του τμήματος, στην κορυφή του Home |
| Κουμπί Projector TV | **Χωρίς Projector** |
| Dropdown τμήματος | Πάτα το **έμβλημα τμήματος** στην κεφαλίδα (γράφει *On schedule* όταν ακολουθεί το πρόγραμμα της ημέρας) για να ανοίξει το **φύλλο επιλογής τμήματος** |
| Γρανάζι Settings στην κεφαλίδα· **dropdown** ενοτήτων μέσα στις Settings | Game Guide (i) και γρανάζι Settings στην κεφαλίδα του κινητού· οι ενότητες των Settings επιλέγονται από ένα **φύλλο**, η καθεμία με τη σύντομη περιγραφή της |
| Log out στην κεφαλίδα | Το **Log out** βρίσκεται στο κάτω μέρος του φύλλου **More**, δίπλα στο **Game Guide**, ώστε να μην πατιέται κατά λάθος |

Το **More** ανοίγει ένα φύλλο με πλακίδια-σύννεφα: Mystic Market, Guild Hall, Adventure Log, Scholar’s Scroll, Quest Calendar, Training Grounds, Student Roster, School Office (αν επιτρέπεται), και Settings. Όσο είναι ανοιχτή μία από αυτές τις καρτέλες, το σύννεφο **More** παίρνει το χρώμα, το εικονίδιο και το σύντομο όνομά της (π.χ. *Market*), με τρεις μικρές τελείες που δείχνουν ότι ανοίγει ακόμη το φύλλο.

Το **φύλλο επιλογής τμήματος** δείχνει κάθε τμήμα σου με τις μέρες και την ώρα του, ετικέτα **Today** όταν έχει μάθημα σήμερα και **In session** όσο γίνεται το μάθημα. Το **Follow today’s schedule** είναι διακόπτης στην κορυφή· ένα τικ σημειώνει το τμήμα που βλέπεις.

Κάθε φύλλο στο κινητό (More, επιλογή τμήματος, ενότητες Settings) κλείνει με το ✕, με ένα πάτημα έξω από αυτό, ή σέρνοντας τη λαβή του προς τα κάτω.

Το κινητό είναι το ίδιο Quest. Προτίμησε τον υπολογιστή όποτε η τάξη πρέπει να *δει* τον κόσμο: Projector, τελετές, τα λάβαρα του Guild Hall, αποκάλυψη Story Weavers.

## Πώς τροφοδοτεί το υπόλοιπο Quest

Το **τμήμα στην κεφαλίδα** ορίζει ποια παιδιά βλέπεις στο Award Stars, στο Market, στο Fortune’s Wheel, στο Adventure Log, στο Scholar’s Scroll, στο Calendar, στο Training Grounds και στο Home. Αν είναι επιλεγμένο λάθος τμήμα, θα δεις λάθος παιδιά. Το **Follow today’s schedule** είναι το προεπιλεγμένο όταν ανοίγεις την εφαρμογή: το τμήμα που έχει μάθημα, ή General view ανάμεσα στα μαθήματα.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Κεφαλίδα, ρολόι, Follow today’s schedule, Guide, ταπετσαρία Projector, ουρανοί καιρού, Sky Theater | Κάρτες Guild, log και Hero Path στην ταπετσαρία όταν αυτά τα features είναι ανοιχτά | Sky Cards γραμμένες από AI (γεγονότα, αστεία, αινίγματα). Ασπίδα School Office όταν υπάρχει Secretary |
`,

  'teacher/02-home.md': `# Home

Το Home είναι το **κέντρο διοίκησης**. Αλλάζει με το τμήμα στην κεφαλίδα, τον καιρό και την ώρα της ημέρας.

## Σκοπός

Να δεις το σχολείο (ή αυτό το τμήμα) με μια ματιά, να πιάσεις τις υπενθυμίσεις πριν χτυπήσει το κουδούνι, να πας στην επόμενη τελετή, και — στο Elite — να παίξεις **Quiz of the Week**.

## Τι βλέπεις

Ο χαιρετισμός ακολουθεί τον πραγματικό ήλιο: **Good Morning** μέχρι το μεσημέρι, **Good Afternoon** μέχρι τις 5 μ.μ., **Good Evening** από τις 5 μ.μ. μέχρι τη δύση, και **Good Night** από τη δύση μέχρι την ανατολή. Πίσω του, ένα ζωγραφιστό τοπίο με λόφους, κυπαρίσσια και ένα μικρό σπιτάκι αλλάζει χρώμα μέσα στη μέρα, με αστέρια το βράδυ και τη νύχτα.

Το λογότυπο του τμήματος (ή 🏫 στο General view) βρίσκεται μέσα σε ένα **δαχτυλίδι μέρας/νύχτας**: ένα καντράν 24 ωρών με το μεσημέρι πάνω και τα μεσάνυχτα κάτω. Η μέρα είναι βαμμένη ανάμεσα στην πραγματική σημερινή ανατολή και δύση, και η νυχτερινή πλευρά είναι έναστρος ουρανός. Ο ήλιος (ή, μετά τη δύση, το φεγγάρι στη σημερινή του φάση) ταξιδεύει γύρω στο δαχτυλίδι και δείχνει την ώρα τώρα. Κάθε φορά που ανοίγεις το Home το δαχτυλίδι κάνει ένα μικρό σόου μέχρι να σταθεί στην τρέχουσα ώρα. Πέρασε τον δείκτη από πάνω του για να δεις τις σημερινές ώρες ανατολής και δύσης.

Τα chips κάτω από τον χαιρετισμό δείχνουν το σχολείο και είτε το επιλεγμένο τμήμα και τη league του είτε πόσα τμήματα έχουν μάθημα σήμερα (και πόσα είναι δικά σου). Τα σήματα υπενθύμισης δίπλα τους μοιάζουν όλα: ένα εικονίδιο, μια μικρή ετικέτα, ένας τίτλος και μια ένδειξη «πότε».

Η **κάρτα καιρού** είναι ένα μικρό παράθυρο στον πραγματικό ουρανό: σύννεφα που περνούν, με βροχή, χιόνι ή αστραπές όταν τα έχει ο καιρός, ένα εικονίδιο καιρού (το φεγγάρι στην πραγματική του φάση τη νύχτα), ένα μικρό αναλογικό ρολόι, η θερμοκρασία και οι συνθήκες, η μέγιστη και η ελάχιστη της ημέρας, ο άνεμος, και οι επόμενες τέσσερις ώρες με την πιθανότητα βροχής.

### General view (χωρίς επιλεγμένο τμήμα)

Βλέπεις **όλο το σχολείο**:

- **School Stars** — τα μηνιαία αστέρια όλων των μαθητών
- **Heroes** — πόσοι μαθητές είναι στο μαθητολόγιο
- **Treasury** — το Gold αυτής της χρονιάς που έχουν οι μαθητές. Το Gold της περσινής χρονιάς αρχειοθετείται όταν κλείσει η σχολική χρονιά, οπότε μια νέα χρονιά ξεκινά από 0.
- **Global Tools** — συντομεύσεις που η κάτω μπάρα και το γρανάζι δεν φτάνουν με ένα κλικ, η καθεμία με ζωντανή υπόδειξη: **Plan Today** (ημερολόγιο Pro· δείχνει πόσα δικά σου μαθήματα έχεις σήμερα), **New Class** (δείχνει πόσα τμήματα έχεις), **Quiz of the Week** (Elite), **Family Access** (κωδικοί γονέων), **Hero Archive** και **Team Archive** (κατατάξεις προηγούμενων μηνών). Σε πακέτα χωρίς κάποια από αυτά, τη θέση τους παίρνουν τα **Student Fixes** (διόρθωση αστεριών ή χρυσού) και **Last Lessons** (τελευταίες μέρες μαθημάτων).
- **Σημερινό πρόγραμμα σχολείου** — κάθε τμήμα που έχει μάθημα σήμερα. Ένα στέμμα σημαδεύει τα δικά σου, ένα μάτι του συναδέλφου, και μια πράσινη τελεία μάθημα σε εξέλιξη. Πάτα **οποιοδήποτε** τμήμα για να ανοίξεις το **class roster** του, που δείχνει:
  - league, δάσκαλο, ώρα και ημέρες, και πόσοι είναι οι ήρωες·
  - αστέρια αυτού του μήνα και όλης της χρονιάς, Gold, πρόοδο Team Quest και το επόμενο μάθημα·
  - τον τελευταίο Hero of the Day, το τελευταίο Quest Assignment και Adventure Log·
  - σημερινά γενέθλια και ονομαστικές γιορτές, και τη μίξη των guild·
  - βάθρο 3 κορυφαίων «Stars of the month» (ποτέ για Pre-Junior)·
  - κάθε μαθητή με τίτλο Hero Path, guild, αστέρια και Gold (αναζήτηση ή ταξινόμηση A–Z / κατά αστέρια).
- **Grand Guild Ceremony** — εμφανίζεται όταν είναι ώρα να στεφθεί το νικητήριο guild της χρονιάς (δες Guild Hall)

**Πάτα έναν μαθητή** σε ένα roster για να ανοίξει η όψη ήρωα: αστέρια μήνα και χρονιάς, Gold, τίτλος Hero Path, guild, τα αστέρια του μήνα ανά αρετή (Teamwork / Creativity / Respect / Focus), τα πέντε τελευταία αστέρια και μια κάρτα **Boons**. Η κάρτα Boons λέει αν το Teacher Boon (+2★, ένας ήρωας ανά τμήμα ανά μήνα, μόνο τις τελευταίες 7 μέρες του μήνα) δεν έχει ανοίξει ακόμα, είναι ανοιχτό τώρα ή έχει ήδη δοθεί (και σε ποιον), και μετρά όσα Hero’s Boons (δώρα συμμαθητών, +0,5★) πήρε ο μαθητής αυτόν τον μήνα. Στα δικά σου τμήματα η όψη ήρωα προσθέτει σύνοψη Scholar’s Scroll και κουμπί **Give Teacher Boon** όσο είναι ανοιχτό το παράθυρο, και το roster έχει τα κουμπιά **Enter class**, **Award Stars** και **Edit class**. Το τμήμα συναδέλφου είναι μόνο για προβολή. Το Esc σε γυρίζει από τον ήρωα στο roster. Στο κινητό, ένα δικό σου τμήμα ανοίγει απευθείας· το τμήμα συναδέλφου ανοίγει το roster μόνο για προβολή.

### Όψη τμήματος (επιλεγμένο τμήμα)

Βλέπεις **αυτή την ομάδα**:

- Κουμπί **Bounty** στο πάνελ χαιρετισμού: ανοίγει την αφίσα **Post a Bounty** γι’ αυτό το τμήμα (παρακάτω)
- **Reminder pills** στην κορυφή: γενέθλια, ονομαστικές γιορτές, προγραμματισμένα διαγωνίσματα, μια λαμπερή **Ceremony of the Month** που περιμένει να τρέξει (ποτέ για τον Αύγουστο — το σχολείο είναι κλειστό), ενεργό bounty, μπόνους Pathfinder, και παρόμοιες σημειώσεις «κάν’ το σήμερα»
- **Quest progress**: τα μηνιαία αστέρια του τμήματος απέναντι στον στόχο του Team Quest (ο στόχος ήδη υπολογίζει αργίες και ακυρωμένα μαθήματα), σαν δρόμος που περνά από τα τέσσερα βασίλεια του Team Quest (Bronze Meadows, Silver Peaks, Golden Citadel, Crystal Realm) μέχρι τη σημαία του στόχου. Το έμβλημα του τμήματος στέκεται εκεί που βρίσκεται τώρα η τάξη, τα βασίλεια που έχει ήδη φτάσει φωτίζονται, και μια γραμμή λέει πόσα αστέρια λείπουν για το επόμενο βασίλειο. Όποιο μπόνους Pathfinder υπάρχει μετράει και φαίνεται κάτω από τον στόχο.
- **Class virtue και φωτογραφία της τάξης**: ένα έμβλημα για την αρετή που έχει φέρει στην τάξη τα περισσότερα αστέρια (ή **Ready to Quest!** πριν από τα πρώτα αστέρια), μια κορδέλα που δείχνει πώς μοιράζονται τα αστέρια ανάμεσα στις αρετές, και όλοι οι ήρωες στο λιβάδι σαν σε φωτογραφία τάξης. Πέρασε τον δείκτη πάνω από έναν ήρωα για το όνομα και τα αστέρια του μήνα· πάτησε για να ανοίξει το Hero Stage. Ένα μικρό βέλος δείχνει skill Hero Path σε αναμονή και ένα χρυσό αστέρι δείχνει ποιος έχει τα περισσότερα αστέρια αυτόν τον μήνα.
- **The Chronicle** — η τελευταία εργασία, γραμμή Story Weavers ή πρόταση του Adventure Log
- **Ενέργειες τμήματος** — τα ίδια πλακίδια με τα Global Tools, μόνο για αυτό το τμήμα και χωρίς να επαναλαμβάνουν την κάτω μπάρα: **Roll Call** (δείχνει ποιοι λείπουν σήμερα), **Class Roster** (ήρωες, αστέρια και χρυσός), **Class Report** (σύνοψη προόδου με AI), **Edit Class** και **Prodigies** (προηγούμενοι Prodigies of the Month). Την τελευταία εβδομάδα του μήνα μπαίνει πρώτο το **Teacher Boon** και δείχνει σε ποιον δόθηκε.
- **Quiz of the Week** στην κάρτα καιρού όταν το τμήμα δικαιούται (Elite)

## Τι μπορείς να κάνεις

- Άλλαξε τμήμα από την κεφαλίδα· το Home ξαναζωγραφίζεται αμέσως. Το άνοιγμα της εφαρμογής ξεκινά σε **Follow today’s schedule** (το τμήμα που έχει μάθημα, ή General view όταν δεν υπάρχει μάθημα). Αν διαλέξεις **Enter class** σε ένα roster του προγράμματος, αυτό το τμήμα μένει καρφωμένο μέχρι να ξαναπατήσεις Follow today’s schedule.
- Άνοιξε τον προορισμό ενός reminder pill (τελετή, bounty, διαγώνισμα).
- Ανέβασε ένα **Quest Bounty** γι’ αυτό το τμήμα με το κουμπί **Bounty**.
- Χρησιμοποίησε τα Global Tools ή τις ενέργειες τμήματος αντί να ψάχνεις στις καρτέλες.
- Ξεκίνα το **Quiz of the Week** όταν προσφέρεται το κουμπί αναπαραγωγής (παρακάτω).
- Τη μέρα της τελετής των guild, ξεκίνα το **Grand Guild Ceremony** από το Home.

## Ανέβασμα ενός Quest Bounty

Ένα bounty είναι πρόκληση **όλου του τμήματος**, ποτέ «ποιος μαθητής πρώτος». Πάτα **Bounty** στο πάνελ χαιρετισμού του τμήματος και ανοίγει μια **αφίσα bounty** σε σκισμένη περγαμηνή, αναρτημένη για το επιλεγμένο τμήμα. Διάλεξε το είδος του bounty στην κορυφή (η αφίσα θυμάται την τελευταία σου επιλογή):

- **Star Hunt** — κερδίστε μαζί αστέρια για να κερδίσετε ένα έπαθλο. Δώσε όνομα στην αποστολή (ή πάτα μία από τις ιδέες· τίτλοι και έπαθλα που έχεις ξαναχρησιμοποιήσει με αυτό το τμήμα εμφανίζονται πρώτα, με ένα μικρό βελάκι επιστροφής). Στο **Stars to earn**, πάτα **Quick win**, **Fair fight** (προεπιλεγμένο) ή **Heroic**: οι αριθμοί βγαίνουν από το πόσα αστέρια κερδίζει συνήθως αυτό το τμήμα σε ένα μάθημα, και μπορείς ακόμα να ανεβάσεις ή να κατεβάσεις τον αριθμό. Μετά γράψε ή πάτα **The reward** (για παράδειγμα 5 min free time ή a class game). Τα αστέρια μετρούν από τη στιγμή που καρφώνεται το bounty, για δύο ώρες.
- **Race the Clock** — τελειώστε μια εργασία πριν τελειώσει ο χρόνος. Δώσε όνομα στην εργασία, μετά διάλεξε **5, 10, 15, 20 ή 30 min**, γράψε δικά σου λεπτά, ή όρισε ώρα **Ends at**. Όταν το τμήμα έχει προγραμματισμένη ώρα λήξης σήμερα, ένα chip **Until the bell** βάζει την αντίστροφη μέτρηση μέχρι το τέλος του μαθήματος.

Μια σύνοψη μιας γραμμής στο κάτω μέρος διαβάζει το bounty με απλά λόγια (για παράδειγμα «When 4A earns 12 stars for English Only, they win 5 min free time.»), και η αφίσα σου λέει αν υπάρχει ήδη bounty στον πίνακα (το νέο τρέχει δίπλα του). Αν κάτι λείπει, η αφίσα το τονίζει. Τελείωσε με **Pin it to the board** (Star Hunt) ή **Start the clock** (Race the Clock), ή **Not now** για να κλείσεις.

Τα ζωντανά bounties κάθονται στον πίνακα bounties στην κορυφή της οθόνης και στην ταπετσαρία του Projector· το **Time Warp Hourglass** προσθέτει πέντε λεπτά στις αντίστροφες μετρήσεις που τρέχουν.

## Quiz of the Week (Elite)

Το Quiz of the Week είναι **ζωντανή επανάληψη σε στυλ τηλεπαιχνιδιού**, όχι γραπτό διαγώνισμα. Δεν αντικαθιστά το Scholar’s Scroll.

### Πριν το μάθημα (Teacher Settings → Quiz)

1. Διάλεξε το τμήμα στην κεφαλίδα.
2. Αν έχεις αποθηκεύσει Quest Assignments για αυτό το τμήμα, το Step 2 δείχνει ήδη **τα μαθήματα αυτής της εβδομάδας** — τις ενότητες, τη γραμματική και τις λέξεις που εξασκήθηκαν από το τελευταίο ολοκληρωμένο Quiz of the Week (ή την περασμένη εβδομάδα, αν το τμήμα δεν έχει παίξει ποτέ). Ξετσέκαρε μια λέξη για να τη βγάλεις, άλλαξε Grammar / Mix / Vocabulary αν θέλεις, ή πρόσθεσε μια σύντομη σημείωση. Το **Generate from this week's lessons** γράφει τις ερωτήσεις πολλαπλής επιλογής από αυτή τη λίστα, και το AI μένει σε αυτές τις λέξεις.
3. Αν δεν υπάρχει ακόμα ιστορικό βιβλίου, διαλέγεις πάλι **grammar**, **vocabulary** ή **mix**, μαζί με chips θεμάτων και προαιρετικές λέξεις-κλειδιά, και μετά Generate.
4. Ο αριθμός των ερωτήσεων κλιμακώνεται με το μέγεθος του τμήματος (περίπου τα τρία τέταρτα του μαθητολογίου, τουλάχιστον 5, το πολύ 15).
5. Μπορείς να κάνεις επαναφορά και να ξαναδημιουργήσεις αν το σετ δεν ταιριάζει σε αυτή την εβδομάδα.
6. Το **Different focus** ανοίγει τα γενικά chips θεμάτων (grammar, vocabulary και mix) για όταν θέλεις να διαλέξεις μόνος σου το θέμα.
7. **Optional extras** (Step 3, και τα δύο κλειστά αν δεν τα τσεκάρεις· η εφαρμογή θυμάται την επιλογή σου ανά τμήμα):
   - **Review the questions before they go live.** Το quiz περιμένει ως **In review** και το κουμπί αναπαραγωγής μένει κρυφό μέχρι να πατήσεις **Approve & make live**. Στο παράθυρο ελέγχου μπορείς να επεξεργαστείς οποιαδήποτε ερώτηση, τις τέσσερις απαντήσεις της, τη σωστή απάντηση και τη σύντομη εξήγηση, ή να διαγράψεις μια ερώτηση (ένα quiz κρατά τουλάχιστον 3). Ένα quiz που είναι ήδη έτοιμο μπορεί επίσης να ανοίξει με **Review & edit questions** οποιαδήποτε στιγμή πριν παιχτεί.
   - **Bring back questions the class missed last week.** Η εφαρμογή απαριθμεί κάθε ερώτηση από το τελευταίο ολοκληρωμένο quiz που απαντήθηκε λάθος με την πρώτη ή παραλείφθηκε, με την απάντηση που διάλεξαν τα περισσότερα παιδιά. Τσέκαρε όσες θέλεις να επιστρέψουν: παίρνουν τις πρώτες θέσεις στο νέο quiz (οι απαντήσεις τους ανακατεύονται), και το AI γράφει μόνο τις υπόλοιπες. Αυτό είναι επανάληψη σε διαστήματα πάνω σε πραγματικά αδύναμα σημεία.

### Όταν εμφανίζεται στο Home

Ένα φωτεινό εισιτήριο **Quiz of the Week** (με τον αριθμό των ερωτήσεων και **Play**) εμφανίζεται στην κάρτα καιρού του **Home του τμήματος** όταν:

- το σχολείο είναι σε **Elite**,
- υπάρχει quiz γι’ αυτή την εβδομάδα και είναι **ready**,
- είναι η **πρώτη ημέρα μαθήματος αυτής της εβδομάδας** για το τμήμα,
- είσαι **μέσα στην ώρα του μαθήματος**,
- και υπάρχουν μαθητές για να επιλεγούν.

Αν το quiz είναι ήδη **completed**, το εισιτήριο γίνεται πράσινο και γράφει **See the results** για την υπόλοιπη εβδομάδα. Αν ακόμα δημιουργείται, ή είναι λάθος μέρα, το κουμπί αναπαραγωγής μένει μακριά — σκόπιμα, ώστε η τελετή να μένει ξεχωριστή.

### Πώς παίζεται

Το quiz ανοίγει ως **σκηνή τηλεπαιχνιδιού**, φτιαγμένη για τον προβολέα. Η πρώτη οθόνη δείχνει πόσες ερωτήσεις υπάρχουν, τους ήρωες που είναι σήμερα στη σκηνή (όσοι σημειώθηκαν απόντες μένουν έξω) και τους τρεις κανόνες. Πάτα **Raise the curtain** για να ξεκινήσει.

- **Ο προβολέας διαλέγει έναν ήρωα** για κάθε ερώτηση. Τα ονόματα τρεμοπαίζουν για λίγο και μετά σταματούν σε ένα παιδί. Η επιλογή είναι δίκαιη, όχι τύχη: πρώτα καλούνται τα παιδιά που δεν απάντησαν στα πρόσφατα quiz, και κανείς δεν παίρνει δεύτερη σειρά πριν πάρουν όλοι οι παρόντες μία.
- **Απάντησε A, B, C ή D.** Μπορείς να πατήσεις με το ποντίκι ή τα πλήκτρα **1** έως **4**· το **Enter** προχωρά.
- **Μια λάθος απάντηση περνά την ερώτηση παρακάτω.** Η απάντηση που δοκιμάστηκε διαγράφεται, και ο προβολέας διαλέγει άλλο παιδί για την ίδια ερώτηση. Αν δεν τη βρει κανείς, η σκηνή δείχνει τη σωστή απάντηση και τη σύντομη εξήγησή της.
- Το **Skip question** υπάρχει όταν μια ερώτηση δεν πρέπει να παιχτεί.
- Τα **φωτάκια στην κορυφή** δείχνουν πώς πήγε κάθε ερώτηση: χρυσό για σωστό με την πρώτη, πράσινο για λύση μετά από πάσα, κόκκινο όταν δεν τη βρήκε κανείς. Ο μετρητής με το αστέρι δίπλα τους μετρά τις σωστές με την πρώτη.
- Το **Pause** (το κουμπί πάνω δεξιά ή το **Esc**) κρατά την παράσταση εκεί που είναι. Άνοιξε ξανά το quiz από το Home για να συνεχίσεις· αν ξαναφορτώσεις τη σελίδα, ξεκινά από την αρχή.

Στο τέλος οι κριτές μετρούν, και η **υπόκλιση (curtain call)** δείχνει το μετάλλιο επιπέδου του τμήματος, την ακρίβεια πρώτης προσπάθειας, τα αστέρια που δόθηκαν και το μπόνους Team Quest, τους **πρωταγωνιστές** με ό,τι κέρδισε ο καθένας, το **Glory για τα guild**, τον **Quiz Champion** και τον θησαυρό του, και μια **ανασκόπηση κάθε ερώτησης** με την απάντησή της. Ένα πάτημα στην οθόνη παραλείπει την αποκάλυψη. Για την υπόλοιπη εβδομάδα, το **See the results** στο Home ανοίγει ξανά την ίδια οθόνη.

Οι ανταμοιβές δίνονται αυτόματα, μία φορά, όταν τελειώσει η παράσταση. Κάθε παιδί ανταμείβεται για **τις δικές του απαντήσεις**, ποτέ για το πώς τα πήγε το υπόλοιπο τμήμα:

| Τι έγινε | Ανταμοιβή |
|----------|-----------|
| Σωστό με την πρώτη | **1 αστέρι** |
| Έσωσε μια ερώτηση που έχασε άλλος | **½ αστέρι** |
| Πήρε σειρά, δεν πέτυχε | **+1 Gold** για το θάρρος |
| Δεν κλήθηκε αυτή την εβδομάδα | Τίποτα αυτή τη φορά· ο προβολέας το καλεί πρώτο την επόμενη |

- **Το πολύ 2 αστέρια από ένα quiz**, ώστε ένα παιδί που έτυχε να κληθεί πιο συχνά να μη φύγει μπροστά.
- **Κάθε αστέρι δίνει 1 Gold** και **2 Guild Glory**, όπως κάθε άλλο αστέρι. Δεν υπάρχει επιπλέον Glory.
- Η **ακρίβεια πρώτης προσπάθειας** του τμήματος ορίζει το επίπεδο και ένα **μπόνους Team Quest** για όλο το τμήμα: Legendary (100%) +3, Epic (80%+) +2, Rare (60%+) +1, Common (40%+) +½, Heroic (κάτω από 40%) κανένα.

**Ένας Quiz Champion** κερδίζει δωρεάν **έναν θησαυρό από το Mystic Market**. Champion είναι το παιδί με τους περισσότερους πόντους (2 για κάθε πρώτη προσπάθεια, 1 για κάθε διάσωση) και χρειάζεται τουλάχιστον μία σωστή με την πρώτη. Στην ισοπαλία κερδίζει όποιο παιδί έχει πάρει τα λιγότερα βραβεία quiz φέτος, και μετά όποιο έκανε λιγότερα λάθη. Ο θησαυρός βγαίνει από **τον πάγκο αυτού του μήνα της league του τμήματος** (ή τον πάγκο της γιορτής) και φεύγει από το απόθεμα, όπως σε μια αγορά: το τελευταίο κομμάτι φεύγει από το ράφι. Είναι κοινός θησαυρός, ή σπάνιος όταν το τμήμα έφτασε Epic ή Legendary. Αν ο πάγκος είναι άδειος, ο champion παίρνει **10 Gold**.

Ρύθμιση στις Settings· **παιχνίδι στο Home**. Μην ψάχνεις καρτέλα Quiz στο cloud dock — δεν υπάρχει.

## Πώς τροφοδοτεί το υπόλοιπο Quest

Το Home δεν δίνει αστέρια από μόνο του. Σε **κατευθύνει**: Award Stars, Adventure Log, Scholar’s Scroll, Calendar, Story Weavers, τελετές. Οι ανταμοιβές του Quiz *προσθέτουν* όμως αστέρια, Gold, μπόνους Team Quest και Glory, άρα μετράνε πραγματικά — απλώς δεν αντικαθιστούν τις τέσσερις αρετές στο Award Stars.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Πίνακας Home, καιρός, χαιρετισμοί, στατιστικά σχολείου και τμήματος, Quest Bounties | Συντόμευση ημερήσιου planner από το Home. Κάλεσμα Grand Guild Ceremony όταν πλησιάζει η τελετή τέλους χρονιάς | Quiz of the Week |
`,

  'teacher/04-heros-challenge.md': `# Hero’s Challenge

Μαθητής εναντίον μαθητή. Το μηνιαίο στέμμα είναι **Prodigy of the Month** στο **Hall of Prodigies**. Το Gold δεν κατεβάζει θέσεις. Δεν είναι πίνακας σπιτιών — τα εμβλήματα guild στις γραμμές είναι ταυτότητα.

## Σκοπός

Προσωπική ευθύνη δίπλα στον αγώνα του τμήματος. Το παιδί που δείχνει σταθερά τις τέσσερις αρετές βλέπει το όνομά του να ανεβαίνει. Το παιδί με ήσυχο μήνα ανήκει ακόμα σε νικητήριο Team Quest.

## Τι βλέπεις

Πίνακας **μαθητή προς μαθητή**, όχι σπιτιών. Η μπάρα **Quest League** κάτω από το λάβαρο του μήνα έχει την επιλογή league, δύο διακόπτες και **History**: **By Class** / **Global Rank** (στο By Class πρώτα τα δικά σου τμήματα), **Monthly Stars** / **Total Stars**.

Κάθε τμήμα ανοίγει με ένα **βάθρο**: βελούδινη σκηνή όπου οι τρεις πρώτοι στέκονται σε χρυσό, ασημένιο και χάλκινο βάθρο, με στέμμα πάνω από τον πρώτο και πόσο προηγείται. Στο βάθρο ανεβαίνουν μόνο ήρωες με αστέρια. Οι υπόλοιποι ακολουθούν σε γραμμές με ασπίδα θέσης, μπάρα με τα αστέρια τους σε σχέση με τον πρώτο και πόσα αστέρια χρειάζονται για να φτάσουν τον από πάνω. Κάθε ήρωας: avatar, αστέρια, Gold, Familiar (Elite), έμβλημα guild, τίτλος Hero Path, αύρα από επίπεδο 3, **Reigning Prodigy**, **Guild Champion** όταν ισχύει.

**Οι αλλαγές θέσεων ζωντανεύουν.** Ο πίνακας θυμάται τι έδειξε τελευταία φορά αυτή η συσκευή. Όταν γυρίζεις μετά από αστέρια (ή όταν έρχονται αστέρια με την καρτέλα ανοιχτή), ένα λάβαρο λέει τι έγινε από την τελευταία σου ματιά, τα αστέρια μετράνε προς τα πάνω εκεί που ήταν ο κάθε ήρωας και μετά όλοι γλιστράνε στη νέα τους θέση. Όποιος ανεβαίνει λάμπει χρυσό, ο νέος πρώτος παίρνει το στέμμα, και μικρά σημάδια **▲ / ▼** και **+N** μένουν σε κάθε ήρωα μέχρι να φύγεις από την καρτέλα.

Ιπτάμενα κουμπιά: **Hall of Prodigies** και **Trophy Room**.

### Trophy Room

Η συλλογή του μαθητή: εποχιακοί θησαυροί, αχρησιμοποίητα Legendary Artifacts, και θέση να **χρησιμοποιήσει** ένα power-up.

### Hall of Prodigies

Μια φωτεινή μαρμάρινη αίθουσα κάτω από ένα βιτρό ροζέτα. Κάθε **ολοκληρωμένος μήνας** τιμά τον **Prodigy of the Month** του: το στέμμα κατεβαίνει σε ένα μετάλλιο με δάφνες, το όνομα χαράζεται σε πλάκα με χρυσό περίγραμμα μαζί με έναν τίτλο (**Ancient Sage**, **Learned Hero** ή **Heroic Spirit**, από τα γραπτά του μήνα), και τέσσερις πλάκες δείχνουν τα αστέρια του μήνα, **πόσες φορές στέφθηκε φέτος**, τους διαφορετικούς λόγους επαίνου και τις απονομές 3★ ή περισσότερων. Από κάτω φαίνονται οι θησαυροί του μαθητή από το Mystic Market. Η κατάταξη είναι ίδια με της τελετής, οπότε όταν οι πρώτοι μαθητές ταιριάζουν αληθινά, κάθε **Co-Prodigy** παίρνει τη δική του αψίδα.

Άλλαξε μήνα με τα βέλη δίπλα στο όνομα του μήνα ή πάτα ένα νόμισμα στο **This year's crowns** στο κάτω μέρος: χρυσό νόμισμα με το πορτρέτο του Prodigy για κάθε μήνα με στέμμα, άδειο νόμισμα για μήνα χωρίς στέμμα, και κλεψύδρα για τον μήνα που τρέχει ακόμη. Ανοίγουν μόνο **ολοκληρωμένοι μήνες**: ποτέ ο ζωντανός μήνας και ποτέ οι μήνες της περσινής σχολικής χρονιάς. Οι στέψεις μετράνε μόνο φέτος. Δεν είναι το Hall of Heroes.

### Certificates

Άνοιξε το **Hero Certificate** από το **Certificate** στη γραμμή του μαθητή στο **Manage Students** (ομάδα **Records**), ή από το κουμπί πιστοποιητικού στο προφίλ του μαθητή. Το παράθυρο δείχνει ζωντανή προεπισκόπηση της σελίδας με δύο κορδέλες επάνω:

- **Monthly Quest**: μόνο τα κατορθώματα αυτού του ημερολογιακού μήνα.
- **Legend's Journey**: όλη η σχολική χρονιά.

Δίπλα στην προεπισκόπηση, το **Honours on the page** δείχνει τι βρήκε η εφαρμογή για την περίοδο: αστέρια, την αρετή που λάμπει, το επίπεδο Hero Path, στέμματα Prodigy of the Month, Ember Oaths που τηρήθηκαν, την καλύτερη δοκιμασία, το Familiar και θησαυρούς (τυπώνονται τα πρώτα έξι). Το ίδιο το πιστοποιητικό είναι φωτισμένη σελίδα A4 οριζόντια, στα χρώματα του guild του παιδιού (ή της ηλικιακής ομάδας πριν το sorting), με σφραγίδα από κερί, το πορτρέτο του ήρωα, την ασπίδα του guild, τη σχολική χρονιά και διατύπωση που ταιριάζει στην ηλικία.

Στο **Elite**, το **Ask the Oracle** γράφει μια σύντομη αναφορά από τον μήνα ή τη χρονιά του παιδιού. Μπορείς να τη διορθώσεις ελεύθερα (η σελίδα αλλάζει καθώς γράφεις) ή να πατήσεις **Write a new one**. Το **Seal & Download PDF** εμφανίζεται μόλις υπάρχει αναφορά και αποθηκεύει το PDF σε A4. Στα Starter και Pro βλέπεις την προεπισκόπηση και τις τιμές, αλλά το PDF χρειάζεται την αναφορά του Oracle.

Το **Monthly Quest** μετρά πάντα τον τρέχοντα ημερολογιακό μήνα, οπότε τύπωσε το πιστοποιητικό ενός μήνα πριν τελειώσει εκείνος ο μήνας.
`,

  'teacher/06-mystic-market-and-economy.md': `# Mystic Market και η οικονομία του Gold

Το Mystic Market είναι **δική του καρτέλα** — όχι μια γωνιά του Hero’s Challenge. Διάλεξε αγοραστή, δες το Gold του και αγόρασε από τέσσερα ράφια: **Legendary Artifacts** (πάντα τα ίδια), **Festival Stall** (γιορτές με χρονικό όριο), **seasonal treasures** (μηνιαία ατμόσφαιρα της τάξης) και **αυγά Familiar** (Elite).

## Σκοπός

Διδάσκει **καθυστερημένη ικανοποίηση**. Τα αστέρια γίνονται αγοραστική δύναμη. Η κατάταξη στο Hero’s Challenge **δεν** πουλιέται: το ξόδεμα Gold δεν κατεβάζει ποτέ τα Total ή Monthly αστέρια.

## Πώς κερδίζεται το Gold

Βασικός κανόνας: **1 Gold ανά αστέρι** που δίνεται (το Gold μένει ξεχωριστό από την κατάταξη).

Έξτρα Gold μπορεί να έρθει από:

| Πηγή | Τι συμβαίνει |
|------|--------------|
| **2× Star Day** | Τα αστέρια (άρα και το Gold) διπλασιάζονται εκείνη τη μέρα |
| **Hero Path match (Pro)** | **+10 Gold** όταν ο λόγος της επιβράβευσης ταιριάζει με το Hero Class του μαθητή |
| **Skill Tree perks (Pro)** | Έξτρα Gold στον ίδιο, σε συμμαθητές ή σε μέλη του guild για λόγους που ταιριάζουν· κάποια δώρα guild την πρώτη του μήνα |
| **Scroll of the Gilded Star** | Το επόμενο αστέρι δίνει **τριπλό Gold** |
| **Fortune’s Wheel** | Βροχές Gold, ορμητικά κύματα και παρόμοια τμήματα |
| **Γενέθλια / ονομαστική γιορτή** | Αστέρια (και Gold) στην ειδική περίσταση |
| **Quiz of the Week** | 1 Gold ανά αστέρι, +1 Gold για μια θαρραλέα προσπάθεια· ο Quiz Champion παίρνει έναν θησαυρό από τον πάγκο (φεύγει από το απόθεμα) |
| **Coin Purse** (Teacher Settings) | Χειροκίνητη διόρθωση υπολοίπου |

Μην μοιράζεις Gold αντί για αστέρια. Το αστέρι είναι η πράξη αναγνώρισης· το Gold απλώς ακολουθεί.

## Πώς ξοδεύεται το Gold

- Αγορές στο Market (artifacts, εποχιακά αντικείμενα, αυγά)
- **Hero’s Boon** (15 Gold, εκτός αν ένα Compassion Token έχει κάνει τα boons δωρεάν αυτόν τον μήνα)

## Legendary Artifacts (power-ups)

Πάντα σε απόθεμα. **Δύο αγορές legendary ανά μαθητή ανά μήνα.** Χρησιμοποιούνται από το Trophy Room ή πατώντας το πορτρέτο του ήρωα. Η χρήση εξαντλεί το αντικείμενο.

| Artifact | Gold | Αποτέλεσμα | Έξτρα όριο |
|----------|------|------------|------------|
| **Crystal of Clarity** | 15 | Φωτεινό πετράδι στην κάρτα του μαθητή που δείχνει ότι έχει μια «πάσα υπόδειξης» | — |
| **Scroll of the Gilded Star** | 20 | Επόμενο αστέρι → **3× Gold**, μετά σβήνει | — |
| **Time Warp Hourglass** | 25 | **+5 λεπτά** σε κάθε ενεργό bounty **Race the Clock** του τμήματος (δεν μπορεί να χρησιμοποιηθεί όταν δεν τρέχει κανένα bounty) | — |
| **Elixir of Luck** | 30 | Επόμενο μάθημα: **50%** πιθανότητα για **+1 αστέρι** στην πρώτη θετική επιβράβευση (δεν χρησιμοποιείται αν το +1 του Hero of the Day ισχύει ήδη σε αυτή την επιβράβευση) | — |
| **Aurum Satchel** | 32 | **50% έκπτωση** στην επόμενη αγορά στο Market αυτόν τον μήνα | — |
| **Banner of Glory** | 35 | Τα επόμενα **3** αστέρια προσθέτουν το καθένα **+1 μπόνους Guild Glory** | Χρειάζεται guild |
| **The Herald’s Banner** | 40 | Πανσχολική γιορτινή ανακοίνωση | — |
| **Fortune’s Favor** | 48 | Ο επόμενος **Fortune’s Wheel** του guild στο τμήμα του μαθητή είναι επίχρυσος: χωρίς καταιγίδες, χωρίς Trickster και χωρίς common τμήματα | Χρειάζεται guild |
| **The Starfall Catalyst** | 50 | Διπλασιάζει το επόμενο μπόνους **Starfall** για υψηλό τεστ | — |
| **Chalice of Unity** | 55 | **+1 Glory** αμέσως για τον μαθητή και κάθε μέλος του guild του στο τμήμα | Χρειάζεται guild |
| **Compassion Token** | 55 | Το Hero’s Boon κοστίζει **0 Gold** για τον υπόλοιπο μήνα | — |
| **The Pathfinder’s Map** | 60 | Άμεσα **+10 αστέρια Team Quest** για το τμήμα | **1 χρήση ανά τμήμα ανά μήνα** (και όχι όσο κάποιος συμμαθητής κρατά ακόμη αχρησιμοποίητο Pathfinder που αγοράστηκε αυτόν τον μήνα) |
| **Archivist’s Quill** | 62 | Το επόμενο μπόνους Story Weaver του τμήματος είναι **1 αστέρι αντί για 0.5** για αυτόν τον μαθητή | — |
| **The Mask of the Protagonist** | 75 | Εγγυάται **Hero of the Day** στο επόμενο Adventure Log | **1 αγορά ανά μαθητή ανά μήνα** |
| **Guild Standard** | 75 | Το όνομα του μαθητή κυματίζει στο λάβαρο του guild στο Guild Hall για το υπόλοιπο Chapter του μήνα, συν **+2 Glory** | Χρειάζεται guild |

## Seasonal treasures (Elite)

Το μηνιαίο ράφι ακολουθεί **την ιστορία του μήνα στην τάξη** (ο Σεπτέμβριος είναι σοδειά και επιστροφή στο σχολείο, όχι Halloween) και γράφεται για την ηλικία της league: το Pre-Junior παίρνει ζεστά παιχνίδια, περιγραφές έξι λέξεων και εικόνες-αυτοκόλλητα, ενώ οι C και D παίρνουν δουλεμένα αντικείμενα χωρίς τίποτα μωρουδίστικο. Κάθε ράφι είναι μία από τις τρεις **συλλογές** του μήνα (Οκτώβριος: Mushroom Ring, Chestnut Fire, Foggy Forest Library), που φαίνεται δίπλα στον μήνα. Η Elite γεμίζει **15** είδη αυτόματα όταν το ράφι είναι άδειο — συνέχισε το μάθημα· οι εικόνες φτάνουν στο παρασκήνιο. Πάτα το στρογγυλό μπρούτζινο κουμπί **Restock** (βέλη σε κύκλο, στην αριστερή άκρη του πάγκου· γράφει «Restock the shelves» όταν το δείχνεις) για ολοκαίνουργιο μηνιαίο ράφι από άλλη συλλογή· τα σημερινά θησαυρίσματα μένουν μέχρι να είναι έτοιμες οι νέες εικόνες. Το Festival Stall είναι ξεχωριστό και έρχεται μόνο του.

Κάθε είδος έχει αντίτυπα: Common **5**, Rare **2**, Legendary seasonal **1**. Κάθε αγορά ξοδεύει ένα αντίτυπο· το τελευταίο αντίτυπο φεύγει από το ράφι. Αν εξαντληθούν όλα τα μηνιαία είδη, ο έμπορος ξαναγεμίζει το ράφι χωρίς να πατήσεις τίποτα.

- 5 είδη Common (περίπου 10–18 Gold)
- 5 είδη Rare (περίπου 35–50)
- 5 Legendary εποχιακά τρόπαια (περίπου 80–120)

Η γλώσσα και η εικόνα για τα Junior μένουν παιχνιδιάρικες· τα αντικείμενα για τους μεγαλύτερους διαβάζονται σαν κειμήλια RPG. **Δεν** υπάρχει όριο εποχιακών αντικειμένων ανά μήνα — όριο είναι το Gold, τα αντίτυπα στο ράφι και η κρίση σου.

## Festival Stall (Elite)

Ένα μικρό έξτρα ράφι για **Halloween** (31 Οκτ.), **Χριστούγεννα** (25 Δεκ.), **Πρωτοχρονιάτικο Γούρι** (2 έως 25 Ιαν., την εποχή της βασιλόπιτας), τις ελληνικές **Απόκριες**, το **Ορθόδοξο Πάσχα**, την **Πρωτομαγιά** (δύο εβδομάδες πριν την 1η Μαΐου) και τη **Γιορτή Λήξης** (όλο τον Ιούνιο). Halloween, Χριστούγεννα, Απόκριες και Πάσχα εμφανίζονται περίπου **22 μέρες** πριν τη γιορτή, όταν είναι έτοιμο το απόθεμά τους· κάθε ράφι αφαιρείται την επομένη της γιορτής. Όταν το Πάσχα πέφτει αργά, παίρνει τη θέση της Πρωτομαγιάς. Το Market δείχνει banner (και ένα μήνυμα μία φορά) όταν φτάσουν περιορισμένα γιορτινά θησαυρίσματα.

Είδη Festival: 2 Common, 2 Rare, 1 Legendary, με τους ίδιους κανόνες αντιτύπων. Αν το Festival Stall εξαντληθεί, μια **νέα** γιορτινή παρτίδα φτιάχνεται στο τέλος εκείνης της μέρας. Οι περίοδοι διακοπών του School Office **δεν** καθορίζουν αυτό το ράφι.

### Εκπτώσεις (εποχιακό ράφι)

Αθροίζονται και μετά έχουν ανώτατο όριο:

- **Βασιλεύων Hero of the Day:** **25%** έκπτωση
- Νίκες Hero of the Day αυτής της σχολικής χρονιάς: Rising Legend (3+) **+5%**, Golden (5+) **+10%**, Mythic (10+) **+15%**. Μια νέα χρονιά ξεκινά από Future Legend. Τα στέμματα της περσινής χρονιάς μένουν στο περσινό Hall of Heroes.
- Η συνολική έκπτωση **δεν μπορεί να ξεπεράσει το 40%**
- Το **Aurum Satchel** μετά κόβει στο μισό την τιμή που προκύπτει (ελάχιστο 1 Gold)

Τα Legendary Artifacts στο μόνιμο ράφι ακολουθούν τον δικό τους κανόνα δύο αγορών τον μήνα· οι εκπτώσεις Hero αφορούν την τιμή του **εποχιακού** ραφιού.

## Familiars (Elite)

Κάθε μαθητής έχει **ένα** Familiar, έναν σύντροφο για όλη τη χρονιά.

| Αυγό | Gold | Προσωπικότητα | Μορφές (εκκόλαψη → μέση → τελική) |
|------|------|---------------|-----------------------------------|
| **Thornback** | 30 | Σταθερός, πιστός | Moss Toad → Bark Bear → Ancient Treant |
| **Frostpaw** | 35 | Ήρεμος, σοφός | Ice Cub → Snow Fox → Frost Guardian |
| **Emberfang** | 40 | Τολμηρός, άγριος | Hatchling → Flame Drake → Inferno Dragon |
| **Veilshade** | 45 | Μυστηριώδης | Shadow Wisp → Phantom Cat → Void Stalker |
| **Sparkling** | 50 | Φωτεινός, χαρούμενος | Sun Sprite → Dawn Fairy → Solar Phoenix |

**Ανάπτυξη** (αστέρια που κερδίζονται *μετά* τη σχετική στιγμή):

1. Αυγό: μετά από **20** αστέρια από την αγορά εκκολάπτεται (Level 1) και παίρνει όνομα και κινούμενη εικόνα
2. **60** αστέρια από την εκκόλαψη → Level 2
3. **140** αστέρια από την εκκόλαψη → Level 3

Ένα Familiar κάθεται δίπλα στο πορτρέτο του μαθητή στους πίνακες, και μεγαλύτερο όταν ανοίγεις τα στατιστικά του («stars together» και πρόοδος προς την επόμενη μορφή). Η εκκόλαψη και η εξέλιξη παίζουν δικούς τους ήχους. Στο Elite, το AI ζωγραφίζει τις εικόνες κάθε Familiar.

## Τι μπορείς να κάνεις στην καρτέλα

1. Διάλεξε τμήμα (κεφαλίδα) και **αγοραστή**. Η επιλογή αγοραστή και το **Purse** κάθονται δίπλα δίπλα σαν ξύλινες πλακέτες πάνω στον πάγκο (στο κινητό ο αγοραστής παίρνει δική του σειρά και το πουγκί από κάτω). Ο **Market Keeper** (ο έμπορος στον πάγκο) τον χαιρετά, λέει το Gold του και πόσα εμπορεύματα μπορεί να αγοράσει. Δείξε ένα εμπόρευμα και λέει την τιμή του, ή πόσο Gold ακόμη χρειάζεται το παιδί.
2. Κοίτα τα ράφια· εξήγησε τις τιμές δυνατά — τα παιδιά πρέπει να *διαλέγουν*. Οι **πινακίδες διαδρόμων** πηγαίνουν σε ένα τμήμα (Festival Stall, Seasonal, Artifacts, Familiar Eggs), το **Sort** ταξινομεί κάθε ράφι με φθηνότερο, ακριβότερο ή A to Z (το θυμάται αυτή η συσκευή), και το **Can afford** κρύβει ό,τι δεν μπορεί να αγοράσει τώρα ο αγοραστής.
3. Κάθε εμπόρευμα έχει χάρτινο καρτελάκι τιμής. Με επιλεγμένο αγοραστή, το κουμπί γράφει **Buy for N**, **Need N more**, **Owned** ή το όριο που το μπλοκάρει. Οι εκπτώσεις (Hero of the Day, βαθμίδες θρύλου Hero of the Day, Aurum Satchel) βάζουν μια έκρηξη προσφοράς με το ποσοστό στο εμπόρευμα και διαγράφουν την παλιά τιμή.
4. **Αγόρασε**. Νομίσματα πηδούν από το πουγκί και ο Keeper ευχαριστεί τον αγοραστή· όταν πουληθεί το τελευταίο αντίτυπο ενός εποχιακού ή γιορτινού κομματιού, σφραγίζεται **Sold!** και φεύγει από το ράφι. Το απόθεμα εμφανίζεται στο Trophy Room.
5. Elite: το μπρούτζινο κουμπί **Restock** στον πάγκο φέρνει ολοκαίνουργιο μηνιαίο ράφι (γυρίζει όσο φτιάχνεται το νέο ράφι). Το Festival Stall έρχεται και φεύγει μόνο του. Το **Teacher Settings → Market** διορθώνει μαύρη εικόνα, υπόλοιπα αντίτυπα, ονόματα, Gold ή περιγραφές, ή αντικαθιστά ένα κομμάτι.
6. Αν δεν έχει επιλεγεί τμήμα, η βιτρίνα μένει με κουρτίνα και πινακίδα **Closed** (και η ταμπέλα πάνω από την πόρτα γράφει κι αυτή Closed).

## Πώς τροφοδοτεί το υπόλοιπο Quest

Τα artifacts αλλάζουν τα **μαθήματα** (τύχη, bounties, logs, Starfall, Story Weavers), το **Team Quest** (Pathfinder) και το **Guild Hall** (μικρά δώρα Glory, ένα Guild Standard στο λάβαρο, ένας επίχρυσος Wheel). Κανένα δεν πολλαπλασιάζει το Glory, οπότε το Gold δεν αγοράζει ποτέ ένα Chapter. Τα Familiars κάνουν ορατό κάθε μελλοντικό αστέρι. Το Compassion Token κάνει τα Hero’s Boons δωρεάν για έναν μήνα.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Gold, πάντα διαθέσιμα Legendary Artifacts, δύο αγορές legendary ανά μαθητή ανά μήνα | Το ίδιο κατάστημα. Τα μπόνους Gold του Hero Path ζουν στο Path | AI μηνιαίο ράφι, Festival Stall, Restock, Market Manager, αυγά Familiar και οι εικόνες τους |
`,

  'teacher/07-guild-hall.md': `# Guild Hall

Το Guild Hall είναι **σπίτι εναντίον σπιτιού** για **ολόκληρη τη σχολική χρονιά**. Παιδιά από κάθε επίπεδο μπαίνουν σε **ένα σπίτι** και το τροφοδοτούν κάθε φορά που κερδίζουν αστέρια. Τον Ιούνιο ένα guild στέφεται στο **Grand Guild Ceremony**.

Αυτός είναι ο τρίτος αγώνας. Η χρονιά λέγεται σε **Chapters**: κάθε σχολικός μήνας είναι ένας νέος αγώνας για **Crowns**, και τα Crowns αθροίζονται όλη τη χρονιά. Ένας κακός Οκτώβριος δεν τελειώνει ποτέ τη χρονιά ενός guild.

## Σκοπός

**Ανήκειν πέρα από τις ηλικίες.** Ένα ήσυχο Junior και ένα τολμηρό Senior μπορούν να μοιράζονται το ίδιο motto. Το σκορ είναι το **Crown Race**, φτιαγμένο ώστε ένα μικρό σπίτι να μην καταδικάζεται από τον αριθμό των μελών του και ένα guild που μένει πίσω να έχει πάντα έναν επόμενο μήνα για να παλέψει.

## Τα τέσσερα σπίτια

Τέσσερα σπίτια. Τέσσερις χαρακτήρες. Τα εμβλήματα, οι ύμνοι και τα χρώματα είναι τα ίδια παντού στο Quest — στα σύννεφα, στο μαθητολόγιο, στην αίθουσα.

**Dragon Flame** — *Fear nothing. Burn bright.* Courage, Fire, Bold. Το σπίτι των πρώτων βημάτων και των δυνατών καρδιών. Παιδιά που δηλώνουν πρώτα, που δοκιμάζουν τη δύσκολη πρόταση, που οδηγούν το ζευγάρι.

**Grizzly Might** — *Stand together. Stand strong.* Strength, Teamwork, Steadfast. Το σπίτι του κύκλου: περιμένουν τον συμμαθητή, μοιράζονται τον χάρτη, δεν αφήνουν κανέναν πίσω.

**Owl Wisdom** — *Knowledge is power.* Wisdom, Curiosity, Calm. Το σπίτι της ερώτησης. Παρατηρούν το μοτίβο, ρωτούν *γιατί*, κρατούν την τάξη σε σκέψη.

**Phoenix Rising** — *Fall down seven, rise up eight.* Resilience, Renewal, Hope. Το σπίτι της δεύτερης ευκαιρίας. Το Welcome Back ανήκει στην ιστορία τους. Επιστρέφουν στη δουλειά.

Κάθε σπίτι έχει έμβλημα, ήχο και **karaoke anthem**. Πάτα το έμβλημα στο λάβαρο ενός guild στην αίθουσα και το **λάβαρο** του guild ξετυλίγεται σε όλη την οθόνη: ένα εραλδικό λάβαρο στα χρώματα του σπιτιού, κρεμασμένο από επίχρυση ράβδο, με το έμβλημα, το όνομα, το motto σε κορδέλα, τα χαρακτηριστικά και τους αριθμούς (Crowns, το Glory ανά μέλος σε αυτό το Chapter, το Unity Seal, το Glory της χρονιάς και τα μέλη). Όταν το κλείσεις, τυλίγεται ξανά προς τα πάνω.

Το μικρό κουμπί με τη **νότα** πάνω στο έμβλημα παίζει τον ύμνο. Ανοίγει σε μια κόγχη φωτισμένη από πυρσούς, με το έμβλημα ανάμεσα σε δύο πυρσούς· οι στίχοι φωτίζονται καθώς τραγουδιούνται. Παίξε τον ύμνο όταν η αίθουσα χρειάζεται ταυτότητα, όχι θόρυβο για τον θόρυβο.

## Τοποθέτηση — Guild Placement Quiz

Από **Teacher Settings → My Classes → Manage Students**, κάθε μαθητής χωρίς guild μπορεί να κάνει ένα quiz **7 ερωτήσεων** σε μορφή ιστορίας. Το καπέλο στο μαθητολόγιο το ανοίγει.

Τρέχει ως **Sorting Ceremony** σε πλήρη οθόνη, φτιαγμένη για τον προβολέα. Ανοίγει σαν χρυσή πύλη από το καπέλο που πάτησες και, όταν κλείνει, διπλώνει πίσω στη σφαίρα (ή στο έμβλημα, μετά την αποκάλυψη).

1. **Εισαγωγή** — το πορτρέτο και το όνομα του μαθητή, τα τέσσερα εμβλήματα να γυρίζουν γύρω από μια φωτεινή σφαίρα. **Begin the Sorting**.
2. **Ερωτήσεις** — ένα πάτημα ανά απάντηση (ή πλήκτρα **1–4** / **A–D**). Μια σπίθα πετά μέσα στη σφαίρα και εμφανίζεται η επόμενη ερώτηση. Η σφαίρα και ο ουρανός παίρνουν σιγά σιγά τα χρώματα προς τα οποία γέρνουν οι απαντήσεις: υπόδειξη, ποτέ η απάντηση. Το **Back** αλλάζει μια προηγούμενη απάντηση.
3. **Σφράγισμα** — «The orb is ready…». Περίμενε να κοιτάζει όλη η τάξη και μετά πάτα **Reveal my Guild**.
4. **Αποκάλυψη** — τύμπανα ενώ ένας προβολέας γυρίζει γύρω από τα τέσσερα σπίτια και επιβραδύνει· μια λάμψη, και μετά το έμβλημα, το όνομα, το motto, τα χαρακτηριστικά του σπιτιού, γιατί το διάλεξαν τα αστέρια, και μια μικρή μπάρα «Your answers echoed». Παίζει ο ήχος του σπιτιού.

Το σπίτι αποθηκεύεται κατά την αποκάλυψη. Αν η αποθήκευση αποτύχει, η τελετή το λέει και το **Try again** κρατά τις απαντήσεις. Το **Esc** ή το ✕ βγαίνει οποιαδήποτε στιγμή (τίποτα δεν αποθηκεύεται πριν την αποκάλυψη). Με μειωμένη κίνηση παραλείπονται η περιστροφή και οι σπίθες.

Η δεξαμενή ερωτήσεων **ταιριάζει στο league** — η γλώσσα του Pre-Junior δεν είναι γλώσσα του D. Κάθε απάντηση γέρνει προς ένα από τα σπίτια, και το σύνολο αποφασίζει πού ανήκει ο μαθητής. Αντιμετώπισέ το ως ταυτότητα, όχι ως διαγώνισμα. Μόλις τοποθετηθεί, το σπίτι είναι για τη χρονιά (και ο σχεδιασμός είναι για ανήκειν ζωής).

Τα σχολεία Starter βλέπουν κλειδωμένο καπέλο. Τα **Pro** και **Elite** τρέχουν το quiz.

## Glory και Crown Race

Κάθε θετικό αστέρι προσθέτει **Guild Glory**, με **2 Glory ανά αστέρι**, συν λίγο ακόμα από το Fortune’s Wheel και μερικά κειμήλια του Mystic Market. Το Quiz of the Week δίνει Glory μέσα από τα αστέρια του. Η μόνη τύχη που παίρνει Glory είναι μια μικρή καταιγίδα ή ένα twist του Fortune’s Wheel, και μόνο από Glory που κερδήθηκε αυτόν τον μήνα. Κατά τα άλλα μόνο ένα αστέρι που αναιρείται ή μια διόρθωση του δασκάλου το αφαιρεί.

**Chapters.** Κάθε σχολικός μήνας είναι ένα **Chapter**. Την 1η του μήνα κάθε guild ξεκινά το Chapter από το 0. Το Chapter το κερδίζει το guild του οποίου τα μέλη κέρδισαν **το περισσότερο Glory το καθένα, κατά μέσο όρο**: το Glory που κέρδισαν εκείνο τον μήνα τα σημερινά μέλη, διαιρεμένο με τον αριθμό των μελών. Ένα σπίτι οκτώ παιδιών που παίζουν όλα νικά ένα σπίτι είκοσι όπου τέσσερα παιδιά κουβαλούν το λάβαρο.

**Crowns.** Όταν τελειώνει ένα Chapter, σφραγίζεται και δίνει Crowns:

| Θέση | 1η | 2η | 3η | 4η |
|------|----|----|----|----|
| Crowns | 5 | 3 | 2 | 1 |

Guilds ισόπαλα σε Glory ανά μέλος μοιράζονται την υψηλότερη θέση. Ένα guild που δεν κέρδισε καθόλου Glory μέσα στον μήνα δεν παίρνει Crowns.

**Το Unity Seal: +1 Crown.** Κάθε guild όπου τουλάχιστον **4 στα 5 μέλη** κέρδισαν **6 Glory (3 αστέρια)** τον μήνα παίρνει ένα επιπλέον Crown, όποια θέση κι αν πήρε. Μπορούν να το κερδίσουν όλα τα guilds τον ίδιο μήνα. Επιβραβεύει την τάξη που φέρνει μαζί και τους ήσυχους ήρωες, όχι μόνο τα αστέρια των αστεριών.

**Η χρονιά.** Το guild με τα **περισσότερα Crowns** στη Grand Guild Ceremony κερδίζει το στέμμα του Ιουνίου. Αν δύο guilds έχουν τα ίδια Crowns, νικά αυτό με το περισσότερο Glory ανά μέλος σε όλη τη χρονιά.

- **Τα σφραγισμένα Chapters δεν αλλάζουν ποτέ.** Μόλις ένας μήνας τελειώσει και σφραγιστεί, οι θέσεις και τα Crowns του είναι ιστορία. Ένα αστέρι που αναιρείται αργότερα αφαιρείται από το Glory της χρονιάς του guild, όχι από ένα σφραγισμένο Chapter.
- **Όποιος φεύγει παίρνει το Glory του μαζί του.** Όταν ένας μαθητής φεύγει, το Glory του σταματά να μετρά για το guild, ώστε κανένα guild να μην ανεβαίνει επειδή μίκρυνε.
- **Δίκαιο σε κάθε μέγεθος.** Το Glory του Wheel, το Chalice of Unity και το Quiz of the Week δίνουν Glory σε μεμονωμένα παιδιά, οπότε ένα μεγάλο guild δεν παίρνει ποτέ μεγαλύτερο αριθμό μόνο επειδή είναι μεγάλο.

Πάτα το **?** δίπλα στο Chapter του μήνα (ή στον πίνακα του Crown Race) για να ανοίξει το **How the Crown Race works**, που τα λέει όλα αυτά στην οθόνη με απλά λόγια. Ένα μικρό, δραστήριο guild μπορεί να νικήσει ένα μεγάλο, νυσταγμένο, και ένα guild που βγήκε 4ο τον περασμένο μήνα μπορεί να κερδίσει αυτόν. Πες το δυνατά.

Η αίθουσα μένει ακίνητη μέχρι να αρχίσει η σχολική χρονιά και να υπάρχουν προγράμματα τμημάτων, οπότε μην ανησυχείς αν φαίνεται ήσυχη την εβδομάδα της προετοιμασίας.

## Τι βλέπεις στην καρτέλα

Το Hall είναι μία νυχτερινή μεγάλη αίθουσα σε τρία μέρη, από πάνω προς τα κάτω.

- **Η πάνω μπάρα.** Το **Fortune’s Wheel** αριστερά, τα **Guild Stats** δεξιά, και στη μέση **το Chapter του μήνα**: ένας δίσκος με τις μέρες που μένουν, το όνομα του μήνα και τι πληρώνει (🥇 5 · 🥈 3 · 🥉 2 · 4th 1, συν 1 για το Unity Seal). Το **?** ανοίγει το How the Crown Race works
- **Τέσσερα λάβαρα guild**, πάντα με την ίδια σειρά, ώστε κάθε παιδί να βρίσκει το σπίτι του στο ίδιο σημείο. Κάθε λάβαρο έχει:
  - τη **θέση του αυτόν τον μήνα** ως μετάλλιο στη γωνία (χρυσό, ασημένιο, χάλκινο, σιδερένιο)· το λάβαρο που προηγείται έχει χρυσό περίγραμμα
  - το έμβλημα (πάτα το για το πλήρες λάβαρο) και το κουμπί με τη **μουσική νότα** για το anthem
  - ένα **φιαλίδιο** που γεμίζει με το **Glory ανά μέλος αυτού του Chapter**, τον αριθμό που κυνηγούν όλα τα guilds, με τον αριθμό από κάτω. Όταν πέφτουν αστέρια, ο αριθμός ανεβαίνει κυλώντας και ένα μικρό «+0.4» αιωρείται δίπλα του
  - **«+3 👑 if the month ended now»**: τα Crowns που θα έπαιρνε το guild σήμερα, μαζί με το Unity Seal
  - τον δακτύλιο του **Unity Seal**: πόσα μέλη έχουν ήδη τα 6 Glory του μήνα, απέναντι σε όσα χρειάζονται. Όταν ο δακτύλιος κλείσει, η σφραγίδα γίνεται χρυσή: **Sealed! +1 Crown**
  - όσα **Guild Standards** υψώθηκαν σε αυτό το Chapter (μαθητές που αγόρασαν ένα στο Mystic Market)
- **Ο πίνακας του Crown Race**, μία σειρά για κάθε guild με τη σειρά των Crowns, με μετάλλιο για τη θέση, μία πέτρα για κάθε μήνα από τον Σεπτέμβριο ως τον Ιούνιο και το σύνολο των Crowns. Οι σφραγισμένοι μήνες δείχνουν τα Crowns που κερδήθηκαν (χρυσό, ασημένιο, χάλκινο ή σιδερένιο, με πράσινη κουκκίδα για Unity Seal)· ο μήνας που τρέχει είναι μια διακεκομμένη πέτρα με τα Crowns που θα πλήρωνε σήμερα. Η γραμμή του τίτλου λέει ποιος προηγείται και με πόσο. Όταν αλλάζει η σειρά, οι σειρές γλιστρούν στις νέες τους θέσεις
- Τα **Guild Stats** ανοίγουν μια κάρτα κάτω από κάθε λάβαρο: το Glory του μήνα, πόσα μέλη κερδίζουν (με μια μικρή πράσινη μπάρα), το Glory ανά μέλος της χρονιάς, τους μήνες που κέρδισε, ένα μικρό βάθρο για τα **Stars of the month**, τα **Legends of the year** (οι τρεις πρώτοι στο καθένα) και ένα κουμπί που ανοίγει το **Spotlight** του guild
- **Fortune Ledger**: ένα δερμάτινο βιβλίο κάτω από την αίθουσα. Το εξώφυλλο δείχνει τα γυρίσματα της χρονιάς, το Glory που βρέθηκε και το Glory του Wheel για κάθε guild· άνοιξέ το για τις σελίδες

Το Hall περιμένει τους βαθμούς των guilds πριν δείξει αριθμό: μέχρι να φτάσουν δείχνει απαλά, λαμπυρίζοντα σημεία αναμονής, ποτέ μια σειρά από μηδενικά. Μετά αλλάζει μόνο ό,τι άλλαξε, οπότε δεν αναβοσβήνει και δεν ξαναζωγραφίζεται ενώ διδάσκεις. Σε πιο αργό laptop (και όταν ο υπολογιστής ζητά λιγότερη κίνηση) το Hall κρατά κάθε αριθμό και χρώμα αλλά σταματά τα εφέ που επαναλαμβάνονται.

## Guild Stats και Guild Spotlight

Όχι για βαθμολόγηση. Για **προπονητική**: ποια τμήματα τροφοδοτούν ποιο σπίτι, ποιοι είναι οι ήσυχοι συνεισφέροντες, αν ένας ήρωας κουβαλά μόνος του ένα λάβαρο. Γιόρτασε την ομαδική δουλειά, όχι έναν πίνακα κατάταξης παιδιών.

Το **Guild Spotlight** ανοίγει από την κάρτα Stats ενός guild. Διάλεξε όποιο από τα τέσσερα guilds θέλεις πάνω πάνω· το έμβλημα, το σύνθημα, τα χαρακτηριστικά και το μετάλλιο του Crown Race αλλάζουν μαζί του. Έχει τέσσερις σελίδες:

- **This month**: ένας δακτύλιος με το Glory ανά μέλος του guild δίπλα στα άλλα τρία, τι θα πλήρωνε ο μήνας αν τελείωνε τώρα, και μια συμβουλή όπως «To pass Owl Wisdom: about 3 more stars across the guild». Η κάρτα **Unity Seal** δείχνει κάθε μέλος ως μικρό δακτύλιο που γεμίζει προς τα 6 Glory, και η σειρά **Almost there** ονομάζει όσους απέχουν ένα ή δύο αστέρια. Τα **Stars of the month** στέκονται σε βάθρο
- **Heroes**: το βάθρο των **Legends of the year**, από ποια τμήματα έρχονται τα αστέρια, και όλοι οι ήρωες, με αναζήτηση και ταξινόμηση ανά μήνα, χρονιά, όνομα ή τμήμα. Ένα λεπτό πράσινο σημάδι σε κάθε μπάρα είναι η γραμμή του Unity Seal
- **Crown Road**: μία πέτρα για κάθε μήνα από τον Σεπτέμβριο ως τον Ιούνιο με τη θέση και τα Crowns (🤝 για Unity Seal), με τον μήνα που τρέχει να λάμπει, μετά τα Crowns, τους μήνες που κέρδισε, τα Unity Seals και το Glory ανά μέλος της χρονιάς, και τις μπάρες του Crown Race για όλα τα guilds
- **Wheel finds**: τα πρόσφατα γυρίσματα του guild, το Glory, τα αστέρια και το Gold που βρέθηκαν, και το **καλύτερο εύρημα**

## Grand Guild Ceremony

Το θέαμα τέλους χρονιάς, μια **Γιορτή του Καλοκαιριού** κάτω από το κάστρο των guilds. Το Home δείχνει το κάλεσμα όταν έρθει η ώρα. Στην πάνω μπάρα υπάρχει **Exit** (Esc), έξι σημάδια κεφαλαίων και το κουμπί **sound**· το **Space** πατά το μεγάλο κουμπί.

**Άνοιγμα.** Το κάστρο στο ηλιοβασίλεμα με τα τέσσερα λάβαρα, η σχολική χρονιά και **Begin the Festival**. Η εφαρμογή μαζεύει τις ιστορίες της χρονιάς από κάθε μήνα.

- **Κεφάλαιο I · Legends of the Day.** Οι μαθητές με τις περισσότερες νίκες Hero of the Day ανεβαίνουν σαν φανάρια, ο πρώτος στη μέση.
- **Κεφάλαιο II · The Quest Road.** Η χρονιά κάθε τμήματος ως σειρά από μηνιαίες μπάρες. Τα τμήματα δεν κατατάσσονται απέναντι σε άλλες leagues.
- **Κεφάλαιο III · The Crown Road.** Ένα πλακίδιο για κάθε ολοκληρωμένο μήνα με τον Prodigy of the Month (ή τους Co-Prodigies) και μια πλάκα **Most crowned**.
- **Κεφάλαιο IV · Wonders of the Year.** Γυρίσματα του Fortune’s Wheel και Familiars που εκκολάφθηκαν, με το πιο τυχερό guild. Παραλείπεται αν η χρονιά δεν έχει κανένα από τα δύο.
- **Κεφάλαιο V · The Guild Crowning.** Πέφτει η νύχτα. Οι τέσσερις κολόνες των guilds στέκονται με κρυφά Crowns και αποκαλύπτονται **από την τελευταία θέση προς τα πάνω** (**Reveal #4**, **#3**, **#2**). Το **🥁 Crown the Champion** παίζει τύμπανα με τον προβολέα να σαρώνει τις δύο τελευταίες κολόνες και στέφει το guild με τα **περισσότερα Crowns** (το Chapter του Ιουνίου μετρά όπως είναι εκείνη τη μέρα· στην ισοπαλία νικά το Glory της χρονιάς ανά μέλος). Κάθε κολόνα δείχνει τα Crowns της και τα Chapters που κέρδισε όταν αποκαλύπτεται. Ακολουθούν το έμβλημα, το σύνθημα και ο **ύμνος** του, με τους στίχους να φωτίζονται στον ρυθμό της μουσικής, και οι κορυφαίοι ήρωές του.
- **Κεφάλαιο VI · The Hall of Heroes.** Κάθε ήρωας των τμημάτων γίνεται αστέρι στον νυχτερινό ουρανό, μαζί με τους αριθμούς της χρονιάς.

Το **Finish Ceremony** αποθηκεύει τη σύνοψη της χρονιάς (ήρωες, αστέρια τμημάτων, στέμματα Prodigy, κατάταξη guilds, γυρίσματα Wheel και Familiars) και αποχαιρετά μέχρι την επόμενη χρονιά. Τα guilds είναι για ζωή: η τελετή δεν ξαναμοιράζει κανέναν.

Αυτή **δεν** είναι η Ceremony of the Month. Μην τρέξεις το μηνιαίο διπλό τελετουργικό και το πεις Guild Ceremony.

## Fortune’s Wheel

Εβδομαδιαίο τελετουργικό, όχι κουλοχέρης για κάθε μάθημα. Ζει σε αυτή την καρτέλα γιατί η περιστροφή δίνει **Glory** — αλλά έρχεται **μετά** τα σπίτια, το quiz και τον ετήσιο αγώνα.

**Πότε μπορεί να γυρίσει**

- Έχει επιλεγεί τμήμα
- Είναι η **τελευταία μέρα μαθήματος της εβδομάδας Δευτέρα–Παρασκευή** για αυτό το τμήμα
- Είσαι **μέσα στην ώρα του μαθήματος**
- Αυτό το τμήμα **δεν** έχει ήδη γυρίσει τον τροχό αυτή την εβδομάδα

**Πώς τρέχει η τελετή.** Άνοιξε το **Fortune's Wheel** από το κουμπί του στην αίθουσα. Ανοίγει ως ουράνιος **Wheel of Fate**: νυχτερινός ουρανός με ζωδιακό κύκλο που γυρίζει, και ο τροχός πλαισιωμένος από φανάρια-αστέρια. Τα τέσσερα guilds παίρνουν σειρά **ένα ένα, με τυχαία σειρά**. Κάθε guild έχει τον δικό του τροχό, και ένα πάνελ **On this wheel** μετρά πόσα τμήματα από κάθε είδος έχει απέναντί του. Πάτα **Spin This Guild**. Ο τροχός παίρνει φόρα προς τα πίσω, τρέχει, κόβει ταχύτητα, και κάποιες φορές περνά λίγο το επόμενο τμήμα και γυρίζει πίσω. Μετά το τμήμα που κάθισε ζωντανεύει: ένας θησαυρός αποκαλύπτεται σε κάρτα μοίρας, μια καταιγίδα φέρνει σύννεφα και κεραυνό πάνω από τον τροχό, ένα twist ή ένα trial ανοίγει τη δική του στιγμή πάνω στην κάρτα. Το **Present Next Guild** πάει παρακάτω, και μετά το τέταρτο guild το **Reveal Final Ledger** μοιράζει το αποτέλεσμα της εβδομάδας σε τέσσερις κάρτες μοίρας. Κάθε δώρο (και κάθε απώλεια) πέφτει στα μέλη εκείνου του guild **σε αυτό το τμήμα**. Όταν ο τροχός δεν μπορεί να γυρίσει, φαίνεται αλυσοδεμένος και σφραγισμένος (ή να επαναφορτίζει, αν αυτό το τμήμα έχει ήδη γυρίσει αυτή την εβδομάδα).

**Όλα μπορούν να συμβούν, λίγο.** Κάθε τροχός έχει **20** τμήματα σε τέσσερις οικογένειες, η καθεμία με το δικό της χρώμα και μοτίβο:

- **Treasure** (από common έως mythic, χρώματα πολύτιμων λίθων): +1 έως +5 Glory για **κάθε μέλος του guild σε αυτό το τμήμα** (Spark, Surge, Fountain, Cascade, Glory Miracle), αστέρια, Gold, artifacts και μπόνους αστέρια Team Quest. Το **Rainbow Bridge** δίνει +1 Glory σε κάθε παιδί του τμήματος, για το δικό του guild. Το πολύ δύο epic, ένα legendary και ένα mythic τμήμα, και πάντα τουλάχιστον ένα rare ή καλύτερο για να ελπίζουν.
- **Twist** (ματζέντα, ρόμβοι αρλεκίνου), 3 σε κάθε τροχό: το δράμα.
  - **Whirlwind**: ο άνεμος αρπάζει τον τροχό και τον ξαναγυρίζει.
  - **Three Chests**: το guild διαλέγει ένα από τρία σεντούκια. Χρυσό: +3 Glory το καθένα. Ασημένιο: +1 Glory το καθένα και Gold για δύο μέλη. Στο τρίτο κρύβεται ένα **Mimic**: −1 Glory το καθένα. Τα άλλα δύο ανοίγουν μετά, για να δει η τάξη τι έχασε.
  - **Double or Nothing**: κράτα +1 Glory το καθένα, ή στρίψε το νόμισμα. Το έμβλημα του guild: +3 το καθένα. Ο κεραυνός: −1 το καθένα.
  - **Kindness Gift**: το guild διαλέγει ένα άλλο guild του τμήματος, και τα δύο κερδίζουν +1 Glory για κάθε μέλος τους εδώ.
  - **Robin Hood**: παίρνει 1 Glory από κάθε μέλος εδώ και δίνει +1 σε κάθε μέλος εδώ του guild που είναι τελευταίο αυτόν τον μήνα. Αν τελευταίο είναι το guild που γυρίζει, ο Robin το βοηθά.
  - **Mirror of Fates**: αντιγράφει ακριβώς ό,τι πήρε το προηγούμενο guild, καλό ή κακό.
  - **Trickster**: ένα ψεύτικο legendary τζακπότ που ραγίζει και γυρίζει ανάποδα: τίποτα δεν κερδίζεται, τίποτα δεν χάνεται.
- **Trial** (τιρκουάζ, δαχτυλίδια), 2 σε κάθε τροχό: μια σύντομη πρόκληση στα Αγγλικά μπροστά στην τάξη. Πάτα **Start the clock**· εσύ κρίνεις με **Correct!** ή **Not this time**. Το **Another one** φέρνει νέα ερώτηση, και το **Answer (for the teacher)** σου δείχνει την απάντηση. Οι ερωτήσεις έρχονται σε δύο επίπεδα: τα Pre-Junior και Junior A/B παίρνουν πιο απλές.
  - **Sphinx's Riddle** (20 δευτερόλεπτα): σωστά +3 Glory το καθένα, λάθος −1 το καθένα.
  - **Lightning Round** (30 δευτερόλεπτα): πείτε λέξεις πριν τελειώσει ο χρόνος. +2 Glory το καθένα, ή τίποτα.
  - **Hero's Dare**: ένας προβολέας πηδά από παιδί σε παιδί του guild και διαλέγει ένα για ένα dare. +1 αστέρι και +10 Gold, ή +5 Gold για τη γενναία προσπάθεια.
- **Storm** (σχιστόλιθος με κίτρινο κεραυνό, γραμμές βροχής), 2 ή 3 σε κάθε τροχό: μια μικρή απώλεια. **Rain Cloud** (−1 Glory το καθένα), **Leaky Pouch** (3 μέλη χάνουν 5 Gold), **Goblin's Toll** (2 μέλη πληρώνουν 10 Gold), **Rockslide** (−1 Glory το καθένα και 2 μέλη χάνουν 5 Gold) και **Thunderclap** (−2 Glory το καθένα). Στις περισσότερες το guild μπορεί να πατήσει **Brave the storm**: απαντούν μαζί σε μία ερώτηση και η ασπίδα κρατά, τίποτα δεν χάνεται· μια λάθος απάντηση αφήνει την καταιγίδα να περάσει. Το Thunderclap και το Leaky Pouch δεν έχουν καταφύγιο.

**Οι απώλειες μένουν μικρές και δίκαιες.** Μια καταιγίδα δεν παίρνει ποτέ αστέρια ή artifacts. Παίρνει μόνο Glory που κέρδισε ένα παιδί **αυτόν τον μήνα** (κανείς δεν πέφτει κάτω από το 0) και Gold μόνο από παιδιά που έχουν. Ένα guild που το χτύπησε καταιγίδα (ή οποιαδήποτε απώλεια) στο τελευταίο του γύρισμα σε αυτό το τμήμα παίρνει **πιο ήρεμο ουρανό** την επόμενη φορά: το πολύ μία καταιγίδα. Γύρνα τον σαν παιχνίδι όπου παίζει όλη η τάξη, και πες το όταν έρθει καταιγίδα: κάθε ήρωας έχει και συννεφιασμένες μέρες.

**Το Glory του τροχού είναι δίκαιο ανά παιδί.** Το Glory πηγαίνει σε (ή φεύγει από) κάθε μέλος του guild που είναι στο τμήμα που γυρίζει, οπότε το Glory ανά μέλος του Chapter κινείται το ίδιο λίγο όποιο κι αν είναι το μέγεθος του guild, και κάθε παιδί σε κάθε guild έχει τις ίδιες ευκαιρίες κάθε εβδομάδα. Επειδή το Glory του τροχού είναι μικρό μπροστά σε έναν μήνα αστεριών, την προσπάθεια την κρίνει το Chapter και ο τροχός προσθέτει δράμα.

**Fortune’s Favor.** Ένας μαθητής που χρησιμοποίησε το **Fortune’s Favor** από το Mystic Market κάνει επίχρυσο τον επόμενο τροχό του guild του στο τμήμα του: χωρίς καταιγίδες, χωρίς Trickster, Robin Hood ή Mirror, χωρίς common τμήματα, και στα σεντούκια ένα χάλκινο δώρο αντί για το Mimic. Η σκηνή το λέει πριν το γύρισμα, και το Favor ξοδεύεται σε εκείνο το γύρισμα.

**Σε πιο αργό laptop** ο τροχός παίζει τις ίδιες στιγμές με λιγότερα σωματίδια και σταματά τα κινούμενα φόντα, ώστε το γύρισμα να μένει ομαλό στο laptop του προβολέα.

Γύρνα τον **με την τάξη να κοιτάζει**. Διάβασε το Ledger μετά, ώστε να θυμούνται την ιστορία.

## Fortune Ledger

Το ιστορικό του τι έκανε πραγματικά ο τροχός **αυτή τη σχολική χρονιά**: ποιος κέρδισε Glory, ποιος βρήκε artifact, ποιο τμήμα πήρε μπόνους Quest, ποιο guild αντιμετώπισε μια καταιγίδα και ποιο έχασε λίγο. Όταν ανοίγει το βιβλίο δείχνει το παράθυρο του τροχού για το επιλεγμένο τμήμα, ένα **Fortune count** για κάθε guild (Glory, γυρίσματα, αστέρια, Gold, καταιγίδες που αντιμετώπισε και το καλύτερο εύρημα, με κορδέλα **Luckiest guild**), κουμπιά για να δεις μόνο ένα guild, και μία σελίδα για κάθε γύρισμα: ημερομηνία, τμήμα και εκπαιδευτικός, το Glory που έδωσε ή πήρε (μια απώλεια φαίνεται με μείον), και τέσσερις κάρτες μοίρας στο χρώμα της οικογένειάς τους, με την επιλογή που έκανε το guild (το σεντούκι που διάλεξε, το νόμισμα). Το **Show older spins** γυρίζει κι άλλες σελίδες. Χρησιμοποίησέ το στην αφήγηση του Grand Guild Ceremony και στις συζητήσεις με γονείς («το σπίτι είχε μια δύσκολη εβδομάδα στον τροχό και μετά ανέκαμψε»). Όταν τελειώσει η χρονιά, οι εγγραφές μένουν σε εκείνη τη χρονιά — το Ledger της νέας χρονιάς ξεκινά άδειο.

## Πώς τροφοδοτεί το υπόλοιπο Quest

| Είσοδος | Επίδραση στο guild |
|---------|--------------------|
| Award Stars | 2 Glory ανά αστέρι, για αυτό το Chapter και τη χρονιά |
| Hero’s Boon (+0.5) | Glory για το σπίτι του παραλήπτη |
| Quiz of the Week | Glory από τα αστέρια που κερδίζει κάθε παιδί με τις δικές του απαντήσεις |
| Fortune’s Wheel | Λίγο Glory για κάθε μέλος στο τμήμα, συν perks· μια καταιγίδα ή ένα twist μπορεί να πάρει λίγο πίσω |
| Mystic Market | Banner of Glory, Chalice of Unity, Guild Standard, Fortune’s Favor |
| Pathfinder / μπόνους Quest | Team Quest, όχι άμεσα το Crown Race. Τα perks του Wheel μπορούν να προσθέσουν και τα δύο |

Το Hero’s Challenge εξακολουθεί να κατατάσσει **μαθητές**, όχι guilds. Στείλε την τάξη στο Guild Hall για να *νιώσει* τον αγώνα των σπιτιών.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Το Guild Hall δεν υπάρχει σε αυτό το πλάνο | Σπίτια, Glory, Crown Race, Fortune’s Wheel, Fortune Ledger, Analytics, Grand Guild Ceremony | Ο ίδιος αγώνας guilds. Τα Familiars εμφανίζονται στην ιστορία του Ιουνίου |
`,

  'teacher/08-award-stars.md': `# Award Stars

Το Award Stars είναι η **καρδιά του Quest**. Σε κάθε μάθημα βάζεις 1, 2 ή 3 αστέρια σε μία από τέσσερις **δεξιότητες ζωής**. Αυτά τα αστέρια τροφοδοτούν Team Quest, Hero’s Challenge, Guild Glory, Gold, Familiars, Hero Path, το Adventure Log, τα bounties και την τελετή του μήνα.

Η καρτέλα ανοίγει κάτω από τον τίτλο της, ένα **μετάλλιο με αστέρι σε νυχτερινό ουρανό**, και είναι φτιαγμένη από **πλωτά σύννεφα**: κάθε μαθητής είναι ένα ζωγραφιστό σύννεφο με πορτρέτο, πουγκί Gold, έμβλημα guild, κορδέλα Hero Path, τρεις μετρητές (Ήλιος, Φεγγάρι, Αστέρι) και τέσσερα πετράδια αρετών.

## Σκοπός

Ονόμασε την **αρετή στην πράξη**, τη στιγμή που συμβαίνει — Teamwork, Creativity, Respect, Focus. Οι τέσσερις λόγοι δίνουν στην τάξη μια κοινή γλώσσα για την καλή συμπεριφορά όλη τη χρονιά, γι’ αυτό κράτα τους ορατούς. Το Scholar’s Bonus και τα αστέρια Story Weaver έρχονται από τις δικές τους τελετές, όχι από επιπλέον πετράδια σε αυτό το σύννεφο.

## Τι βλέπεις

Πάνω από τα σύννεφα, μια **σύνοψη ουρανού** μετρά πόσοι ήρωες λάμπουν σήμερα (μία κουκκίδα ανά μαθητή), πόσα αστέρια δόθηκαν και πόσοι περιμένουν ακόμα. Σε Bonus Day δείχνει επίσης **2× Star Day** ή την αρετή-μπόνους της μέρας (π.χ. **Respect Bonus Day**), και το πετράδι εκείνης της αρετής φορά ένα **+1**.

Κάθε **σύννεφο** έχει:

- Το **πορτρέτο** με το έμβλημα του guild, ένα μωβ βελάκι level-up όταν περιμένει δεξιότητα (Pro), και δίπλα το **πουγκί Gold**
- Την **κορδέλα Hero Path** και το όνομα, με τιμές από κάτω: **Hero of the Day +1**, **Prodigy of the Month**, **Birthday!**, **Name Day!** ή **Welcomed back**
- Τρεις μετρητές: τον **Ήλιο** (αστέρια σήμερα, με τρεις κουκκίδες που ανάβουν), το **Φεγγάρι** (αυτόν τον μήνα) και το **Αστέρι** (όλη τη χρονιά)
- Τα τέσσερα **πετράδια αρετών**, και μετά τα κουμπιά αστεριών

Ο Hero of the Day επιπλέει σε **χρυσό σύννεφο** με στέμμα. Ο Prodigy of the Month του προηγούμενου μήνα (ή οι Co-Prodigy μετά από ισοβαθμία) σε **μέντα σύννεφο**. Ένα σύννεφο γενεθλίων ή ονομαστικής γιορτής παίρνει γιορτινή απόχρωση. Τα σύννεφα αιωρούνται απαλά και σταματούν όσο κάνεις scroll, ώστε και τα παλιά laptop να μένουν ομαλά.

## Τέσσερις αρετές

| Κουμπί | Τι τιμά |
|--------|-----------------|
| **Teamwork** | Βοήθεια, δουλειά σε ζευγάρια, ακρόαση ενός συμμαθητή |
| **Creativity** | Μια νέα ιδέα, μια απρόσμενη πρόταση, παιχνιδιάρικα αγγλικά |
| **Respect** | Καλοσύνη, συμπερίληψη, φροντίδα για την αίθουσα |
| **Focus** | Προσπάθεια, προσοχή, επιμονή σε μια δύσκολη εργασία |

Πάτα πρώτα ένα πετράδι: ανάβει, το σύννεφο παίρνει το χρώμα της αρετής και σηκώνονται τρία κουμπιά αστεριών: **Spark** (1), **Shine** (2) και **Supernova** (3). Κάθε μέγεθος είναι μεγαλύτερη στιγμή. Το Spark χτυπά ένα καμπανάκι με μια μικρή έκρηξη. Το Shine σηκώνει το σύννεφο και ηχεί διπλά. Το Supernova φέρνει τύμπανο και συγχορδία καμπάνας, ανοίγει μια ηλιαχτίδα πίσω από το σύννεφο και ρίχνει βροχή αστεριών. Σε κάθε περίπτωση τα αστέρια πετούν μέσα στον Ήλιο.

Μετά το σύννεφο **σφραγίζεται**: τα κουμπιά αστεριών γίνονται μια σφραγίδα όπως **+2 ★ for Teamwork**, και το πετράδι που βραβεύτηκε κρατά τα αστέρια του. Για αναίρεση, πάτα το στρογγυλό κουμπί **Undo** πάνω δεξιά. Οι ήχοι και τα σωματίδια πρέπει να μοιάζουν με γιορτή, όχι με ένα σημάδι σε πίνακα.

Το **Scholar’s Bonus** και το **Story Weaver** **δεν** είναι κουμπιά εδώ. Το Scholar’s Bonus έρχεται από το **Starfall** μετά από υψηλό διαγώνισμα ή υπαγόρευση. Τα αστέρια Story Weaver έρχονται από την καρτέλα **Story Weavers** όταν το τμήμα φτάσει ένα ορόσημο γραφής.

## Welcome Back

Το σύννεφο ενός απόντα μαθητή γίνεται απαλό **γκρι σύννεφο βροχής** και τα πετράδια του μαζεύονται. Όταν ο μαθητής έλειπε το προηγούμενο μάθημα και το τμήμα έχει μάθημα σήμερα, το σύννεφο δείχνει ένα **γραφείο υποδοχής**: ένα κουμπί-ανατολή **Welcome back!**, και επίσης **Present** (χωρίς μπόνους) και **Away today**.

Τα αστέρια Welcome Back κλιμακώνονται με τα συνεχόμενα χαμένα προγραμματισμένα μαθήματα (με ματιά έως 30 μέρες πίσω):

| Σερί απουσιών | Αστέρια |
|---------------|-------|
| Κανένα (πρώτο καλωσόρισμα γκρι κάρτας) | **0.5** |
| 1 μάθημα | **0.5 ή 1.0** (τυχαία) |
| 2 μαθήματα | **1.5** |
| 3 ή περισσότερα | **2.0** |

Το Welcome Back **δεν κλειδώνει** την κάρτα. Μπορείς ακόμα να δώσεις αστέρι αρετής στο ίδιο μάθημα. Αυτή είναι η παιδαγωγική: η επιστροφή τιμάται, και μετά το παιδί εξακολουθεί να *παίζει* σήμερα.

Στο Pro, τα αστέρια Welcome Back ανεβάζουν επίπεδο και στο Hero Path **Nomad**.

## Γενέθλια και ονομαστικές γιορτές

Στο **πρώτο κλικ αστεριού** της ξεχωριστής μέρας του μαθητή (όταν ταιριάζει με το ημερολόγιο του σχολείου):

- **Happy Birthday!** → **+2.5** αστέρια
- **Happy Nameday!** → **+1.5** αστέρια

Καταγράφονται ως μπόνους με το όνομα της περίστασης. Όρισε τις ημερομηνίες στο προφίλ του μαθητή (AI Nameday Lookup στο Elite για το ελληνικό ορθόδοξο εορτολόγιο). Τα reminder pills του Home και οι κάρτες του Projector ανακοινώνουν επίσης τη μέρα.

## Hero’s Boon (peer gift)

Το κουμπί καρδιάς σε ένα σύννεφο: **Bestow Hero’s Boon**.

Είναι **γενναιοδωρία μαθητή προς μαθητή**, πληρωμένη σε Gold.

| Κανόνας | Λεπτομέρεια |
|------|--------|
| Δώρο | Ο παραλήπτης παίρνει **+0.5** αστέρια Total και Monthly (τροφοδοτεί το Guild Glory) |
| Κόστος | **15 Gold** από αυτόν που δίνει |
| Δωρεάν | Μήνας **Compassion Token**, ή συσσωρευμένες δωρεάν χρήσεις |
| Ημερήσιο όριο | **4** δώρα συμμαθητών **ανά τμήμα ανά μέρα** |
| Ποιος μπορεί να πάρει | Οι **3** τελευταίοι στα αστέρια αυτού του μήνα, **ή** όποιος είναι σε **ομάδα ισοβαθμίας** (ίδιο σύνολο μηνιαίων αστεριών με κάποιον άλλον) |
| Στον εαυτό | Ποτέ |
| Επανάληψη | Δεν μπορείς να δώσεις στον **ίδιο** συμμαθητή δύο φορές στη σειρά |

Η καρδιά κάθεται στην πάνω αριστερή γωνία του σύννεφου. Όταν ο μαθητής μπορεί να πάρει boon, λάμπει ροζ με ταμπελάκι **+½**. Όταν δεν μπορεί (ή το τμήμα έχει ήδη δώσει 4 boons σήμερα), μένει αχνή. Εξήγησε τους κανόνες μία φορά· τα παιδιά θα φυλάξουν τη δικαιοσύνη καλύτερα από ένα κήρυγμα.

Στο **Pro**, το να δίνεις boons ανεβάζει επίπεδο στο Hero Path **Patron** (δες το κεφάλαιο Hero Path): το πρώτο δώρο κάθε ημερολογιακής εβδομάδας κερδίζει ένα path point, και αυτός που δίνει παίρνει πίσω **+10 Gold**, οπότε ένα πληρωμένο δώρο κοστίζει στο τέλος 5 Gold (τίποτα, αν το Compassion Token το έκανε δωρεάν). Αυτός που δίνει δεν κερδίζει ποτέ αστέρια κατάταξης.

Μην το μπερδεύεις με:

- το **Teacher Boon** (το δικό σου δώρο, παρακάτω)
- το **Hero of the Day +1** στο χρυσό σύννεφο. Το πρώτο αστέρι του Hero of the Day κάθε μέρα φέρνει αυτόματα ένα αστέρι μπόνους· το Adventure Log το σημειώνει ως **«Includes Hero’s Boon (+1 Bonus Star)»**. Είναι ημερήσιο προνόμιο, όχι δώρο 15 Gold

## Teacher Boon

Τις **τελευταίες 7 μέρες του μήνα** (από έξι μέρες πριν το τέλος του μήνα μέχρι την τελευταία μέρα), μια ροζ-χρυσή **σφραγίδα δώρου** εμφανίζεται πάνω από τα σύννεφα: **Month’s end gift · Teacher Boon**, με ένα ταμπελάκι **+2 ★**. Τον υπόλοιπο μήνα δεν υπάρχει, και μόλις δώσεις το boon αυτού του μήνα για το επιλεγμένο τμήμα, εξαφανίζεται μέχρι τον επόμενο μήνα.

Πάτα την και το παράθυρο Teacher Boon σε οδηγεί σε τρία βήματα:

1. **Hero** — «Who shone brightest this month?» Όλοι οι μαθητές του τμήματος, ταξινομημένοι κατά τα αστέρια αυτού του μήνα (οι τρεις πρώτοι έχουν ένα μικρό σήμα θέσης).
2. **Reason** — «What are you celebrating?» Πάτα Leadership, Perseverance, Kindness, Bravery, Helping Others ή Remarkable Growth, ή γράψε δικά σου λόγια κάτω από το **or in your own words**.
3. **Bestow** — μια κάρτα με τον μαθητή, δύο αστέρια και τον λόγο σου. Πάτα **Bestow boon**· εμφανίζεται το **Boon bestowed!** και το παράθυρο κλείνει μόνο του.

Χρησιμοποίησε **Continue** και **Back** για να κινηθείς ανάμεσα στα βήματα, ή πάτα ένα βήμα που έχεις ήδη ολοκληρώσει.

- **2 αστέρια**, πάντα
- **Μία φορά ανά τμήμα ανά μήνα**
- Φαίνεται ως κορδέλα στην Ceremony of the Month

Χρησιμοποίησέ το για χαρακτήρα που τα τέσσερα κουμπιά δεν μπορούν να ονομάσουν ακριβώς. Μην το χρησιμοποιείς για να «διορθώσεις» τον αγώνα του Prodigy την τελευταία ώρα.

## Έλεγχοι απουσίας στα σύννεφα

Χωρίς να ανοίξεις το Chronicle μπορείς:

- να σημειώσεις **Absent** σήμερα με το μικρό κουμπί στη γωνία (ανθρωπάκι με γραμμή) σε σύννεφο που δεν έχει πάρει ακόμα αστέρι
- να το αναιρέσεις με **Mark present** στο γραφείο **Away today** του γκρι σύννεφου
- να προσφέρεις **Welcome back!**, ή να σημειώσεις **Present** ή **Away today**, στο γραφείο υποδοχής

Το πλήρες ιστορικό του μήνα ζει στο Adventure Log → **Attendance Chronicle** (Pro).

## Quest Bounties

Σύντομες προκλήσεις όλου του τμήματος, που ανεβαίνουν από το κουμπί **Bounty** στο **Home** του τμήματος (μια αφίσα bounty σε περγαμηνή· δες Home). Υπάρχουν δύο είδη: **Star Hunt** (κερδίστε μαζί έναν αριθμό αστεριών, μέσα σε δύο ώρες από το κάρφωμα, για ένα δηλωμένο έπαθλο όπως πέντε λεπτά ελεύθερου χρόνου) και **Race the Clock** (τελειώστε μια εργασία πριν τελειώσει μια αντίστροφη μέτρηση). Κάθε αστέρι που δίνεις εδώ γεμίζει ένα ενεργό Star Hunt· τα ζωντανά bounties κάθονται στον πίνακα bounties στην κορυφή της οθόνης και στο Projector Mode. Το **Time Warp Hourglass** προσθέτει πέντε λεπτά στις αντίστροφες μετρήσεις που τρέχουν. Όταν πιάνεται ο στόχος ακούγεται φανφάρα.

## Πώς τροφοδοτεί το υπόλοιπο Quest

Ένα άγγιγμα μπορεί:

- να κινήσει το Team Quest στον χάρτη
- να αλλάξει τη σειρά στο Hero’s Challenge
- να προσθέσει Guild Glory
- να προσθέσει Gold (και Gold του Hero Path)
- να εκκολάψει ή να εξελίξει ένα Familiar
- να μετρήσει στις ισοβαθμίες του Prodigy (αστέρια 3 vs 2 vs μοναδικοί λόγοι)
- να εμφανιστεί στο σημερινό Adventure Log
- να γεμίσει μια μπάρα bounty

Γι’ αυτό οι τέσσερις λόγοι πρέπει να μένουν τίμιοι. Φουσκωμένα 3άρια σε κάθε μάθημα αδειάζουν την τελετή από νόημα.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Τέσσερις δεξιότητες ζωής, Welcome Back, γενέθλια και ονομαστικές γιορτές, Hero’s Boon, Teacher Boon, bounties | Τίτλοι Hero Path και βέλη ανόδου επιπέδου. Attendance Chronicle | Εικόνες Familiar στα σύννεφα. AI nameday lookup |
`,

  'teacher/09-adventure-log.md': `# Adventure Log

Το Adventure Log είναι το **τελετουργικό κλεισίματος** του μαθήματος. Η καρτέλα είναι το **ημερολόγιο** της ίδιας της τάξης: η τάξη στέφει πρώτα τον **Hero of the Day**, μετά γράφεις (ή αφήνεις το Elite να γράψει) τη σημερινή σελίδα, και δύο ιπτάμενα κουμπιά φροντίζουν τη **δουλειά για την επόμενη φορά** και το **ποιος ήταν εδώ**.

## Σκοπός

Κάνε την ώρα **ιστορία που ανήκει στην τάξη**. Τα παιδιά θυμούνται αφηγήσεις. Ένα ημερολόγιο που ονομάζει αρετές, έναν ήρωα και την επόμενη αποστολή έχει περισσότερη δύναμη από ένα τικ σε παρουσιολόγιο.

## Crown Today’s Hero και μετά η σελίδα

Χρειάζεται επιλεγμένο τμήμα και **αστέρια που δόθηκαν σήμερα**. Μία σελίδα ανά τμήμα ανά μέρα. Το μεγάλο κουμπί αλλάζει όσο κλείνει το μάθημα, και μια σύντομη γραμμή από κάτω σου λέει πού βρίσκεσαι:

| Κουμπί | Πότε | Τι κάνει |
|--------|------|----------|
| **Crown Today’s Hero** | Έχουν δοθεί αστέρια και δεν έχει στεφθεί ακόμα κανείς | Με ένα πάτημα παίζει η αποκάλυψη του Hero of the Day. Η σελίδα αποθηκεύεται αμέσως ως **κενή σελίδα με στέμμα**, ώστε το στέμμα, το +1 και η έκπτωση στο Market να ισχύουν αμέσως. |
| **Write Today’s Page** | Έχει στεφθεί, η σελίδα είναι ακόμα κενή | Ξανανοίγει το **Today’s Page** (παρακάτω). |
| **Open Today’s Page** | Η σελίδα έχει γραφτεί | Πηγαίνει το ημερολόγιο στη σημερινή σελίδα και την φωτίζει. |

**Today’s Page.** Όταν πατήσεις **Huzzah!**, εμφανίζεται μια κάρτα με το πορτρέτο του ήρωα σε κορδέλα, με όσα έφερε η μέρα (αστέρια — όχι για Pre-Junior —, οι αρετές που φάνηκαν περισσότερο, νέες λέξεις, στιγμές μάθησης) και την ερώτηση *Shall we write today’s page?*

- **Auto** (Elite, πλήκτρο **A**): ο AI Chronicler γράφει ολόκληρη τη σελίδα και ζωγραφίζει εικόνα. Η κάρτα δείχνει για λίγο *The Chronicler dips the quill…* και μετά η σελίδα εμφανίζεται στο ημερολόγιο με σφραγίδα **Being written** μέχρι να τελειώσει. Μπορείς να τη διορθώσεις μετά. Στο Pro η κάρτα γράφει **Elite** και εξηγεί το πλάνο.
- **Manual** (πλήκτρο **M**): ανοίγει το **Write today’s page**, όπου γράφεις μόνος σου τα πάντα (παρακάτω).
- **Later: keep the page blank for now** (ή Esc): η σελίδα με το στέμμα περιμένει στο ημερολόγιο ως **A page waiting for its story**, με σφραγίδα **Blank page**, το αυτοκόλλητο του ήρωα, το **Write it myself** και (Elite) **Auto or Manual**. Μια σελίδα που έμεινε κενή άλλη μέρα γράφει **This page was never written** και μπορεί ακόμα να γραφτεί.

Το Campfire ανάβει μόνο αφού έχεις διαλέξει πώς θα γραφτεί η σελίδα, ώστε ο Chronicler να ξεκινά πάντα πρώτος.

**Write today’s page (Manual).** Μια σελίδα ημερολογίου με **Title**, **Today’s story**, **Highlights** (έως τέσσερα, χωρισμένα με κόμμα), το αυτοκόλλητο του **Hero of the Day**, **Picture** και **What we learned today**. Βοηθήματα που μπορείς να πατήσεις:

- **Ideas** κάτω από τον τίτλο: τρεις ιδέες τίτλου με βάση την ισχυρότερη αρετή της ημέρας (π.χ. *Stronger Together* για το Teamwork).
- **Need a spark?** κάτω από την ιστορία: αρχές προτάσεων (*Today our quest began with…*, *The bravest moment was when…*, *[Hero] wore the crown today because…*, *Next time, we will…*) και chips **Today’s words** που ρίχνουν μια λέξη μέσα στην ιστορία. Από κάτω μετρά τις λέξεις.
- **Picture:** **Upload your picture** (JPG, PNG ή WebP έως **8 MB**) ή, στο Elite, **Paint it from my words**, που ζωγραφίζει εικόνα από τον τίτλο και την ιστορία που έχεις γράψει ως τώρα (γράψε πρώτα λίγες γραμμές).

Το **Save today’s page** την αποθηκεύει στο ημερολόγιο (δουλεύει και το Ctrl + Enter). Αν κλείσεις πριν αποθηκεύσεις, ο τίτλος, η ιστορία και τα highlights κρατιούνται **σε αυτή τη συσκευή** και επιστρέφουν την επόμενη φορά. Αν στο μεταξύ η σελίδα γράφτηκε αλλιώς (π.χ. Auto από άλλον υπολογιστή), η αποθήκευση σταματά και τα λόγια σου μένουν ως πρόχειρο.

Στην κορυφή της καρτέλας βρίσκεται το γραφείο του ημερολογίου:

- **Καρτέλες μηνών** στην άκρη, σαν διαχωριστικά σε τετράδιο, από την αρχή της σχολικής χρονιάς μέχρι το **now**. Πάτα μία για να γυρίσεις σε εκείνον τον μήνα.
- **This month in the diary**: σελίδες, ήρωες που στέφθηκαν, νέες λέξεις και σημειώσεις δασκάλου για τον μήνα που βλέπεις.
- **Crown Today’s Hero** (αργότερα **Write Today’s Page** / **Open Today’s Page**), **Hall of Heroes** και, από κάτω, **Ember Oaths** (δες το κεφάλαιο Hero Campfire).

| Πλάνο | Τι γίνεται |
|------|----------------|
| **Starter** | Το ημερολόγιο δεν περιλαμβάνεται. Το Quest Assignment και οι παρουσίες στα σύννεφα του Award Stars λειτουργούν κανονικά. |
| **Pro** | **Crown Today’s Hero** και μετά **Manual**: γράφεις όλη τη σελίδα (τίτλος, ιστορία, highlights, εικόνα που ανεβάζεις, τι μάθαμε). Εσύ είσαι ο χρονογράφος. |
| **Elite** | Μετά το στέμμα, το **Auto** αφήνει τον **AI Chronicler** να γράψει τη σελίδα και να ζωγραφίσει εικόνα παραμυθιού (δες τις σφραγίδες παρακάτω όσο δουλεύει), ή **Manual** με **Paint it from my words**. Μπορείς να διορθώσεις κάθε σελίδα. |

Κάθε μέρα γίνεται μια **σελίδα ημερολογίου**, η νεότερη πρώτη: σφραγίδα ημερομηνίας, ο τίτλος, ένα αυτοκόλλητο **Hero of the Day** με το πορτρέτο του ήρωα, η εικόνα κολλημένη σαν φωτογραφία (Elite), η ιστορία σε γραμμές τετραδίου, τα highlights σαν χρωματιστές ταινίες και το αυτοκόλλητο χαρτάκι σου αν πρόσθεσες ένα. Μια μικρή γραμμή λέει **Written by hand** ή **Written by the Chronicler**· όσο το Elite δουλεύει ακόμα, μια σφραγίδα δείχνει **Being written**, **Rewriting**, **Waiting for the Chronicler** ή **Needs a retry**.

Κουμπιά στο κάτω μέρος κάθε σελίδας:

- **Retry**: μόνο σε σελίδα Elite που δεν ολοκληρώθηκε· ζητά από τον Chronicler να ξαναπροσπαθήσει.
- **Edit**: ανοίγει το **Edit this page** (τίτλος, ιστορία, highlights, εικόνα, τι μάθαμε) και **Save changes**. Στο Pro διορθώνεις τις σελίδες που έγραψες με το χέρι· στο Elite κάθε σελίδα.
- **Add note** / **Note**: **A note for this page**, ένα αυτοκόλλητο χαρτάκι με την υπογραφή σου. Το **Stick it on** το αποθηκεύει· άφησέ το κενό για να το αφαιρέσεις.
- **Remove**: διαγράφει τη σελίδα (μια κενή σελίδα με στέμμα δείχνει μόνο αυτό το κουμπί).

Το **Mask of the Protagonist**, το Pathfinder, τα τεστ και τα bounties μπορούν να χρωματίσουν την ιστορία που λέει το AI (ή εσύ).

### Ένας Chronicler που θυμάται όλο το μάθημα (Elite)

Όταν διαλέξεις **Auto**, ο Chronicler μαζεύει πρώτα μια χρονολογημένη εικόνα της μέρας του τμήματος, ακόμη και από καρτέλες που δεν άνοιξες. Μετά γράφει λίγες συνδεδεμένες παραγράφους για τα πραγματικά αγγλικά του τμήματος, για όσα έκαναν τα παιδιά και για την κοινή ιστορία, όχι μια γενική σύνοψη αστεριών.

- **Μάθηση:** διαγωνίσματα και υπαγορεύσεις (τίτλοι και ποιοι συμμετείχαν, ποτέ ατομικοί βαθμοί), θέματα και λέξεις του Quiz of the Week, προτάσεις και ολοκληρωμένες ιστορίες Story Weavers, τα βιβλία που καταγράφηκαν στο Quest Assignment, το What we learned today και το ίδιο το Quest Assignment.
- **Το ημερολόγιο:** Special Quests (σημερινά, σε εξέλιξη και προσεχή), 2× Star Day ή Reason Bonus Day, σχολικές αργίες που τρέχουν, έρχονται (τις επόμενες **14 ημέρες**) ή μόλις τελείωσαν (τις τελευταίες **7 ημέρες**), γενέθλια και ονομαστικές γιορτές, και τυχόν περίσταση του Festival Stall. Το Festival Stall δίνει μόνο εποχική ατμόσφαιρα, όχι απόδειξη ότι η τάξη γιόρτασε. Τα διαγωνίσματα και τα quests που είναι απλώς προγραμματισμένα περιγράφονται ως προγραμματισμένα, και η εργασία που ανατέθηκε σήμερα αφορά το επόμενο μάθημα.
- **Η κοινή περιπέτεια:** παρουσίες, αστέρια και πράξεις που αναγνώρισες, Hero’s Boon και Teacher Boon, Bounties, Fortune’s Wheel, Guild Hall και Team Quest, Hero Paths και skills, Familiars, αγορές στο Market σήμερα, Pathfinder’s Map, Hero Campfire, Ember Oaths και τελετές. Όσα είχε ήδη ένα παιδί δεν ξαναλέγονται ως νέα επιτεύγματα σήμερα. Ένας πρόσφατος ουρανός της τάξης μπορεί να προσθέσει ατμόσφαιρα.
- **Συνέχεια:** οι πρόσφατοι τίτλοι και τα highlights του ημερολογίου βοηθούν να αλλάζει η φωνή και να δένει η ιστορία· δεν ξαναλέγονται ποτέ ως σημερινά γεγονότα. Οι σελίδες που έμειναν κενές παραλείπονται.

Ο Chronicler δεν επινοεί δραστηριότητες για να γεμίσει μια άδεια ενότητα. Αφήνει έξω ιδιωτικά μηνύματα οικογενειών, στοιχεία λογαριασμών, ατομικούς βαθμούς και τις ιδιωτικές σου σημειώσεις. Τα Ember Oaths εμφανίζονται μόνο ως ανώνυμη δραστηριότητα: ποιος τα έκανε, τι υποσχέθηκε, οι ενδείξεις και οι ιδιωτικοί στοχασμοί μένουν ιδιωτικά. Οι ιστορίες για Pre-Junior αποφεύγουν αριθμούς, βαθμούς και συγκρίσεις. Αν μια σελίδα χρειαστεί νέα προσπάθεια, ή χρησιμοποιήσεις το **Ask the Chronicler**, δουλεύει από την ίδια εικόνα της μέρας, και ένας έλεγχος του What we learned today ενημερώνει εκείνο το κομμάτι. Αν η απάντηση του AI είναι ελλιπής ή άχρηστη, η σελίδα μένει σημειωμένη για νέα προσπάθεια αντί να μοιάζει ολοκληρωμένη.

### Χειριστήρια εικόνας στο Edit

Στο **Edit this page**, το **Picture** έχει προεπισκόπηση και **Upload your picture** (JPG, PNG ή WebP έως **8 MB**, με αυτόματη συμπίεση), **Delete picture** και, στο Elite, **Retry AI picture**. Η νέα εικόνα βασίζεται στον τίτλο και στην ιστορία που βλέπεις στον editor, χωρίς να ξαναγράφει το κείμενο. Στο Pro μπορείς να ανεβάζεις και να αφαιρείς εικόνες στις δικές σου χειρόγραφες σελίδες. Οι αλλαγές εικόνας εφαρμόζονται με **Save changes**· το **Cancel** αφήνει την αποθηκευμένη εικόνα όπως ήταν. Ό,τι ανεβάσεις, διαγράψεις ή διορθώσεις εσύ υπερισχύει πάντα: μια εικόνα που το AI ολοκληρώνει αργότερα δεν θα το αντικαταστήσει. Αν η δημιουργία εικόνας αποτύχει, μπορείς να ξαναδοκιμάσεις ή να ανεβάσεις δική σου από το Edit.

### Τι μάθαμε σήμερα

Κάθε σελίδα καταγράφει αυτόματα το **What we learned today**. Δεν χρειάζεται να το πληκτρολογήσεις. Η εφαρμογή το μαζεύει από ό,τι έκανε πραγματικά η τάξη εκείνη τη μέρα:

- **Quiz of the Week** που παίχτηκε σήμερα: τα θέματά του και τις λέξεις λεξιλογίου
- **Story Weavers** που ενημερώθηκε σήμερα: το Word of the Day
- **Special Quests** σήμερα: η αποστολή και η προτροπή της (οι λέξεις του Vocabulary Vault γίνονται λέξεις-στόχοι)
- Δοκιμασίες **Scholar's Scroll** σήμερα: οι τίτλοι τεστ ή ορθογραφίας, και ένα προγραμματισμένο τεστ για σήμερα
- **Quest Assignment** που αποθηκεύτηκε σήμερα: η επόμενη αποστολή

Στο **Elite**, ο AI Chronicler παίρνει αυτή τη λίστα και ενσωματώνει 2–3 από τις λέξεις ή τα θέματα στο ημερολόγιο, ώστε η τάξη να ακούσει ξανά τα σημερινά αγγλικά μέσα στη δική της ιστορία. Στις **Manual** σελίδες, η σελίδα που γράφεις δείχνει τα στοιχεία σαν τσεκαρισμένα chips: ξετσεκάρισε ό,τι δεν ταιριάζει ή πρόσθεσε δική σου γραμμή. Και τα δύο είναι προαιρετικά. Η σελίδα του ημερολογίου δείχνει μια λωρίδα **What we learned today** (θέματα και λέξεις), και το **Edit** σου επιτρέπει να τη διορθώσεις αργότερα.

## Hero of the Day

Δεν διαλέγεις τον ήρωα με το χέρι. Όταν πατάς **Crown Today’s Hero**, το Quest στέφει **αυτόματα** τον **Hero of the Day** και η τάξη βλέπει τον εορτασμό· η σελίδα του ημερολογίου γράφεται μετά. Αυτό είναι το τελετουργικό: στέφεται ένας παρών μαθητής και μετά λες την ιστορία της ώρας.

**Ποιος επιλέγεται**

1. Αν ένας παρών μαθητής έχει αγοράσει το **Mask of the Protagonist**, το στέμμα είναι εγγυημένα δικό του.
2. Αλλιώς η τάξη ακολουθεί **δίκαιη εναλλαγή**: όλοι οι παρόντες παίρνουν σειρά πριν ξαναρχίσει ο κύκλος· το ίδιο παιδί δεν επαναλαμβάνεται αμέσως όσο άλλοι περιμένουν.

Αν δεν είναι κανείς παρών, το ημερολόγιο μπορεί να τιμήσει «The Class Team».

**Προνόμια (όσο βασιλεύει, συν ο θρύλος αυτής της σχολικής χρονιάς)**

| Προνόμιο | Λεπτομέρεια |
|------|--------|
| Εορτασμός | Όνομα και «The Class Hero!» |
| Award Stars | Σύννεφο με σήμα **Reigning Hero** |
| Πρώτο αστέρι σήμερα | **+1 bonus αστέρι** («Includes Hero’s Boon (+1 Bonus Star)») — μία φορά |
| Mystic Market | **25% έκπτωση** στους εποχιακούς θησαυρούς όσο βασιλεύει |
| Νίκες φέτος | Rising Legend (3 νίκες) +5%, Golden (5) +10%, Mythic (10) +15%, μαζί με την έκπτωση ήρωα **με ανώτατο όριο 40%**. Οι μετρήσεις ξεκινούν από την αρχή κάθε σχολική χρονιά. |
| Home / Projector | Κάρτες προβολής |
| Hall of Heroes | Οι νίκες της χρονιάς |

Ο Hero of the Day **δεν** μοιράζει δωρεάν αστέρια, εκτός από εκείνο το **+1 στο πρώτο αστέρι**. Η ανταμοιβή είναι η προβολή και η έκπτωση στο Market.

Αυτό **δεν** είναι το Prodigy of the Month.

## Gather at the Campfire (Pro)

Όταν κλείσεις τον εορτασμό του Hero of the Day (**Huzzah!**) και διαλέξεις πώς θα γραφτεί η σελίδα (Auto, Manual ή Later), ανάβει ένα κουμπί **Gather at the Campfire** κάτω από τα Crown Today’s Hero και Hall of Heroes, στη θέση του κουμπιού Ember Oaths (κρατά ένα chip **Oaths**). Ανοίγει το **Hero Campfire**, έναν δίλεπτο στοχασμό κλεισίματος στον projector. Είναι προαιρετικό: το **Not today** το κρύβει για τη μέρα. Δες το κεφάλαιο Hero Campfire.

## Hall of Heroes

Κουμπί σε αυτή την καρτέλα. Μια πινακοθήκη με πορτρέτα των στεμμάτων **Hero of the Day** **αυτής της σχολικής χρονιάς** — ποιοι έγιναν το πρόσωπο πολλών μαθημάτων. Τα περσινά πορτρέτα μένουν στην περσινή χρονιά.

- Τρεις πλάκες επάνω: **crowns awarded**, **heroes crowned**, **still waiting**.
- Οι τρεις πρώτοι κρέμονται σε μεγάλες κορνίζες (**First**, **Second**, **Third**), οι υπόλοιποι στο **The gallery**. Κάθε κορνίζα δείχνει πόσα στέμματα, τη βαθμίδα θρύλου (**Rising Legend**, **Golden Legend**, **Mythic Legend**) με την έκπτωσή της στο Market, μια μπάρα μέχρι την επόμενη βαθμίδα και την ημερομηνία που στέφθηκε τελευταία φορά.
- Το **Waiting for their first crown** δείχνει όσους δεν έχουν στεφθεί ακόμα, ώστε κανένα παιδί να μη μένει αόρατο.
- Υπόμνημα στο κάτω μέρος: 3 στέμματα · Rising Legend · 5% off, 5 · Golden · 10%, 10 · Mythic · 15%.

Το **Hall of Prodigies** (Hero’s Challenge) είναι το μηνιαίο στέμμα μαθητή. Κράτα τα ονόματα χωριστά όταν μιλάς στην τάξη.

## Quest Assignment (αριστερό ιπτάμενο κουμπί)

Χρειάζεται τμήμα στην κεφαλίδα.

Ανοίγει το **Quest Board**, έναν πίνακα ανακοινώσεων από φελλό. Το **Pinned last time** δείχνει την προηγούμενη εργασία (μπορείς να πατήσεις **Edit**) και όποιο τεστ είχε προγραμματιστεί μαζί της. Το **For next lesson** είναι το σημειωματάριο όπου γράφεις τη νέα εργασία· οι αριθμημένες γραμμές γίνονται λίστα. Το **Schedule Test** καρφιτσώνει ένα τεστ (ημερομηνία, τίτλος, θέματα) στον πίνακα όταν το τμήμα χρησιμοποιεί τεστ· οι γονείς το βλέπουν μαζί με την εργασία. Το **Save Quest Board** αποθηκεύει.

Η αποθήκευση μπορεί να στείλει μια γραμμή εργασίας στο **Family Portal**, ώστε οι γονείς να βλέπουν την ίδια αποστολή χωρίς να βλέπουν τις ιδιωτικές σου σημειώσεις.

**Αναγνώριση βιβλίου (Pro).** Καθώς γράφεις, ένα μικρό chip κάτω από το κείμενο αναγνωρίζει το βιβλίο, το **μέρος** του (Student’s Book, Activity book, Companion / Language booster, Grammar book, Test book, Reader), την ενότητα και τις σελίδες. Καταλαβαίνει γραμμές όπως «PP2 un.4 pp.78-80», «SB p.42, GB unit 5», «PP2 activity book p.15», «yeti 2 language booster p.108», «CU B1 u.2 p.17», «σελ. 110-112» ή «Yeti 2 unit 13». Αυτό απλώς λέει στο **Hero Campfire** τι εξάσκησαν τα παιδιά· δεν αλλάζει ποτέ την εργασία που βλέπουν οι οικογένειες.

- **Επιβεβαίωση.** Πάτα **Yes, that’s it**, ή **Another book…** και πρόσθεσε ένα σύντομο θέμα. Όταν η εφαρμογή δεν είναι σίγουρη, ρωτά «Is this the right lesson?» με πορτοκαλί.
- **Περισσότερα από ένα βιβλία.** Ένα τμήμα μπορεί να χρησιμοποιεί πολλά βιβλία την ίδια μέρα. Το chip απαριθμεί κάθε βιβλίο που βρήκε και το **Choose the books** ανοίγει μια γραμμή ανά βιβλίο (Book, Part, Unit, Pages) με **＋ Add another book** για ένα βιβλίο γραμματικής, ένα activity book ή ένα companion.
- **Οι σελίδες συμπληρώνουν την ενότητα.** Όταν γράφεις σελίδες, η ενότητα συμπληρώνεται μόνη της όπου η εφαρμογή έχει χάρτη σελίδων για εκείνο το μέρος. Όπου δεν έχει, γράφεις εσύ την ενότητα.
- **Μεγαλύτερες ηλικίες.** Όταν διαλέγεις ενότητα, τα **Vocabulary pages** εμφανίζονται ως chips· πάτα το σετ σελίδων που δίδαξες πραγματικά, ώστε το Campfire να χρησιμοποιήσει μόνο εκείνες τις λέξεις. Τα junior μαθήματα διδάσκονται ως ένα ενιαίο μάθημα και δεν χρειάζονται περιορισμό.
- **Συντομεύσεις.** Μια γραμμή με μόνο σελίδα ή μέρος βιβλίου («p.40», «G.B. unit 5») χρησιμοποιεί το τρέχον βιβλίο του τμήματος. Οι λέξεις μετά από «words:», «φωτοτυπία:», «worksheet:» ή «elab:» κρατιούνται ως λέξεις της εργασίας, ακόμα κι όταν το βιβλίο είναι αβέβαιο.

Χρησιμοποίησέ το σε κάθε μάθημα αν μπορείς. Η συνέχεια είναι το κρυφό αναλυτικό πρόγραμμα.

## Attendance Chronicle (δεξί ιπτάμενο κουμπί)

**Pro.** Ανοίγει το **Attendance Chronicle** — το παρουσιολόγιο της τάξης, σχεδιασμένο σαν φιλικό τετράδιο, όχι βλοσυρό καθολικό. Ένα τικ σημαίνει παρών, ένα Χ απών.

Μπορείς να πάρεις παρουσίες στην **αρχή ή στο τέλος** του μαθήματος. Τα σύννεφα του Award Stars σημειώνουν επίσης απών/παρών/Welcome Back για σήμερα.

Στο Chronicle:

- Μετακινήσου **προηγούμενο / επόμενο μήνα** (από την αρχή της σχολικής χρονιάς μέχρι τον τρέχοντα μήνα)
- Οι μέρες **πριν από την ημέρα έναρξης** της χρονιάς σημειώνονται **Before lessons** — δεν μετρούν ποτέ ως μέρες μαθήματος (η Γραμματεία ορίζει την ημέρα έναρξης στο School Office → School Year → κάρτα *Opening day*)
- Ο **ζωντανός μήνας** επεξεργάζεται (*This month · tap a mark to change it*)· οι παλιότεροι μήνες είναι αρχείο μόνο για ανάγνωση (*Past month · read only*)
- Πανό αργιών· ράγα ημερών **Month at a glance**
- Σύνοψη: **μηνιαίο ποσοστό παρουσίας**, μαθήματα που έγιναν, συνολικές απουσίες, **Perfect Attendees**
- Πλέγμα: πάτα ένα σημάδι για να αλλάξεις παρών / απών
- Η διαγραφή μιας στήλης την κάνει μέρα **No Lesson**· το κουτάκι **Is this a School Holiday?** ορίζει αν μετρά για όλο το σχολείο ή μόνο για αυτό το τμήμα
- Μια μικρή σημείωση εξηγεί κάθε μέρα: σχολική αργία, ακύρωση, πριν αρχίσουν τα μαθήματα, μετά το τέλος της περιόδου, μάθημα ή χωρίς εβδομαδιαίο μάθημα

Τα *διαστήματα* αργιών για όλο το σχολείο ανήκουν στη **Γραμματεία**. Αυτό το παράθυρο είναι για μία μέρα και μόνο για αυτό το τμήμα.

Οι δάσκαλοι Starter σημειώνουν ακόμα παρουσίες στα σύννεφα του Award Stars· δεν έχουν αυτόν τον μηνιαίο πίνακα μέχρι το Pro.

## Πώς ταΐζει το υπόλοιπο Quest

- Ο Hero of the Day αλλάζει το Award Stars και το Market την επόμενη φορά που το παιδί ψωνίζει.
- Η εργασία φτάνει στις οικογένειες (Pro Family Access).
- Τα μοτίβα παρουσίας τροφοδοτούν το Welcome Back και την πρόοδο που βλέπουν οι γονείς.
- Η πρόταση του ημερολογίου εμφανίζεται στο Chronicle του Home και μπορεί να φανεί σε κάρτες του Projector.
- Κάθε στέμμα κρεμιέται στο Hall of Heroes και μετρά για τη βαθμίδα θρύλου του παιδιού.
- Το Mask of the Protagonist εξαντλείται στο επόμενο στέψιμο.

## Αξιοπρέπεια

Μην καταγράφεις ποτέ ένα μάθημα ως λίστα με όσους απέτυχαν. Ονόμασε αρετές, έναν ήρωα και την αποστολή της επόμενης φοράς. Διόρθωσε το κείμενο του AI αν είναι πολύ ξέφρενο για την ηλικία της τάξης.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Το Adventure Log δεν είναι σε αυτό το πλάνο. Παρουσίες στα σύννεφα Award Stars | Crown Today’s Hero, χειροκίνητο ημερολόγιο, Hall of Heroes, Attendance Chronicle, Quest Assignment. Συγχρονισμός εργασίας με τις οικογένειες όταν είναι ανοιχτό το Family Access | AI ιστορία και εικόνα παραμυθιού — μπορείς ακόμα να διορθώσεις |
`,

  'teacher/10-scholars-scroll.md': `# Scholar’s Scroll

Διαγωνίσματα, υπαγορεύσεις, γραφήματα, Pending Makeups, **Starfall**. Pro. Δεν υπάρχει κουμπί Scholar’s Bonus στο Award Stars — τα αστέρια έρχονται από εδώ.

**Log New Trial** ανοίγει τον **πίνακα βαθμολόγησης**: όλη η τάξη σε ένα φύλλο με γραμμές. Προγραμματισμένα διαγωνίσματα φαίνονται στο Home και στην ταπετσαρία Projector.

### Log a trial

Διάλεξε **Dictation** ή **Test** από τα καρτελάκια πάνω στο φύλλο (εμφανίζονται μόνο αν το τμήμα χρησιμοποιεί και τα δύο). Έλεγξε τη σφραγίδα ημερομηνίας (**Today** από προεπιλογή). Πάτα μια σφραγίδα βαθμού (ξανά για να τη σβήσεις) ή γράψε τον βαθμό και πάτα **Enter** για τον επόμενο μαθητή. Πάτα **Present** για να μαρκάρεις απόντα. Η μπάρα στο κάτω μέρος δείχνει πόσοι έχουν βαθμό. Τέλος **Save results**.

## Ο φάκελος του μαθητή (Scholar’s Folio)

Πάτα το όνομα ενός μαθητή στο Honour Roll (ή **Scholar’s Folio** στο Hero stats, ή **Folio** στη σελίδα του μαθητή) για να ανοίξει το **Scholar’s Folio** του: μία σελίδα με όσα λένε τα γραπτά του.

- **Κεφαλίδα:** πορτρέτο, Hero Path και τμήμα, η θέση του στην τάξη με βάση τον συνολικό μέσο όρο, η ζώνη του και ο μέσος όρος σε μετάλλιο με τη διαφορά από την τάξη. Τα βελάκια (ή ← / →) περνούν στον επόμενο μαθητή με τη σειρά του Honour Roll χωρίς να κλείσει.
- **Περίοδος:** 30 days, 3 months (προεπιλογή) ή Whole year (τα παλαιότερα γραπτά φορτώνουν μία φορά).
- **Overview:** Momentum (τα τρία τελευταία γραπτά απέναντι στα προηγούμενα), Best result, Latest και Presence (απουσίες των τελευταίων 30 ημερών και γραπτά χωρίς βαθμό). Το γράφημα **journey** δείχνει κάθε γραπτό με τη σειρά, με τον μέσο όρο της τάξης στο ίδιο γραπτό από πίσω· δείξε μια κουκκίδα για λεπτομέρειες, πάτα την για να πας σε εκείνο το γραπτό. Το **scribe’s reading** λέει απλά τι πάει καλά και τι θέλει προσοχή. Το **record** βάζει τα τεστ και τις υπαγορεύσεις απέναντι στην τάξη και δείχνει το Starfall του μήνα.
- **Trials:** κάθε γραπτό με βαθμό, ποσοστό, μέσο όρο τάξης, θέση σε εκείνο το γραπτό και πόσο πάνω ή κάτω από την τάξη ήταν. Σήματα δείχνουν **Top of class**, **Personal best** (καλύτερο από τουλάχιστον δύο προηγούμενα του ίδιου είδους) και βαθμούς Starfall. Πρώτα εμφανίζονται τα γραπτά που έγραψε το μεγαλύτερο μέρος της τάξης και ο μαθητής δεν έχει ακόμα βαθμό.
- **Oracle** (Elite): σημειώσεις για συνάντηση με γονείς, πλάνο επόμενων βημάτων, πού δυσκολεύεται, η πορεία ως τώρα ή δική σου ερώτηση, γραμμένα από τους αριθμούς του φακέλου. Διάβασε την απάντηση πριν τη μοιραστείς· το κουμπί αντιγραφής τη βάζει στο πρόχειρο.
- **Spreadsheet** (CSV) και **Print** (το παράθυρο εκτύπωσης αποθηκεύει και PDF) βρίσκονται πάνω δεξιά.

## Starfall

Μετά από μαζική αποθήκευση, το Quest μπορεί να προτείνει μπόνους αστέρια Scholar’s Bonus για εξαιρετικές επιδόσεις. Επιβεβαιώνεις τις προτάσεις μαζί, σε ένα παράθυρο. Τίποτα δεν είναι υποχρεωτικό. Το **Starfall Catalyst** διπλασιάζει το επόμενο υψηλό test bonus.
`,

  'teacher/11-quest-calendar.md': `# Quest Calendar

Το Quest Calendar είναι το **μηνιαίο πλέγμα της διδακτικής χρονιάς**: μέρες μαθήματος, σύνολα αστεριών, αργίες, ακυρωμένες μέρες και **Quest Events**. Πάτα μια μέρα για να ανοίξει το **Day Planner**.

## Σκοπός

Κρατά το Quest τίμιο απέναντι στον χρόνο. Ένας μήνας με την εβδομάδα του Πάσχα δεν πρέπει να ζητά τον ίδιο στόχο Team Quest με έναν γεμάτο διδακτικό μήνα. Οι ειδικοί τύποι μαθήματος πρέπει να φαίνονται *πριν* καθίσουν τα παιδιά.

## Τι βλέπεις (υπολογιστής)

Ένα μηνιαίο ημερολόγιο. Τα κελιά δείχνουν:

- Αν είναι **μέρα μαθήματος** (από τα προγράμματα των τμημάτων και τις έκτακτες αλλαγές)
- Τα **σύνολα αστεριών** που καταγράφηκαν εκείνη τη μέρα
- Εικονίδια για **Quest Events**
- Θέματα για **σχολικές αργίες** και μέρες **χωρίς σχολείο** (π.χ. Winter Break)

Στο **κινητό**, η ίδια καρτέλα είναι **ημερήσια ατζέντα** με Plan / Logbook, όχι στριμωγμένο μηνιαίο πλέγμα.

## Day Planner

Δύο καρτέλες: **Schedule** και **Quest Event**.

### Schedule

- Λίστα των τμημάτων που έχουν μάθημα εκείνη τη μέρα
- **Cancel** για ένα μάθημα του τμήματός σου. Το τμήμα κάνει λιγότερα μαθήματα τον μήνα, οπότε ο στόχος του Team Quest μειώνεται
- **Add a one-time lesson** — διάλεξε ένα σήμα τμήματος και μετά **Add lesson**
- **Mark as School Holiday** για ένα απρόοπτο κλείσιμο μίας μέρας

Τα σχολικά **διαστήματα αργιών** (Χριστούγεννα, Πάσχα, γενικά) δημιουργούνται στο **School Office** (Γραμματεία). Οι δάσκαλοι δεν επεξεργάζονται το ημερολόγιο όλου του σχολείου από τις Settings· αυτό είναι δουλειά του School Office. Το **My Planning** είναι μόνο η **τελευταία μέρα μαθήματος** κάθε τμήματος.

Το Day Planner έχει ακόμα το **Mark School Holiday** για **μία ημερομηνία**: ακυρώνει **όλα τα τμήματα** εκείνη τη μέρα και αναδιαμορφώνει τους στόχους. Χρησιμοποίησέ το για απρόοπτο κλείσιμο μίας μέρας· για το Winter Break και το Πάσχα χρησιμοποίησε το School Office.

### Quest Event

Διάλεξε μια κάρτα για την ημερομηνία, επίλεξε τμήματα (τα standard events καλύπτουν όλα τα τμήματα) και μετά **Summon Event**. Δύο οικογένειες:

**Standard events (η εφαρμογή τα εφαρμόζει αυτόματα στο Award Stars)**

| Event | Αποτέλεσμα |
|-------|------------|
| **2× Star Day** | Κάθε θετική απονομή αστεριών εκείνη τη μέρα **διπλασιάζεται** |
| **Reason Bonus Day** | Διάλεξε Teamwork, Creativity, Respect ή Focus. Οι απονομές με αυτόν τον λόγο παίρνουν **+1 επιπλέον αστέρι** |

**Special quests (τα τρέχεις εσύ στην τάξη· το ημερολόγιο κρατά τον στόχο και το μπόνους)**

| Quest | Ορίζεις | Στο μάθημα |
|-------|---------|------------|
| **Vocabulary Vault** | Στόχος (χρήσεις/προτάσεις) + αστέρια μπόνους ολοκλήρωσης | Οι μαθητές χρησιμοποιούν τις λέξεις-στόχους σε πραγματικά Αγγλικά· κάθε χρήση μετρά για το θησαυροφυλάκιο. |
| **The Unbroken Chain** | Μπόνους ολοκλήρωσης | Ευχέρεια: κρατάτε μια προφορική αλυσίδα χωρίς να σπάσει. |
| **Grammar Guardians** | Στόχος + μπόνους ολοκλήρωσης | Βρίσκουν και διορθώνουν λάθη· «σώζουν» προτάσεις. |
| **The Scribe’s Sketch** | Μπόνους ολοκλήρωσης | Ακούν και ζωγραφίζουν ό,τι ακούν. |
| **Five-Sentence Saga** | Μπόνους ολοκλήρωσης | Μια μικρή ιστορία με περιορισμούς (πέντε προτάσεις, δοσμένα υλικά). |

Διέγραψε ένα event από το ημερολόγιο όταν αλλάζουν τα σχέδια.

Κάθε Special Quest ανήκει σε ένα τμήμα και μπορεί να συνεχιστεί αργότερα. Αν επιλέξεις πολλά τμήματα, το καθένα παίρνει δικό του event. Όταν ξεκινά το quest, η εφαρμογή ελέγχει ποιοι είναι παρόντες. Όταν το ολοκληρώσεις, κάθε επιλεγμένο παιδί παίρνει τα αστέρια που διάλεξες και το ίδιο ποσό Gold, μία μόνο φορά — ακόμα κι αν πατήσεις το κουμπί δύο φορές. Το **Undo** είναι δυνατό μόνο όσο το Gold υπάρχει ακόμα για να επιστραφεί, και κρατά καθαρό αρχείο. Οι ανταμοιβές των Special Quests μετρούν για Team Quest, Guild Glory και Familiars, αλλά δεν είναι συνηθισμένες απονομές της ημέρας: δεν επηρεάζουν ποτέ Hero Path, Bounty, 2×/Reason Bonus Day, artifacts ή Hero of the Day.

### Τα πέντε σχήματα Quest (στο μάθημα)

Ο δάσκαλος προχωρά το quest από την οθόνη του μαθήματος. Το κουμπί **Projector** του runner δείχνει την προεπισκόπηση για την τάξη (σήμα, προαιρετικό prompt, μπάρα προόδου — χωρίς κουμπιά δασκάλου). Το **Controls** επιστρέφει στο runner. Αυτή η προεπισκόπηση δεν είναι η ταπετσαρία **Projector Mode** του **TV** στην κεφαλίδα.

Η οθόνη του quest έχει θεματικό banner (σήμα quest, Active ή Completed, και Stars / Gold ανά παιδί), μπάρα Quest Objective, ένα ζωντανό στοιχείο (πολύτιμοι λίθοι, ρούνοι γραμματικής, κρίκοι αλυσίδας, checklist του scribe ή σελίδες saga) και μετά τη λίστα με τα παιδιά που θα πάρουν την ανταμοιβή. Η εφαρμογή θυμάται πού σταμάτησες, ώστε να συνεχίσεις και μετά από refresh. Οι προεπιλεγμένοι στόχοι είναι σκόπιμα μικροί· μπορείς να τους αλλάξεις μέσα στα εύρη που φαίνονται παρακάτω:

| Quest | Στόχος και χειρισμός | Ολοκλήρωση |
|-------|----------------------|------------|
| **Vocabulary Vault** | 10 έγκυρες χρήσεις (εύρος 5–30). Το **Add Word Gem** μετρά μία χρήση. Το **Complete Quest** μένει ανενεργό μέχρι τον στόχο. Οι λίθοι του θησαυροφυλακίου φαίνονται στην οθόνη του δασκάλου. | Όταν επιτευχθεί ο στόχος |
| **Grammar Guardians** | 8 διασωσμένες προτάσεις (εύρος 3–20). Το **Rescued Sentence** μετρά μία διάσωση. | Όταν επιτευχθεί ο στόχος |
| **The Unbroken Chain** | 10 επιτυχημένες σειρές (εύρος 5–30). **Successful Turn**, **Chain Broke** (η τρέχουσα αλυσίδα ξεκινά από την αρχή· η καλύτερη αλυσίδα μένει). | Όταν επιτευχθεί ο στόχος |
| **The Scribe’s Sketch** | Τέσσερα κουμπιά: **Step 1: Listen**, **Step 2: Sketch**, **Step 3: Add details**, **Step 4: Reveal & describe**. Μπορείς να προσθέσεις ένα σύντομο prompt ακρόασης (έως 160 χαρακτήρες)· φαίνεται στον projector μόνο αν το επιλέξεις. | Και τα τέσσερα στάδια ολοκληρωμένα |
| **Five-Sentence Saga** | Ακριβώς πέντε θέσεις προτάσεων. Το **Submit Sentence** κλείνει την προηγούμενη πρόταση· κάθε πρόταση είναι προαιρετική και έως 240 χαρακτήρες. | Όταν ολοκληρωθεί η πέμπτη πρόταση |

Όταν ξεκινάς, επιβεβαιώνεις ποιοι είναι παρόντες: όσοι έχουν καταγεγραμμένη απουσία μένουν έξω, και αν δεν έχουν παρθεί παρουσίες, ξεκινούν επιλεγμένοι όλοι οι ενεργοί μαθητές. Μπορείς να προσθέσεις ή να αφαιρέσεις παιδιά πριν πατήσεις Complete. Η ανταμοιβή είναι 0,5, 1, 1,5 ή 2 αστέρια ανά παιδί, με το ίδιο ποσό Gold. Μετά το Complete, το **Undo** αναιρεί ολόκληρη την ολοκλήρωση, και μόνο όταν κάθε παιδί έχει ακόμα διαθέσιμο αυτό το Gold· δεν υπάρχει αναίρεση μόνο των αστεριών.

Μερικοί κανόνες κρατούν το ημερολόγιο καθαρό: ένα standard event ανά μέρα· όχι δεύτερο quest του ίδιου είδους για το ίδιο τμήμα την ίδια μέρα· και τα events δεν επαναλαμβάνονται. Τα standard events (**2× Star Day** και **Reason Bonus Day**) είναι **για όλο το σχολείο**: το Day Planner δείχνει ένα μόνο σήμα **All classes**, και το event ισχύει για κάθε τμήμα που έχει μάθημα εκείνη τη μέρα. Τα Special Quests μένουν ανά τμήμα, οπότε αν διαλέξεις πολλά τμήματα φτιάχνεται ένα event για το καθένα. Αν ένα επιλεγμένο τμήμα δεν έχει μάθημα εκείνη τη μέρα (αργία, ακύρωση ή όχι μέρα του), η εφαρμογή το ονομάζει και δεν αποθηκεύει μέχρι να λύσεις τη σύγκρουση στο ημερολόγιο. Παλιότερα Special Quests που αποθηκεύτηκαν χωρίς τμήμα δεν μπορούν να ξεκινήσουν.

Αυτά τα special quests **δεν** είναι το ίδιο με το Story Weavers (ολόκληρη καρτέλα) ή το Quiz of the Week (Home). Είναι **σχήματα μαθήματος μίας μέρας**.

## Πώς τροφοδοτεί το υπόλοιπο Quest

- Οι αργίες και οι ακυρώσεις **αναδιαμορφώνουν τους μηνιαίους στόχους Team Quest**.
- Οι μέρες 2× / Reason Bonus **αλλάζουν το Gold και τις κατατάξεις** εκείνη τη μέρα — ανακοίνωσέ τες ώστε κάθε τμήμα να περιμένει το μπόνους.
- Τα tests του Quest Board που προγραμματίζονται μέσω εργασιών εμφανίζονται ως ακαδημαϊκές ειδοποιήσεις, όχι ως αυτοί οι τύποι event.
- Το Home και ο Projector μπορούν να κάνουν αντίστροφη μέτρηση για αργίες και tests.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Χωρίς καρτέλα προγραμματισμού. Το Award Stars και ο χάρτης λειτουργούν κανονικά | Quest Calendar, Day Planner, Quest Events, ακυρώσεις μαθημάτων, My Planning (τελευταία μέρα τμήματος) | Το ίδιο ημερολόγιο. Τα σχολικά διαστήματα αργιών ανήκουν ακόμα στο School Office |
`,

  'teacher/12-story-weavers.md': `# Training Grounds

Η καρτέλα Training Grounds έχει **τέσσερα ομαδικά παιχνίδια, ένα για κάθε δεξιότητα ήρωα**. Διάλεξε παιχνίδι από τις τέσσερις καρτέλες στην κορυφή· η καθεμία δείχνει τη δεξιότητα, το όνομα και δύο μικρούς **κόμπους** για τους γύρους που έχουν δεθεί προς το επόμενο αστέρι.

| Παιχνίδι | Δεξιότητα | Με μια φράση |
|----------|-----------|--------------|
| ✒️ **Story Weavers** | Creativity | Η τάξη γράφει ένα βιβλίο, πρόταση με πρόταση, γύρω από μια Word of the Day |
| 🐉 **The Vanishing Hoard** | Focus | Κοιτάξτε τους θησαυρούς του δράκου και πείτε τι χάθηκε |
| 🗺️ **The Torn Map** | Teamwork | Κάθε ομάδα κρατά ένα κομμάτι του γρίφου· μόνο μαζί λύνεται |
| 🕯️ **The Round Table** | Respect | Η Speaking Stone περνά από χέρι σε χέρι, ο καθένας επαναλαμβάνει τον προηγούμενο, κανείς δεν διακόπτει |

Τα τρία νέα παιχνίδια έχουν τον ίδιο ρυθμό. Ένας γύρος μετρά μόνο όταν η τάξη τον κερδίζει, και μόνο **ένας γύρος ανά τμήμα ανά μέρα μαθήματος** δένει κόμπο (οι υπόλοιποι είναι ελεύθερη εξάσκηση). Κάθε **δεύτερος** κόμπος είναι **στιγμή αστεριού**: το Quest ρωτά αν θα δώσει **σε όλη την τάξη +0,5 αστέρια** εκείνης της δεξιότητας. Είναι μπόνους αστέρια, καταγράφονται με το όνομα του παιχνιδιού και δεν «τρώνε» το ημερήσιο αστέρι δεξιότητας κανενός παιδιού. Το Story Weavers κρατά τον δικό του ρυθμό (κάθε δεύτερη σελίδα), με το ίδιο +0,5. Κάθε παιχνίδι χτίζει και ένα **ενθύμιο** μέσα στα μαθήματα (ένα βιβλίο, ένα θησαυροφυλάκιο δράκου, έναν χάρτη, ένα λάβαρο του συμβουλίου)· τα ολοκληρωμένα μένουν σε ένα ράφι κάτω από το παιχνίδι.

Το περιεχόμενο ακολουθεί το **Quest League** του τμήματος: το Pre-Junior παίρνει εικόνες και τις πιο απλές λέξεις, τα Junior A και B σύντομες προτάσεις, τα A και B λίγο περισσότερα, και τα C και D μεγαλύτερους γρίφους και δυσκολότερες ερωτήσεις.

## Σκοπός

Κάθε δεξιότητα αποκτά ένα παιχνίδι που η τάξη εξασκεί από μάθημα σε μάθημα, όχι μόνο ένα κουμπί που πατά ο δάσκαλος. Και τα ντροπαλά παιδιά ανήκουν: η ιστορία χρειάζεται κάθε πρόταση, ο χάρτης κάθε ομάδα, το συμβούλιο κάθε φωνή. Κάθε παιχνίδι ανεβάζει επίπεδο στο Hero Path **Vanguard**.

## Story Weavers (Creativity)

Το Story Weavers είναι **συνεργατική δημιουργική γραφή**. Η τάξη χτίζει **μία ιστορία**, πρόταση με πρόταση, με μια **Word of the Day** και (στο Elite) μια εικονογράφηση για κάθε κλείδωμα. Οι ολοκληρωμένες ιστορίες μπορούν να **αφηγηθούν** φωναχτά και να **τυπωθούν ως PDF βιβλίο**.

### Τι βλέπεις

Διάλεξε τμήμα στην κεφαλίδα. Η καρτέλα ανοίγει σαν **βιβλίο ιστοριών**: η τελευταία εικόνα στην αριστερή σελίδα, η τελευταία πρόταση στη δεξιά (με αριθμούς σελίδων και μια κορδέλα για τη Word of the Day εκείνης της σελίδας). Κάτω από το βιβλίο βρίσκονται τα **Game Master Controls** και τα **Writing Helpers**.

Τα **Writing Helpers** ταιριάζουν με το Quest League του τμήματος:

- **Structure focus**: δύο ή τρία μοτίβα πρότασης για αυτό το league (π.χ. past continuous με *when* στο B, 1st conditional στο C, passive voice στο D), το καθένα με παράδειγμα. Πάτα ένα για να γίνει η εστίαση της επόμενης σελίδας· πάτα ξανά για να το καθαρίσεις. Η εστίαση φαίνεται στο πλαίσιο της πρότασης.
- **Sentence starters**: πάτα ένα για να ανοίξει η επόμενη σελίδα ήδη ξεκινημένη (κλείδωσε πρώτα τη Word of the Day). Το πλαίσιο της πρότασης δείχνει επίσης τη σημερινή λέξη και μια μικρή σειρά από αρχές προτάσεων.

Μέχρι να διαλέξεις τμήμα εμφανίζεται μήνυμα αναμονής.

### Τι μπορείς να κάνεις

1. **Word of the Day** — γράψε τη λέξη και κλείδωσέ τη (το τικ), ή **Suggest** (Elite AI). Καθάρισέ τη όταν χρειάζεσαι νέο γάντζο.
2. **Start Story…** / **Continue…** — πρόσθεσε την επόμενη πρόταση. Στο Elite δημιουργείται και μια εικονογράφηση και η σελίδα αποθηκεύεται στο ιστορικό της ιστορίας.
3. Κάθε **δεύτερη** προσθήκη, το Quest ρωτά αν θα δώσει **σε όλη την τάξη +0,5 αστέρια Creativity** (καταγράφονται ως Story Weavers). Πες ναι όταν η γραφή το άξιζε. Το **Archivist’s Quill** κάνει το επόμενο ομαδικό μπόνους εκείνου του μαθητή **1,0 αντί για 0,5**.
4. **Reveal to class** — η τελευταία σελίδα ως μεγάλο δισέλιδο (εικόνα και κείμενο), με το **Let's talk about it**: τρεις ερωτήσεις για να τις κάνεις φωναχτά (θυμήσου, φαντάσου ή ρώτα *γιατί*, και σύνδεσέ το με τη ζωή σου ή χρησιμοποίησε τη Word of the Day). Το **New questions** τις ανακατεύει. Αυτό είναι διαλογική ανάγνωση: τα παιδιά μιλούν για την ιστορία, δεν ακούν μόνο.
5. **Current Story** — το βιβλίο μέχρι τώρα.
6. **The End** — κλείνει αυτή την ιστορία.
7. **View Archive** — παλιά βιβλία.
8. **Start New** — ένα νέο quest.
9. Σε ολοκληρωμένο βιβλίο: **Narrate Story** (ομιλία), **Print Storybook** (PDF, θεματικές σελίδες) ή διαγραφή.

### Παιδαγωγική στην τάξη

- Κλείδωσε τη λέξη **πριν** από την πρόταση, ώστε ο περιορισμός να είναι παιχνίδι και όχι παγίδα στο τέλος.
- Άφησε διαφορετικά παιδιά να «κατέχουν» διαφορετικές προτάσεις μέσα στις εβδομάδες.
- Τύπωσε το PDF για τον διάδρομο ή για το portfolio του Ιουνίου. Τα παιδιά παίρνουν σπίτι την απόδειξη ότι τα Αγγλικά έφτιαξαν ένα *βιβλίο*.

Αυτή η καρτέλα είναι ξεχωριστή από το **Five-Sentence Saga** (ένα event μίας μέρας στο Calendar) και από το **Adventure Log** (το ημερολόγιο του δασκάλου για το μάθημα).

## The Vanishing Hoard (Focus)

Ένας δράκος κοιμάται πάνω στον θησαυρό του. Η τάξη κοιτάζει τους θησαυρούς (εικόνες με την αγγλική λέξη τους), η φτερούγα του δράκου τους σκεπάζει, και ένας ή περισσότεροι έχουν χαθεί. Η τάξη λέει τι λείπει και μετά ο θησαυρός αποκαλύπτεται.

1. **Gather the hoard** και άφησε την τάξη να κοιτάζει σιωπηλά όσο τρέχει η αντίστροφη μέτρηση (ή πάτα **The class is ready**).
2. Η φτερούγα του δράκου περνά και παίρνει τους κλεμμένους θησαυρούς· από το A και πάνω οι υπόλοιποι μπορεί και να αλλάξουν θέση.
3. Η τάξη κοιτάζει τι έμεινε, συζητά με τα πλαίσια προτάσεων και συμφωνεί τι λείπει, μετά **Check our answers**.
4. Γύρνα κάθε κλεμμένη κάρτα και σημείωσε **We said it** ή **Missed**. Αν ειπωθούν όλοι οι κλεμμένοι θησαυροί, ο θησαυρός σφραγίζεται και ανάβει ένας ρούνος.

Ο θησαυρός μεγαλώνει με κάθε ρούνο που ανάβει: περισσότεροι θησαυροί και περισσότερα χαμένα, και στα A έως D οι θησαυροί αρχίζουν να αλλάζουν θέση (στα C και D νωρίτερα). Άναψε το **Use this lesson’s words** για να μπει το λεξιλόγιο της εβδομάδας στους θησαυρούς. Οκτώ αναμμένοι ρούνοι σφραγίζουν ένα θησαυροφυλάκιο και ξεκινά το επόμενο.

## The Torn Map (Teamwork)

Ένας χάρτης θησαυρού έχει σκιστεί σε κομμάτια. Ο πίνακας δείχνει έναν γρίφο και τις πιθανές απαντήσεις. Κάθε **ομάδα** παίρνει ένα κομμάτι με ένα στοιχείο, και κάθε στοιχείο αποκλείει ακριβώς μία λάθος απάντηση, άρα καμία ομάδα δεν τον λύνει μόνη της.

1. **Unroll a riddle** ώστε όλοι να βλέπουν την ερώτηση και τις απαντήσεις.
2. **Deal the scraps**: μία ομάδα τη φορά έρχεται να δει το κομμάτι της ενώ οι άλλοι κλείνουν τα μάτια, ή **Print the scraps** για να μοιράσεις κάρτες.
3. **Pool the clues**: οι ομάδες λένε φωναχτά το στοιχείο τους με τα πλαίσια προτάσεων (*Our clue says… So it isn't the…*) και αποκλείουν απαντήσεις μαζί.
4. Διάλεξε την απάντηση που έμεινε. Η τάξη έχει **δύο προσπάθειες**: μια λάθος επιλογή ανοίγει ένα ακόμη κομμάτι για βοήθεια, μια δεύτερη λάθος χάνει τον γύρο, και η σωστή απάντηση επαναφέρει ένα κομμάτι του χάρτη.

Τα Pre-Junior και Junior A/B έχουν τέσσερις απαντήσεις και τρεις ομάδες· από το A και πάνω πέντε απαντήσεις και τέσσερις ομάδες. Έξι κομμάτια κάνουν ολόκληρο τον χάρτη, που μπαίνει στο **Map Chest**.

## The Round Table (Respect)

Το βασίλειο κάνει μια ερώτηση στο συμβούλιο. Μιλά μόνο όποιος κρατά τη **Speaking Stone**, και ο **Echo Rule** λέει ότι κάθε ομιλητής πρώτα επαναλαμβάνει κάτι που είπε ο προηγούμενος.

1. **Call the council** και διάβασε την ερώτηση. Τα πλαίσια προτάσεων βοηθούν τα παιδιά να πουν, να επαναλάβουν και να είναι ευγενικά.
2. Όρισε πόσοι **ομιλητές** θα μιλήσουν και δώσε την πέτρα στον πρώτο.
3. Για κάθε ομιλητή πάτα **Echoed!** όταν επαναλάβει τον προηγούμενο και **Interrupted** αν κάποιος μιλήσει εκτός σειράς, μετά **Pass the stone**. Κάθε ομιλητής έχει ένα ήπιο δαχτυλίδι χρόνου.
4. **Close the council** μετά τον τελευταίο ομιλητή. Το Quest προτείνει **ετυμηγορία**: το συμβούλιο τιμήθηκε όταν όλοι επανέλαβαν και κανείς δεν διέκοψε. Την τελευταία λέξη την έχεις εσύ: **The council was honoured** ή **Hold it again next lesson**.

Κάθε συμβούλιο που τιμήθηκε ανάβει ένα κερί· έξι κεριά ολοκληρώνουν ένα λάβαρο για το **Hall of Banners**.

## Στην τάξη

- Το μικρό **?** δίπλα στον τίτλο κάθε παιχνιδιού ανοίγει το **How to play**: τέσσερα βήματα με εικόνες, πώς κερδίζεις, και μια συμβουλή για σένα. Δουλεύει και σε full screen, για να το δείξεις στην τάξη.
- Κάθε παιχνίδι έχει **Full screen** για τον projector και **Stop this round** αν χτυπήσει το κουδούνι.
- Κάτω από τον πίνακα, η μπάρα **Game Master** δείχνει σε ποιο βήμα είναι ο γύρος και τι κάνεις τώρα. Πιο κάτω βρίσκονται το ράφι με τα ενθύμια και οι **Recent rounds**.
- Οι γύροι αποθηκεύονται στο τμήμα, άρα κάθε συσκευή δείχνει τους ίδιους κόμπους και τα ίδια ενθύμια.

## Πώς τροφοδοτεί το υπόλοιπο Quest

Τα αστέρια του Training Grounds είναι πραγματικά αστέρια: χάρτης, κατατάξεις, Glory, Gold. Κάθε ένα ανεβάζει επίπεδο στο Hero Path **Vanguard** και πληρώνει το Gold του Vanguard. Το Chronicle του Home μπορεί να δείχνει την τελευταία πρόταση της ιστορίας. Ο Projector μπορεί να δείξει την πρόταση (Elite).

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Το Training Grounds δεν υπάρχει σε αυτό το πλάνο | Το Training Grounds δεν υπάρχει σε αυτό το πλάνο | Και τα τέσσερα παιχνίδια, Word of the Day, εικονογραφήσεις. Τα ομαδικά μπόνους προσθέτουν αστέρια στα ίδια σύνολα |
`,

  'teacher/13-settings-and-roster.md': `# Teacher Settings, μαθητολόγιο, Family Access και ρύθμιση Quiz

Το γρανάζι στην κεφαλίδα ανοίγει τις **Teacher Settings** στα **My Classes**. Τα My Classes είναι **εδώ**, όχι στις δέκα καρτέλες. Το Student Roster δεν είναι καρτέλα· ανοίγει από το κουμπί **Students** ενός τμήματος.

## Σκοπός

Στήνεις τη σκηνή της σχολικής χρονιάς: τμήματα, πρόσωπα, ημερομηνίες, πόρτες για τους γονείς και (στο Elite) το εβδομαδιαίο quiz. Μετά γυρνάς στο Award Stars και διδάσκεις.

## Υποκαρτέλες

Κάτω από τον πίνακα με τον τίτλο, ένας **επιλογέας ενότητας** δείχνει πού βρίσκεσαι, με μια σύντομη υπόδειξη (π.χ. *My Classes · Your classes and rosters*). Πάτα **Switch** για να ανοίξει ένα μενού με όλες τις ενότητες, την καθεμία με την υπόδειξή της. Στο κινητό τα ίδια ονόματα ανοίγουν από ένα **φύλλο** (sheet). Κάθε ενότητα εμφανίζεται πάνω στο γραφείο του δασκάλου σαν δικό της κολλημένο φύλλο χαρτί.

| Υποκαρτέλα | Τι είναι |
|------------|----------|
| **My Classes** | Ανοίγει πρώτη. Δημιουργία/επεξεργασία τμημάτων και άνοιγμα του μαθητολογίου |
| **Student Tools** | Διόρθωση αστεριών, Gold ή Familiar στο χέρι, χωρίς να φαίνεται σαν μέρος του σημερινού μαθήματος |
| **My Planning** | Η **τελευταία μέρα μαθήματος** κάθε τμήματος (Pro) |
| **Profile** | Το **όνομα εμφάνισής** σου (το όνομα Quest Master στα ημερολόγια) και ο διακόπτης **Quest cursor** |
| **Class Grading** | Παράκαμψη των προεπιλογών αξιολόγησης της γραμματείας για το *δικό σου* τμήμα (Pro) |
| **Family Access** | Username και κωδικός γονέα για κάθε παιδί (Pro) |
| **Quiz** | Φτιάχνεις το Quiz of the Week (Elite) — το παίζεις στο **Home** |
| **Market** | Επιδιόρθωση Seasonal Treasures και Festival Stall (Elite) |

### Student Tools

Τρεις κάρτες ευρετηρίου δίπλα-δίπλα:

- **Student Star Manager** — διάλεξε μαθητή. Το **Add Historical Award** (ημερομηνία, αστέρια, λόγος, μαζί με Welcome Back Bonus και Manual Correction) προσθέτει βράβευση για μια παλιά ημερομηνία και την καταγράφει όπως κάθε άλλη. Το **Direct Score Override** (Today / Monthly / Total) αλλάζει τον αριθμό **χωρίς** εγγραφή στο ιστορικό — χρησιμοποίησέ το μόνο για να διορθώσεις λάθη.
- **Coin Purse Manager** — ορίζει το τρέχον Gold.
- **Familiar Sprite Forge** (Elite) — ξαναζωγραφίζει την εικόνα ενός Familiar αν απέτυχε η αρχική.

### My Classes

Κάθε τμήμα είναι μια κάρτα: έμβλημα, όνομα, Quest League, μέρες και ώρες. Τα κουμπιά της κάρτας είναι **Report** (εβδομαδιαία σύνοψη με AI + προτεινόμενο mini-quest στο Elite), **Edit**, **Students** (το μαθητολόγιο, παρακάτω), **Oaths** (ο πίνακας Ember Oaths του τμήματος, Pro) και ο **κάδος**, πάντα τελευταίος. Η διαγραφή τμήματος σβήνει και τους μαθητές του, γι’ αυτό η εφαρμογή ρωτά πρώτα.

Το **Add New Class** ανοίγει έναν **χάρτη ίδρυσης** (class charter): μια σελίδα ίδρυσης με το έμβλημα του τμήματος καρφιτσωμένο στην κορδέλα της.

1. Πάτα το έμβλημα για να ανοίξει η **θήκη εμβλημάτων** (*Choose a Class Logo*): ξεφύλλισε ένα συρτάρι ή ψάξε με όνομα και πάτα ένα έμβλημα για να το καρφιτσώσεις στο τμήμα σου.
2. **Class Name** — γράψε ένα, ή (Elite) πάτα τη σπίθα για τρεις ιδέες ονομάτων με AI, αφού διαλέξεις league.
3. **Quest Level (League)** — ηλικία και δυσκολία. Το league αυτό ορίζει τους συμμαθητές στον χάρτη, τον τόνο του Market, τη γλώσσα του Guild quiz και τη φωνή των πιστοποιητικών.
4. **Meets on** — πάτα τα μανταλάκια των ημερών και μετά τις ώρες **From** / **To**.
5. **Create Class**.

Το **Edit** αλλάζει αργότερα τα ίδια στοιχεία.

## Profile

Το **όνομα εμφάνισής** σου — το όνομα Quest Master στα ημερολόγια, στις τελετές και στον χαιρετισμό του Adventurer’s Guide. Ένα καρτελάκι προσωπικού δίπλα στο πεδίο δείχνει το όνομα καθώς γράφεις. **Save Name**.

Ο διακόπτης **Quest cursor** ανάβει ή σβήνει αμέσως τον γαλάζιο και χρυσό δείκτη του ποντικιού, μόνο για αυτόν τον browser. Σβήσε τον για να χρησιμοποιείς τον κανονικό δείκτη του υπολογιστή σου. Οι οθόνες αφής και η λειτουργία υψηλής αντίθεσης χρησιμοποιούν αυτόματα τον κανονικό δείκτη.

## Manage Students (το μαθητολόγιο)

Αυτή είναι η λίστα του τμήματος όπου ζεις. Η κεφαλίδα έχει **Classes** (πίσω), **New Student** και το πλήθος των μαθητών.

Το **New Student** σε αυτό το μαθητολόγιο προσθέτει όνομα στο *δικό σου* τμήμα. Το School Office μπορεί επίσης να κάνει **Add a new student** από το Admin· ο ήρωας αυτός μένει **δικός σου** να τον διδάξεις.

Αν ήρωες της περσινής χρονιάς περιμένουν ακόμα τμήμα, ένα χρυσό πάνελ **Returning adventurers** (*Student setup*) εμφανίζεται πάνω από το μαθητολόγιο με τον αριθμό όσων περιμένουν. Ξεκινά κλειστό. Άνοιξέ το για αναζήτηση, τσέκαρε μαθητές (πρώτα έρχονται οι προτάσεις, με βάση το περσινό league· κάθε κάρτα δείχνει το παλιό τμήμα και το league) και πάτα **Place Selected** — ένας μετρητής δείχνει πόσους τσέκαρες. Αυτή είναι η θέση του δασκάλου για τους περσινούς μαθητές — όχι ο οδηγός **Student placement** του School Office και όχι το **Add a new student**.

Κάθε γραμμή δείχνει avatar, όνομα, Hero Class ή τίτλο και ένα σήμα guild, και μετά **τα ίδια εργαλεία στις ίδιες θέσεις σε κάθε γραμμή**, σε τρεις ομάδες με λεζάντα (στο κινητό σπάνε σε δύο γραμμές):

| Ομάδα | Κουμπί | Τι κάνει |
|-------|--------|----------|
| **Hero path** | **Sort** (καπέλο μάγου) | Μόνο για μαθητή χωρίς guild: ανοίγει το **Sorting Ceremony**, το quiz τοποθέτησης σε guild (Pro· κλειδωμένο στο Starter). Μετά την κατανομή, η θέση δείχνει το έμβλημα του guild και δεν είναι πια κουμπί — το guild είναι για πάντα. |
| | **Class** (ασπίδα) | Μόνο αν δεν έχει ακόμα Hero Class: ανοίγει την τελετή **Hero Class** (Pro). Μόλις επιλεγεί, η θέση δείχνει την τάξη· η αλλαγή της μένει πίσω από το **Edit → Hero path**. |
| | **Skills** (sitemap) | Ανοίγει το Skill Tree (Pro). **Πάλλεται** όταν περιμένει νέο κλαδί. Δες το κεφάλαιο Hero Path. |
| **Records** | **Chronicle** (βιβλίο) | Hero’s Chronicle, το ιδιωτικό σου τετράδιο για αυτό το παιδί (παρακάτω). |
| | **Parents** (ασπίδα) | Πηγαίνει στο Family Access για αυτό το παιδί (Pro). |
| | **Avatar** (αστροναύτης) | Ανοίγει το **Avatar Forge** (Elite). Δείχνει λουκέτο στα άλλα πλάνα. |
| | **Certificate** (βραβείο) | PDF επαίνου. |
| **Manage** | **Move** | Στέλνει το παιδί σε άλλο τμήμα που διδάσκεις. |
| | **Edit** | Ανοίγει το **Adventurer’s Passport** του μαθητή (παρακάτω). |
| | **Delete** | Ζητά επιβεβαίωση και μετά αφαιρεί οριστικά τον μαθητή. Χρησιμοποίησέ το σπάνια. |

**Μαθητές που φεύγουν από το σχολείο:** το καταγράφει το School Office, όχι εσύ. Το παιδί βγαίνει από το μαθητολόγιό σου και το login του γονέα παγώνει· τα αρχεία του κρατιούνται. Αν το Office το φέρει πίσω στο τμήμα σου, επιστρέφει με τα αστέρια του και το login του γονέα ξαναλειτουργεί.

Ό,τι αλλάξεις στο Passport ενός μαθητή, για παράδειγμα το όνομά του, είναι αυτό που εμφανίζεται παντού: στα ημερολόγια και τις τελετές, στα εργαλεία AI (Avatar Forge, Oracle, αναφορές, πιστοποιητικά) και στο Family Portal.

## Adventurer’s Passport

Το **Edit** σε μια γραμμή του μαθητολογίου ανοίγει το προφίλ του μαθητή σαν ένα ανοιχτό διαβατήριο. Το εξώφυλλο έχει το όνομα και σήματα για το τμήμα και το guild.

**Αριστερή σελίδα — Identity:** το πορτρέτο (πάτα για να το δεις· το **New portrait** ανοίγει το Avatar Forge), **Name**, **Class** με **Move**, **Guild** (με **Sort** μόνο όσο δεν έχει guild) και το ιστορικό του quest: Total stars, This month, Gold, Hero rank. Από κάτω, **Open for this student**: Chronicle, Folio, Certificate, Avatar Forge, Skill Tree, Move class.

**Δεξιά σελίδα — Special days:** **Birthday** και **Nameday** σαν γραμματόσημα (διάλεξε μέρα και μήνα· το **Clear** αδειάζει ένα). Το **Find from name** είναι το **AI Nameday Lookup** (ελληνορθόδοξο εορτολόγιο) στο Elite. Τη μέρα τους η τάξη βλέπει πανό γιορτής και το παιδί παίρνει μπόνους αστέρια.

**Δεξιά σελίδα — Hero path:** μια βίζα με την τρέχουσα τάξη (ή No Class) και **Choose Hero Class** / **Change Hero Class** / **Your Path**. Αυτό ανοίγει την τελετή στον πίνακα — προεπισκόπηση και μετά **Swear this Path**. Το **Skill tree** βρίσκεται στην ίδια βίζα. Κρατούν την τάξη που έχουν. Κάθε σχολική χρονιά μπορούν να την αλλάξουν δύο φορές· η δεύτερη αλλαγή κλειδώνει το μονοπάτι μέχρι την επόμενη χρονιά. Το κεφάλαιο Hero Path δείχνει την οθόνη.

Το κάτω μέρος γράφει **Unsaved changes** όταν κάτι περιμένει. **Save Changes** ή **Cancel**.

## Avatar Forge

Elite. Άνοιξέ το από το **Avatar** στο μαθητολόγιο ή από το Passport. Το σιδηρουργείο φτιάχνει ένα πορτρέτο που φαίνεται στα μαθητολόγια, στα σύννεφα, στα πιστοποιητικά και στο Family Portal.

1. Διάλεξε **The Creature**, **The Colour** και **The Relic** (κάτι να κρατά ή να φορά). Κάνε πρώτα και τις τρεις επιλογές: το **Strike the Anvil** μένει ανενεργό μέχρι τότε.
2. Το **Tempering** είναι προαιρετικό και έχει ήδη καλές προεπιλογές: **Art style**, **Mood**, **Backdrop**, **Framing** και **A special touch** (λίγες λέξεις, π.χ. *freckles and a star-shaped badge*).
3. Το **Surprise me** διαλέγει τυχαία συνταγή. Το **Strike the Anvil** ζωγραφίζει το πορτρέτο.
4. **Keep this portrait** ή **Strike again**. Τα χτυπήματα αυτής της συνεδρίας μένουν σε μια σειρά κάτω από το αμόνι — πάτα ένα για να κρατήσεις εκείνο.

Το **Melt the current portrait** αφαιρεί το αποθηκευμένο πορτρέτο (ο μαθητής επιστρέφει στα αρχικά του).

## Hero’s Chronicle

Το **Chronicle** στο μαθητολόγιο (ή στο Passport) ανοίγει το δεμένο βιβλίο του ήρωα. Αυτό είναι το **δικό σου** τετράδιο — όχι το Adventure Log που ακούει η τάξη και όχι το Family Portal. Καρτέλες σελίδων στο πλάι: **Notes**, **Oaths**, **The Oracle**.

**Notes:** **History of Deeds** αριστερά, ένα χρονολόγιο με ημερομηνίες. **Write an entry** δεξιά: διάλεξε θέμα, γράψε τι έγινε, **Save Note**. Κατηγορίες στην εφαρμογή:

- 📓 **General**
- 🎓 **Academic**
- 🎭 **Behavior**
- 💬 **Social**
- 🎯 **Goals**

Μπορείς να επεξεργαστείς ή να σβήσεις μια εγγραφή (το **Cancel Editing** βγαίνει από την επεξεργασία). Οι οικογένειες δεν βλέπουν ποτέ αυτές τις σημειώσεις.

**Oaths** (Pro): τα Ember Oaths αυτού του παιδιού — δες το κεφάλαιο Hero Campfire.

**The Oracle** (Elite): **Ask the Oracle** για Parent Summary, Teacher Strategy, Traits & Trends (δυνατά / αδύνατα σημεία) ή Hero’s Goal. Διαβάζει σημειώσεις, βαθμούς δοκιμασιών και αστέρια. Εσύ αποφασίζεις τι θα κρατήσεις. Το **Publish to Parent Portal** γράφει μια σύνοψη κατάλληλη για γονείς που μπορούν να διαβάσουν οι οικογένειες — ο μόνος τρόπος να φτάσει κάτι από αυτό το βιβλίο σε αυτές.

Οι **σημειώσεις του Hero’s Chronicle** υπάρχουν σε κάθε συνδρομητικό πλάνο. Το Oracle είναι Elite.

## My Planning

Μόνο η **τελευταία μέρα μαθήματος** για το τμήμα της κεφαλίδας. Ένα φύλλο ημερολογίου δείχνει την ημερομηνία που διάλεξες· το **Use suggested** διαλέγει την τελευταία προγραμματισμένη μέρα του Ιουνίου. **Save for this class**. Άφησέ το κενό αν το τμήμα τρέχει όλη τη χρονιά. Μετά από αυτή την ημερομηνία το τμήμα βγαίνει από τα ημερήσια προγράμματα. **Οι αργίες ανήκουν στη Γραμματεία.**

## Class Grading

Πρώτα **My classes**: διάλεξε τμήμα και μετά **Tests** ή **Dictations**. Άφησε ενεργό το **Use school defaults** εκτός αν αυτή η ομάδα πρέπει να γράφει διαφορετικά διαγωνίσματα· το φύλλο λέει με λέξεις πότε ένα τμήμα ακολουθεί τις προεπιλογές του σχολείου. Το **School picture** δείχνει τη ρύθμιση της Γραμματείας για το league σου (μόνο για ανάγνωση). **Save My Class Grading**.

## Family Access

Ένα login γονέα ανά μαθητή. Διάλεξε μαθητή· ένα κλειδομπρελόκ δείχνει αν υπάρχει login και το username του (για νέο login προτείνεται username). Το **Easy password** φτιάχνει κωδικό που η οικογένεια πληκτρολογεί εύκολα από το χαρτί. **Save Parent Account**, και όταν χρειάζεται **Reset Password**, **Disable** ή **Delete**· ένα login που απενεργοποιήθηκε επιστρέφει με **Switch back on**. Μετά την αποθήκευση, το **Print family slip** τυπώνει τα στοιχεία μαζί με το QR σύνδεσης γονέα. Η Γραμματεία διαχειρίζεται όλα τα login οικογενειών από το Admin → Family Logins. Οι οικογένειες βλέπουν πρόοδο, εργασίες (από το Quest Assignment), γιορτές και σημειώσεις που **δημοσίευσες** (όπως μια σύνοψη γονέων του Oracle) — όχι το ιδιωτικό σου Chronicle. Pro και Elite.

## Quiz (Elite)

Όταν τα Quest Assignments γεμίζουν το βιβλίο του τμήματος, το **Generate from this week's lessons** χρησιμοποιεί αυτές τις ενότητες, τη γραμματική και τις λέξεις (από το τελευταίο ολοκληρωμένο quiz). Ξετσέκαρε λέξεις ή άνοιξε το **Different focus** για τα παλιά θέματα. Προαιρετικές επιλογές (**Review the questions before they go live**, **Bring back questions the class missed last week**), **Review & edit questions**, ιστορικό, επαναφορά αυτής της εβδομάδας. Ο αριθμός ερωτήσεων ακολουθεί το μέγεθος του τμήματος. Παίζεται στο Home, στο πρώτο μάθημα της εβδομάδας, μέσα στην ώρα του μαθήματος. Οι πλήρεις πίνακες ανταμοιβών είναι στο κεφάλαιο Home.

## Market (Elite)

Τα Seasonal Treasures και το Festival Stall αυτού του τμήματος (τμήμα της κεφαλίδας), το καθένα σαν δελτίο επισκευής. Το **New picture** κρατά το αντικείμενο και ξαναζωγραφίζει την εικόνα. Το **Replace this treasure** δημιουργεί νέο αντικείμενο της ίδιας σπανιότητας. **Save** για όνομα, περιγραφή, Gold και αντίτυπα που απομένουν. Το **Remove** το βγάζει από τον πάγκο. Τα εισερχόμενα κομμάτια του Restock εμφανίζονται στο **Coming in**.

## Πώς τροφοδοτεί το υπόλοιπο Quest

Χωρίς τμήμα και μαθητολόγιο, το Award Stars δεν έχει σύννεφα. Χωρίς Hero Path και Guild Quiz, τα εργαλεία ταυτότητας μένουν σε αδράνεια. Χωρίς Family Access, οι γονείς δεν μπορούν να δουν την εργασία που έγραψες στο τέλος του μαθήματος. Οι Settings είναι το **παρασκήνιο** της σκηνής· η παράσταση παίζεται στις δέκα καρτέλες.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Profile, My Classes, βασικά Student Tools | My Planning, Class Grading, Family Access, Guild Quiz, Hero Path, Ember Oaths | Avatar Forge, Oracle, αναφορές και πιστοποιητικά με AI, ιδέες ονομάτων τμήματος, αναζήτηση ονομαστικής εορτής, ρύθμιση Quiz, Familiar forge, Market Manager |
`,

  'teacher/14-hero-path.md': `# Hero Path (τάξεις και Skill Tree)

Πώς ένα παιδί **διαλέγει ταυτότητα** και μεγαλώνει εξασκώντας μία αρετή όλη τη χρονιά. **Pro και Elite.** Προαιρετικό: μπορεί να μείνει «No Class». **Κρατά** την τάξη που έχει ήδη. Κάθε σχολική χρονιά μπορεί να την **αλλάξει δύο φορές**. Η δεύτερη αλλαγή **κλειδώνει** τη διαδρομή μέχρι την επόμενη χρονιά. Η τάξη δεν σβήνεται.

Βασικό δώρο: **+10 Gold** όταν ο λόγος αστεριού ταιριάζει με την τάξη. Από το **επίπεδο 3** εμφανίζεται χρωματιστό **aura**.

## Πώς ορίζεις τάξη

Το Hero Path **δεν** είναι δέκατη καρτέλα. Το ορίζεις στο roster, ως **τελετή** που αγγίζει το ίδιο το παιδί — όπως το Guild Sorting.

1. Άνοιξε **Teacher Settings → My Classes → Manage Students**.
2. Κάθε γραμμή ομαδοποιεί τα κουμπιά της σε **Hero path** (Guild, Class, Skills), **Records** και **Manage**. Αν το παιδί **δεν έχει ακόμα Hero Class**, πάτα την ασπίδα **Class** στην ομάδα **Hero path** (**Choose Hero Class**). Όταν έχει ήδη τάξη, εκεί φαίνεται το έμβλημά της. Για να τη διαλέξεις ή να την αλλάξεις από το προφίλ, πάτα **Edit** (το μολύβι στην ομάδα **Manage**) → ενότητα **Hero path** → **Choose Hero Class** (ή **Change Hero Class** αν έχει ήδη).
3. Η τελετή ανοίγει στον πίνακα. Το παιδί πατά μία τάξη για **προεπισκόπηση** (η αίθουσα παίρνει το χρώμα της). Το **Swear this Path** αποθηκεύει την τάξη αμέσως. Το **Not yet** / κλείσιμο δεν αποθηκεύει.
4. Ακολουθεί σύντομο αποτέλεσμα: **You are a Guardian!** (ή Sage, Paladin, Artificer, Scholar, Vanguard, Nomad, Patron). Το **Let's Go!** το κλείνει.
5. Το **No Class** είναι κανονική επιλογή: απλώς **μην** τρέξεις την τελετή. Η ίδια η τελετή δεν προσφέρει No Class.
6. Το **Skills** (το κουμπί sitemap στην ομάδα **Hero path** της γραμμής, ή το **Skill tree** στην ενότητα Hero path του προφίλ) ανοίγει το δέντρο. Το κουμπί στο roster **πάλλεται** όταν περιμένει νέο κλαδί.

Η τάξη που έχουν ήδη **μένει**. Κάθε σχολική χρονιά μπορούν να ορκιστούν **άλλη** τάξη **δύο φορές**. Η πρώτη αλλαγή δεν κλειδώνει. Η δεύτερη **κλειδώνει** για την υπόλοιπη χρονιά. Η νέα χρονιά δεν σβήνει την τάξη· ξαναδίνει δύο αλλαγές. Η πρώτη ανάθεση, όταν δεν έχουν ακόμα τάξη, δεν χρησιμοποιεί αλλαγή.

## Το Skill Tree στην οθόνη

Άνοιξέ το από το **Manage Students** (το κουμπί **Skills** με το sitemap), από το μεγεθυμένο avatar, ή από το **LEVEL UP!**. Σε κάθε νέο επίπεδο διαλέγουν **ένα από δύο** μόνιμα κλαδιά. Το κουμπί **πάλλεται** μέχρι να διαλέξουν.

Τα μπόνους **αστέρια** κινούν κατατάξεις. Το μπόνους **Gold** όχι. Ισχύει μόνο με την **ταιριαστή αρετή**.

## Οι οκτώ τάξεις

| Τάξη | Αρετή | Τίτλοι |
|------|--------|--------|
| 🛡️ **Guardian** | Respect | Sentinel → … → Eternal Guardian |
| 🔮 **Sage** | Creativity | Apprentice → … → Elder Sage |
| ⚔️ **Paladin** | Teamwork | Squire → … → High Paladin |
| ⚙️ **Artificer** | Focus | Tinkerer → … → Grand Artificer |
| ⚜️ **Vanguard** | Training Grounds (και τα τέσσερα παιχνίδια) | Recruit → … → High Vanguard |
| 📜 **Scholar** | Scholar’s Bonus | τρεις βαθμίδες |
| 👟 **Nomad** | Welcome Back | τρεις βαθμίδες |
| 💝 **Patron** | Hero's Boon (όταν **δίνεις**· ένα path point ανά ημερολογιακή εβδομάδα) | Giver → Benefactor → Grand Patron |

Δεν είναι Quest League και δεν είναι guild.
`,

  'teacher/15-hero-campfire.md': `# Hero Campfire και Ember Oaths

Το **Hero Campfire** είναι προαιρετικός, δίλεπτος κλείσιμο στον projector. Η τάξη μαζεύεται γύρω από τη φωτιά, θυμάται τις λέξεις που εξάσκησε, απαντά μία ερώτηση στοχασμού, δείχνει πόσο φωτεινά έμαθε, και κοιτά λίγα **Ember Oaths**: μικρές προσωπικές υποσχέσεις που διάλεξε κάθε παιδί. Δεν υπάρχουν κατατάξεις, βαθμοί ούτε Gold.

## Σκοπός

Τα αστέρια ονομάζουν πράξεις. Η φωτιά προσθέτει δύο συνήθειες που το υπόλοιπο Quest δεν καλύπτει: **να κοιτάξουμε τι μάθαμε** και **να δουλέψουμε προς έναν προσωπικό στόχο**. Το παιδί διαλέγει τον στόχο, ο δάσκαλος επιβεβαιώνει την πρόοδο, και το δώρο είναι κοινό φως, όχι αριθμός.

## Όταν εμφανίζεται

- Ετοιμάζεται μόνο του στο παρασκήνιο, χωρίς να περιμένεις και χωρίς να χρειάζεται AI.
- Μόλις κλείσεις τον εορτασμό Hero of the Day (**Huzzah!**) και διαλέξεις πώς θα γραφτεί η σελίδα του ημερολογίου, ανάβει το **Gather at the Campfire** στο Adventure Log, κάτω από τα Crown Today’s Hero και Hall of Heroes, εκεί που συνήθως βρίσκεται το κουμπί Ember Oaths. Ένα μικρό σήμα (badge) εμφανίζεται και στο Home.
- Δεν ανοίγει μόνο του. Το μικρό **×** σημαίνει «όχι σήμερα».
- Μετά την τελετή το κουμπί ξεκουράζεται ως **Campfire held · Relight**.

## Τι βλέπει η τάξη (εφτά στιγμές)

Προχωράς με **Space, Enter ή →**, πίσω με **←**, κλείσιμο με **Esc**. Τίποτα δεν λέγεται δυνατά· όλα είναι οπτικά. Στη φωτιά δεν εμφανίζονται βιβλία, μονάδες, σελίδες ή χρονόμετρα.

**Pre-Junior:** χωρίς ονόματα και χωρίς ατομικές υποσχέσεις στον projector. Ο κύκλος γίνεται **Our Class Promise**.

## Ember Oaths

Άνοιξε το **Oath Board** από **🔥 Ember Oaths** στο Adventure Log (ακολουθεί το τμήμα στην κεφαλίδα· μένει γκρι μέχρι να διαλέξεις τμήμα), το 📜 Oaths στο αναμμένο κουμπί της φωτιάς, **🔥 Oaths** στην κάρτα τμήματος στο My Classes (ακριβώς αριστερά από τον κάδο), ή τη σελίδα **Oaths** στο Hero’s Chronicle.

Το Oath Board ανοίγει κάτω από έναν μικρό νυχτερινό ουρανό με το όνομα του τμήματος, έναν κύκλο που δείχνει πόσα παιδιά έχουν υπόσχεση και πόσες έχουν τηρηθεί. Η σειρά **Tonight** δίνει το επόμενο χρήσιμο βήμα με ένα πάτημα: μια υπόσχεση έτοιμη να τηρηθεί, τα παιδιά που περιμένουν το σημερινό check-in, ή το Choosing ceremony. Οι κάρτες δείχνουν πρώτα τις έτοιμες, μετά όσες περιμένουν check-in, με τις μέρες που απομένουν. Φίλτρα: Everyone · Check in · Need a promise · Ready to keep.

Ένα παιδί διαλέγει μία μικρή υπόσχεση. Τα τρία κουμπιά 🔥 / 🕯️ / 🌙 είναι το **σημερινό check-in**, όχι η τήρηση. Η υπόσχεση είναι έτοιμη όταν υπάρχει αρκετή απόδειξη και τουλάχιστον ένα 🔥· τότε **Keep the promise** ή **Let it rise**. Γίνεται αστέρι στον ουρανό (κάθε είδος έχει το δικό του σχήμα) και **Star-Ember** στο Trophy Room — ποτέ αστέρια, ποτέ Gold. Το τηλεσκόπιο στην κεφαλίδα σηκώνει την κάμερα στον ουρανό.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---|---|---|
| Δεν περιλαμβάνεται | Hero Campfire, Ember Oaths, αναγνώριση βιβλίου, τράπεζα ερωτήσεων | Επιπλέον η ερώτηση και οι καταληκτικές γραμμές με AI, και ιδέες Oracle (η τράπεζα δουλεύει πάντα χωρίς AI) |
`,

  'secretary/school-office.md': `# School Office (Γραμματεία)

Το School Office είναι το **γραφείο ελέγχου της σχολικής χρονιάς**. Δεν είναι δεύτερη τάξη. Οι δάσκαλοι εξακολουθούν να δίνουν αστέρια· η γραμματεία κρατά σε τάξη τον χρόνο, τις αργίες, τα τμήματα, τους μαθητές, τις προεπιλογές βαθμολόγησης και τα μηνύματα των οικογενειών.

**Elite.** Οι δάσκαλοι μπορούν να το ανοίξουν από την ασπίδα της κεφαλίδας όταν το σχολείο έχει πρόσβαση Secretary. Στο κινητό οι ίδιες πέντε καρτέλες εμφανίζονται σε μια συμπαγή μπάρα.

Κεφαλίδα: τίτλος **School Office**, **Open Teacher App**, αποσύνδεση. Ο τίτλος κάθε καρτέλας κάθεται σε μια μικρή πινακίδα: πίνακας ανακοινώσεων για το School, έλεγχος προόδου για το Grades, φάκελος επιστολής για το Messages, φάκελος αρχείου για το Admin.

## Οι πέντε καρτέλες

| Καρτέλα | Δουλειά |
|-----|-----|
| **Home** | Η υποδοχή: χαιρετισμός, σήμα πλάνου, τέσσερις μετρήσεις (Students, Classes, School stars, Treasury), **On your desk today**, **Latest at school** και **Office drawers** |
| **School** | Το **Classes** είναι μια ζωντανή εικόνα κάθε τάξης, μόνο για ανάγνωση. Πάτησε μια κάρτα τμήματος για να την ανοίξεις. Το **Students** ομαδοποιεί τους μαθητές ανά τμήμα, με Edit, Notes και Message σε κάθε κάρτα ήρωα |
| **Grades** | Βαθμοί **Scholar's Scroll** και **Quest Assignment**, για όλο το σχολείο. Το **Change how grades work** πηγαίνει στο Admin → Grading |
| **Messages** | Εισερχόμενα και απαντήσεις με οικογένειες και δασκάλους |
| **Admin** | **Students & Classes** (ανοίγει πρώτο), **School Year**, **School Details**, **Grading** |

Σε πλάνα χωρίς το πλήρες Elite School Office, τα Grades και Messages κρύβονται, τα κουμπιά Edit κρύβονται και το Admin → Grading δεν εμφανίζεται. Το Admin κρατά το Students & Classes (τοποθέτηση μαθητών που επιστρέφουν και πρώην μαθητές), το School Year και το School Details, αλλά τα **Open a new class** και **Enrol a new student** έχουν κλείδωμα Elite.

Οι λογαριασμοί δασκάλων δημιουργούνται όταν στήνεται το σχολείο (μαζί με τη χρέωση), όχι στο School Office. Το Office **ανοίγει το Teacher App** όταν η γραμματεία διδάσκει κιόλας. Δημιούργησε εδώ τμήματα για δασκάλους που έχουν ήδη λογαριασμό Quest Master.

## Home — η υποδοχή

- **Χαιρετισμός** με τη σημερινή ημερομηνία, το όνομα του σχολείου και το σήμα πλάνου
- **Τέσσερις μετρήσεις** — Students (σε τμήμα και σε αναμονή), Classes, School stars, Treasury (Gold της χρονιάς). Τα Students και Classes ανοίγουν την καρτέλα School
- **On your desk today** — ό,τι σε περιμένει, το πιο επείγον πρώτο: μαθητές που επιστρέφουν και χρειάζονται τμήμα, μηνύματα οικογενειών που περιμένουν απάντηση, και η τελευταία μέρα της χρονιάς αν δεν έχει οριστεί. Κάθε στοιχείο ανοίγει το σημείο όπου γίνεται η δουλειά. Όταν δεν περιμένει τίποτα, γράφει **All clear**
- **Latest at school** — ο τελευταίος βαθμός και η τελευταία συνομιλία με οικογένεια, καρφιτσωμένα σαν σημειώματα
- **Office drawers** — με ένα πάτημα σε Classes, Students, Grades, Messages, Students & Classes και Settings

Στο Home, στο Students & Classes και στους διαλόγους αποχώρησης και επιστροφής, οι μαθητές εμφανίζονται με το δικό τους avatar· τα αρχικά φαίνονται μόνο όταν ένας μαθητής δεν έχει ακόμη avatar.

## School → ένα τμήμα

Πατώντας ένα τμήμα ανοίγει ένα φωτεινό λάβαρο τμήματος (λογότυπο, δάσκαλος, league, πρόγραμμα, πόσοι ήρωες) και μια σειρά από δέκα προβολές: **Overview**, **Award Stars**, **Team Quest**, **Hero's Challenge**, **Mystic Market**, **Guild Hall**, **Adventure Log**, **Quest Calendar**, **Attendance**, **Grades**. Όλα είναι μόνο για ανάγνωση: αστέρια ανά ήρωα και ανά αρετή, ο αγώνας του league, το βάθρο του Hero's Challenge, τα πουγκιά με Gold, οι οίκοι των guild, το ημερολόγιο της τάξης, το επόμενο και το τελευταίο μάθημα, οι απουσίες και οι βαθμοί του τμήματος. Το **Open class desk** επεξεργάζεται το τμήμα· το **All classes** γυρίζει πίσω.

## Admin → Students & Classes

Ένα σημείο για όλη τη διαδρομή του μαθητή, στημένο σαν μία διαδρομή. Πάνω πάνω, ο πάγκος διαβάζεται από αριστερά προς τα δεξιά: **1 Open a new class**, μετά **2 Enrol a new student**. Όταν περιμένουν μαθητές που επιστρέφουν, εμφανίζεται και τρίτο γραφείο, το **Seat returning students**, με το πόσοι περιμένουν. Από κάτω, ένας φάκελος με τρεις λωρίδες, η καθεμία με τη δική της αναζήτηση:

- **Students** — όλοι οι εγγεγραμμένοι, ανά τμήμα, με πρώτο το **Waiting for a class** (το κουμπί του **Seat them** ανοίγει την τοποθέτηση). Κάθε συρτάρι τμήματος έχει **Enrol**, που προσθέτει νέο μαθητή κατευθείαν σε αυτό το τμήμα. Κάθε γραμμή έχει **Edit** (ανοίγει το διαβατήριο του μαθητή) και **Leaves**
- **Classes** — κάρτες τμημάτων με δάσκαλο, πρόγραμμα και αριθμό μαθητών. Το **Enrol** προσθέτει νέο μαθητή σε αυτό το τμήμα, το **Edit** ανοίγει τον φάκελο του τμήματος και το ματάκι ανοίγει το τμήμα στην καρτέλα School. Η κάρτα **Open a new class** ξεκινά νέο τμήμα
- **Former students** — όσοι έχουν φύγει, με κουμπιά αιτίας για φιλτράρισμα (**All**, **Moved away**, **Graduated**, **Other reason**)

Όταν πληκτρολογείς στην αναζήτηση, αλλάζουν μόνο τα αποτελέσματα· η υπόλοιπη σελίδα μένει ακίνητη.

### Add a new student

Το **Enrol a new student** ανοίγει ένα γραφείο δύο βημάτων (όχι τη φόρμα New Student του δασκάλου):

1. **Class** — διάλεξε τμήμα της φετινής χρονιάς από πλακίδια ομαδοποιημένα ανά δάσκαλο (λογότυπο, league, δάσκαλος, πλήθος). Δεν υπάρχει ακόμη το τμήμα του; Το τελευταίο πλακίδιο, **Their class isn’t here yet**, ανοίγει νέο τμήμα στο δρόμο· μόλις δημιουργηθεί, το γραφείο επιστρέφει με το τμήμα ήδη επιλεγμένο και ό,τι είχες γράψει κρατημένο
2. **Student** — το τμήμα που διάλεξες μένει καρφιτσωμένο πάνω (με **Change class**). Ονοματεπώνυμο (υποχρεωτικό), προαιρετικά γενέθλια και ονομαστική εορτή (οι ίδιες Special Dates που ορίζει ένας δάσκαλος στο Edit), μετά **Add to roster** (ή Enter). Το γραφείο μένει στο ίδιο τμήμα για τον επόμενο μαθητή· το **Done** το κλείνει

Το **Enrol** σε κάρτα ή συρτάρι τμήματος παραλείπει το βήμα 1 και ανοίγει κατευθείαν σε εκείνο το τμήμα.

Ο **δάσκαλος του τμήματος** έχει τον μαθητή, ακριβώς σαν να είχε πατήσει **New Student** στη δική του λίστα. Γι' αυτό μπορεί να δίνει αστέρια και να επεξεργάζεται την εγγραφή. Αυτό **δεν** είναι τοποθέτηση μαθητών που επιστρέφουν: ένας νέος ήρωας ξεκινά **ενεργός** στο τμήμα που διάλεξες. Guild, Hero Class, avatar και Family Access είναι τελετουργίες της τάξης ή της οικογένειας αφού υπάρξει ο μαθητής.

### Open and edit classes

Το **Open a new class** (το πρώτο γραφείο, ή η διακεκομμένη κάρτα στη λωρίδα Classes) ανοίγει το class desk, έναν οδηγό (όχι το Add New Class του δασκάλου):

1. Ιχνηλάτης με κουμπιά (**Teacher**, **Name**, **League**, **Schedule**, **Review**· όσα ολοκληρώθηκαν σε γυρίζουν πίσω). Διάλεξε δάσκαλο, μετά όνομα + λογότυπο, **Quest League**, μέρες και ώρες, έλεγχο, δημιουργία. Ο δάσκαλος έχει το τμήμα στο δικό του Teacher App
2. Μόλις ανοίξει το τμήμα, δύο επόμενα βήματα στέκονται δίπλα δίπλα: **Enrol its students** (ανοίγει το γραφείο μαθητών στο νέο τμήμα) και **Open another class** (κρατά τον ίδιο δάσκαλο επιλεγμένο)

Το **Edit** σε μια κάρτα τμήματος ανοίγει τον φάκελο του τμήματος: πάνω το **Enrol a new student here**, μετά **Teacher** (μαζί με μεταφορά του τμήματος σε άλλο δάσκαλο), **Name and emblem**, **Quest League** και **Lesson days and times**. Το **Save class** ή το **Cancel** σε γυρίζουν στη λίστα. Τα άδεια τμήματα μπορούν να αφαιρεθούν.

Η καρτέλα School **δεν** δημιουργεί ούτε επεξεργάζεται τμήματα. Γι' αυτό υπάρχει η λωρίδα Classes, ή το **Open class desk** από την προβολή ενός τμήματος.

### Place returning students

Το **Seat returning students** ανοίγει έναν οδηγό τοποθέτησης τριών βημάτων (όχι λίστα με ονόματα τμημάτων):

1. **Gather** — ομαδοποίηση ανά **Previous class** (προεπιλογή), **League** ή **A–Z**. Αναζήτηση με όνομα, παλιό τμήμα, league ή δάσκαλο. Πάτησε μια περσινή ομάδα για να πάρεις όλους μαζί. Στο A–Z, τσέκαρε μεμονωμένους ήρωες ή χρησιμοποίησε **Select all** / **Unselect all** για όσους φαίνονται στη λίστα (λαμβάνει υπόψη την αναζήτηση). Κάθε κάρτα μπορεί να δείχνει προτεινόμενο τμήμα.
2. **New class** — διάλεξε φετινό τμήμα από πλακίδια (λογότυπο, δάσκαλος, league, πόσοι έχουν ήδη τοποθετηθεί). Η καλύτερη αντιστοιχία φωτίζεται με βάση το περσινό league: πρώτα το φυσικό επόμενο league, μετά ο ίδιος δάσκαλος, μετά το μικρότερο τμήμα. Αν δεν υπάρχουν ακόμη τμήματα, άνοιξε ένα από εδώ.
3. **Review** — avatar, προηγούμενο τμήμα, league και εμβλήματα guild με τα ονόματα των οίκων. Ξετσέκαρε όποιον πρέπει να περιμένει ή χρησιμοποίησε **Select all** / **Unselect all**. Πάτησε **Seat** για τους υπόλοιπους. Το **Leaves school** ανοίγει τον ίδιο διάλογο αποχώρησης με τη λωρίδα Students.

Ο οδηγός μένει ανοιχτός μέχρι να τοποθετηθούν όλοι ή να πατήσεις **Done**. Κάθε ήρωας κρατά το guild που ήδη έχει. Οι δάσκαλοι μπορούν ακόμη να τοποθετούν μαθητές που επιστρέφουν από το **Student setup** στη δική τους λίστα.

### Όταν ένας μαθητής φεύγει

Το **Leaves** στη γραμμή ενός μαθητή (ή το **Leaves school** στην τοποθέτηση ή στο διαβατήριο) ανοίγει έναν σύντομο διάλογο. Διάλεξε γιατί — **Moved away**, **Graduated** ή **Other reason** — πρόσθεσε προαιρετικά μια σημείωση για το αρχείο και πάτησε **Mark as left**.

- Ο μαθητής φεύγει από κάθε λίστα τμήματος και κάθε λίστα της τάξης.
- Αστέρια, βαθμοί, σημειώσεις και ιστορικό μένουν στο αρχείο. **Τίποτα δεν διαγράφεται.**
- Η πρόσβαση της οικογένειας στην εφαρμογή παγώνει μέχρι να επιστρέψει.
- Για λίγα δευτερόλεπτα εμφανίζεται μπάρα **Undo**, σε περίπτωση λάθους.

Δεν υπάρχει αυτόματος καθαρισμός: η εγγραφή ενός πρώην μαθητή μένει μέχρι να αποφασίσεις διαφορετικά.

### Former students

Η λωρίδα **Former students** δείχνει όσους έχουν φύγει, τους πιο πρόσφατους πρώτους, με σφραγίδα για την αιτία, την ημερομηνία αποχώρησης, το τελευταίο τμήμα και τον δάσκαλο, και τη σημείωσή σου.

- **Bring back** — στείλ' τους **πίσω στο παλιό τους τμήμα** (αν υπάρχει ακόμη), **διάλεξε τμήμα** της φετινής χρονιάς, ή άφησέ τους να **περιμένουν στο Student placement** μαζί με τους άλλους που επιστρέφουν. Η εγγραφή τους είναι ακριβώς όπως την άφησαν και η πρόσβαση της οικογένειας επανέρχεται. Και εδώ προσφέρεται **Undo**.
- **Delete forever** — σβήνει ολόκληρη την εγγραφή: αστέρια, βαθμούς, σημειώσεις, μηνύματα, avatar και πρόσβαση οικογένειας. Για επιβεβαίωση πληκτρολογείς το όνομα του μαθητή. **Δεν αναιρείται.** Αν μπορεί να επιστρέψει κάποια μέρα, κράτησέ τον ως πρώην μαθητή.

### Το Adventurer's Passport στο Office

Το **Edit** σε έναν μαθητή ανοίγει το ίδιο Adventurer's Passport που χρησιμοποιούν οι δάσκαλοι, αλλά με ένα **Office desk** στη θέση των εργαλείων της τάξης:

- **Notes** — ο φάκελος του μαθητή στη γραμματεία. Καρφίτσωσε μια σημείωση με ετικέτα **Family**, **Health**, **Fees & forms** ή **General**· μπορείς αργότερα να την αλλάξεις ή να τη σβήσεις. Από κάτω, το **From the classroom** δείχνει τις σημειώσεις των δασκάλων για ανάγνωση. **Οι σημειώσεις της γραμματείας είναι ιδιωτικές: οι δάσκαλοι δεν τις βλέπουν ποτέ.**
- **Move class** — διάλεξε οποιοδήποτε φετινό τμήμα, ανά league, με πρώτο το league του μαθητή. Αστέρια, Gold, guild και σημειώσεις πάνε μαζί του· η εφαρμογή της οικογένειας και τα μηνύματα ακολουθούν στον νέο δάσκαλο. Προσφέρεται **Undo**. Για μαθητή που περιμένει τμήμα, το κουμπί γράφει **Seat in a class**.
- **Family login** — ανοίγει το κλειδομπρελόκ του μαθητή από το Family Logins παρακάτω (δημιουργία, νέος κωδικός κ.λπ.).
- **Grades** — ανοίγει την καρτέλα Grades με αναζήτηση ήδη για αυτόν τον μαθητή.
- **Leaves school** — ο διάλογος αποχώρησης παραπάνω.

Πορτρέτα, skill tree, τελετές ήρωα, πιστοποιητικά και το chronicle του δασκάλου μένουν στην τάξη. Το guild φαίνεται αλλά δεν αλλάζει ποτέ εδώ: ένας μαθητής που έχει ήδη guild γράφει **Member for life. Guilds never change.**· όποιος δεν έχει ακόμη, το διαλέγει στην τάξη με τον δάσκαλό του. Το κουμπί **Notes** σε μια κάρτα του School → Students ανοίγει τον ίδιο φάκελο της γραμματείας.

## Admin → Family Logins (Pro και Elite)

Η **κλειδοθήκη** της γραμματείας: κάθε εγγεγραμμένος μαθητής έχει ένα κλειδομπρελόκ, σε ένα συρτάρι ανά τμήμα. Πράσινο σημαίνει ότι η οικογένεια **μπορεί να συνδεθεί**, γκρι ότι είναι **απενεργοποιημένο**, διακεκομμένο ότι **δεν υπάρχει ακόμη login**. Στην κορυφή φαίνεται πόσες οικογένειες μπορούν να συνδεθούν, με αναζήτηση (μαθητής, username ή τμήμα) και φίλτρα: **Everyone**, **No login yet**, **Can sign in**, **Switched off**.

- **Πάτα ένα μπρελόκ** χωρίς login για να φτιάξεις ένα. Προτείνεται username από το όνομα του παιδιού (τα ελληνικά γράφονται με λατινικά, π.χ. *maria.p*) και ένας εύκολος κωδικός όπως *sunny-otter-47*· το ζάρι φτιάχνει άλλον. Τα αδέρφια παίρνουν το καθένα δικό του login.
- **Πάτα ένα μπρελόκ** με login για **νέο κωδικό**, αλλαγή **username**, **Switch off** ή **Delete**. Ένα απενεργοποιημένο login επιστρέφει με **Switch back on** και νέο κωδικό.
- Το **Create N missing** σε ένα συρτάρι τμήματος φτιάχνει μονομιάς login για όλους τους μαθητές του τμήματος που δεν έχουν.
- Μετά την αποθήκευση, ο διάλογος δείχνει τα στοιχεία μία φορά, με **Copy** και **Print slip(s)**: κάθε χαρτάκι έχει username, κωδικό και το QR σύνδεσης, δύο ανά σελίδα A4. Οι κωδικοί δεν ξαναφαίνονται όταν κλείσεις.
- **Parent sign-in QR**: το **Print poster** δίνει αφίσα A4 για τον πίνακα ανακοινώσεων· το **Copy link** αντιγράφει τη διεύθυνση που ανοίγει τη σύνδεση γονέα.

Οι δάσκαλοι κρατούν το δικό τους **Family Access** για τους μαθητές τους· και τα δύο δουλεύουν πάνω στα ίδια login.

## Admin → School Year

Έτσι **ανοίγει, τρέχει και κλείνει** η σχολική χρονιά. Ένα εξώφυλλο σαν ημερολόγιο τοίχου δείχνει τη χρονιά και μια σφραγίδα κατάστασης. Από κάτω, ένας κατάλογος **Students & classes** (μαθητές, τμήματα, σε αναμονή για τμήμα, πρώην μαθητές) οδηγεί στο Students & Classes. Οι καταστάσεις που θα συναντήσεις:

- **Not started yet** — opening day· last day
- **Between years** — opening day· **Open school year**
- **In progress** — opening day· last school day· **Finish the school year** σε τρία βήματα

### School calendar — opening day and last day

Δύο κάρτες **School calendar**, η καθεμία με ένα φύλλο ημερολογίου, κρατούν τις ημερομηνίες της χρονιάς. Το **Opening day** είναι η πρώτη μέρα μαθημάτων: **καμία ημερομηνία πριν από αυτήν δεν μετρά ως μέρα μαθήματος**, οπότε ένα σχολείο που ξεκινά στις 18 Σεπτεμβρίου δεν δείχνει μαθήματα την 1η–17η Σεπτεμβρίου στο παρουσιολόγιο, στο Quest Calendar ή οπουδήποτε αλλού μετριούνται μέρες μαθήματος. Είναι η ίδια τιμή που βλέπουν οι δάσκαλοι ως αρχή της χρονιάς. Άφησέ την στην 1η Σεπτεμβρίου αν τα μαθήματα όντως ξεκινούν με τον μήνα. Το **Last day of the school year** είναι η ημερομηνία κλεισίματος (δες *Finish the school year*). Ανάμεσα σε χρονιές εμφανίζεται μόνο η κάρτα του opening day.

### Finish the school year

Τρία αριθμημένα βήματα: **Set the last school day**, **Check readiness** (ανοίγει προεπισκόπηση), και μετά πληκτρολόγησε τη φράση επιβεβαίωσης και πάτησε **Finish school year**. Το κουμπί μένει κλειδωμένο μέχρι να φτάσει η τελευταία μέρα. Το κλείσιμο της χρονιάς την αποθηκεύει ως κλεισμένη χρονιά, αρχειοθετεί το Gold της, κρατά κάθε συμμετοχή σε guild, κρατά το Fortune Ledger εκείνης της χρονιάς μαζί της, μηδενίζει τη ζωντανή πρόοδο (αστέρια, Gold, Golden Legend και τις φετινές μετρήσεις Prodigy) και μεταφέρει τους μαθητές που επιστρέφουν στην τοποθέτηση. Το Treasury ξεκινά από 0 τη νέα χρονιά. Το παλιό Gold, τα παλιά στέμματα και το παλιό ιστορικό του Wheel μένουν στη χρονιά τους και δεν επηρεάζουν το Market, το Hall of Heroes, το Hall of Prodigies ή το Fortune Ledger της νέας χρονιάς.

Το κλείσιμο μιας χρονιάς την **αρχειοθετεί**, γι’ αυτό περίμενε να τελειώσουν οι βαθμοί, οι αναφορές και τα πιστοποιητικά που χρειάζεται ακόμη το σχολείο. Αν κάτι ξεφύγει, υπάρχουν εργαλεία εκτύπωσης έκτακτης ανάγκης εκτός αυτού του οδηγού· είναι για αποκατάσταση, όχι για καθημερινή χρήση.

Τα Crowns των guilds, η πρόοδος στο Hero Path και τα Familiars ανήκουν σε μία σχολική χρονιά τη φορά. Το κλείσιμο της χρονιάς κλείνει αυτό το κεφάλαιο, όπως η Grand Guild Ceremony για τα guilds.

## Admin → School Details

Κάρτες αρχείου, μία δουλειά η καθεμία:

- **Όνομα** σχολείου (με **Open Teacher App**)
- **Weather location** (ελληνικές πόλεις) — ορίζει τον ουρανό στο Home του δασκάλου και στο Projector
- **Your account** — μια κάρτα προσωπικού που δείχνει ποιος έχει συνδεθεί
- **Holidays and breaks** (όνομα, έναρξη, λήξη, θέμα: Christmas/Winter, Easter/Spring, generic) — σκιάζουν κάθε ημερολόγιο δασκάλου και **μικραίνουν τους στόχους Team Quest**
- **Secretary credentials**
- **Plan and billing**
- **Helpful shortcuts**: ανανέωση πληροφοριών οικογενειών, όλοι οι βαθμοί, απάντηση σε οικογένειες, Students & Classes

Το **My Planning** των δασκάλων ορίζει μόνο την ημερομηνία λήξης ενός τμήματος. **Εσύ** έχεις τις αργίες.

## Admin → Grading (Elite)

Κάθε league παίρνει μια μικρή κάρτα για τεστ και υπαγορεύσεις: **Marks out of 100**, έναν αριθμό από **word labels**, ή **Turned off**. Άνοιξε ένα league για να το αλλάξεις. Με το **Choose a class** δίνεις σε ένα τμήμα διαφορετικό τρόπο. Το **Save grading setup** αποθηκεύει και τα δύο. Οι δάσκαλοι μπορούν ακόμη να αλλάξουν ένα μόνο τμήμα στις Teacher Settings αν εκείνη η ομάδα είναι διαφορετική.

Το Pre-Junior ξεκινά με τα δύο κλειστά, μέχρι το σχολείο να είναι έτοιμο για χαρτί.

## Messages

Τύποι συνομιλίας που μπορείς να στείλεις:

Announcement, Meeting request, Attendance note, Celebration, Progress update, Homework, General message.

Οι γονείς απαντούν με μικρότερο σύνολο (General, Meeting request, Question). Κράτα τον τόνο **κατάλληλο για γονείς**. Ποτέ μην επικολλάς ιδιωτικές σημειώσεις Chronicle ή σημειώσεις της γραμματείας.

## Πώς τροφοδοτεί το Quest του δασκάλου

Λάθος αργίες = άδικοι στόχοι Team Quest. Λάθος πόλη καιρού = ηλιόλουστη κεφαλίδα μέσα σε καταιγίδα. Λάθος προεπιλογές βαθμών = άδεια Scholar's Scrolls ή απρόσμενο Starfall. Τα τμήματα που δημιουργούνται εδώ είναι οι αίθουσες όπου διδάσκουν στ' αλήθεια οι δάσκαλοι. Οι μαθητές που προστίθενται ή μετακινούνται εδώ εμφανίζονται στη λίστα εκείνου του δασκάλου. Ένας μαθητής που σημειώνεται ως αποχωρήσας χάνεται από την τάξη αλλά κρατά κάθε εγγραφή. Το Office δουλεύει στο παρασκήνιο, αλλά όλη η τάξη στηρίζεται πάνω του.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Το School Office δεν είναι σε αυτό το πλάνο | Το Family Access είναι άλλη πόρτα (δάσκαλος → γονέας). Το Office δεν είναι εκείνο το portal | Πλήρες School Office: αργίες, σχολική χρονιά, Students & Classes (νέοι μαθητές, class desk, student placement, πρώην μαθητές), σημειώσεις γραμματείας, πόλη καιρού, προεπιλογές βαθμών, μηνύματα για όλο το σχολείο |
`,

  'parent/family-portal.md': `# Family Portal (Γονέας)

Το Family Portal είναι ένα **ζεστό παράθυρο** σε ένα παιδί, φτιαγμένο για το κινητό του γονέα. Δεν είναι ο υπολογιστής της τάξης ούτε το School Office. Οι γονείς δεν μπορούν να δώσουν αστέρια, να αγοράσουν artifacts ή να δουν το ιδιωτικό Chronicle του δασκάλου.

**Pro και Elite.** Ένα login ανά μαθητή, που το φτιάχνει ο δάσκαλος στις Teacher Settings → **Family Access** ή η Γραμματεία στο Admin → **Family Logins**.

**Πώς μπαίνουν.** Οι οικογένειες σκανάρουν το **Parent sign-in QR** του σχολείου (στην αφίσα ή στο χαρτάκι τους). Ανοίγει την οθόνη σύνδεσης, **The Quest Gate**, κατευθείαν στην πόρτα **Parent** με ένα «Hello, family!»· πληκτρολογούν username και κωδικό από το χαρτάκι. Το κινητό θυμάται την πόρτα Parent την επόμενη φορά. Αν κάτι είναι λάθος, η οθόνη το λέει απλά (π.χ. «That username and password don't match») και το **Forgot password?** τους λέει να ζητήσουν νέο κωδικό από τον δάσκαλο ή τη γραμματεία.

Αν το School Office καταγράψει ότι το παιδί έφυγε από το σχολείο, το login παγώνει (τα αρχεία κρατιούνται). Αν το παιδί επιστρέψει, το login ξαναλειτουργεί — εκτός αν ο δάσκαλος το είχε ήδη απενεργοποιήσει.

Κινητό και υπολογιστής έχουν την ίδια διάταξη: κεφαλίδα με το πορτρέτο του παιδιού, το μικρό του όνομα, το τμήμα, το guild και το Hero Class, και μπάρα καρτελών κάτω. Ο ουρανός της κεφαλίδας ακολουθεί την ώρα της ημέρας. Το **Check for news** ζητά από το σχολείο φρέσκια σύνοψη· το portal το κάνει και μόνο του κάθε φορά που το ανοίγει μια οικογένεια.

## Οι τέσσερις καρτέλες

| Καρτέλα | Τι βλέπουν οι οικογένειες |
|---------|---------------------------|
| **Home** | Μια καρτ-ποστάλ που λέει την εβδομάδα με απλά λόγια (αστέρια της εβδομάδας, ένα τεστ που έρχεται, το τελευταίο αποτέλεσμα, το επόμενο μάθημα) και τι είναι **νέο από την τελευταία επίσκεψη** σε αυτό το κινητό. Από κάτω: το **επόμενο μάθημα** (από τις μέρες και την ώρα του τμήματος, χωρίς τις αργίες), η επόμενη **μέρα τεστ** ή η εργασία· το **βάζο με τα αστέρια** του μήνα· η τελευταία **δημοσιευμένη** σημείωση του δασκάλου με **Reply**· και οι **star moments**, οι πρόσφατοι λόγοι για τα αστέρια |
| **Homework** | Το τρέχον Quest Assignment καρφιτσωμένο σαν σημείωμα στο ψυγείο, με τίτλο το μάθημα για το οποίο είναι. Ένα τεστ μέσα στην εργασία παίρνει δική του κάρτα με αντίστροφη μέτρηση, την ύλη και **Add to calendar** (υπενθύμιση το προηγούμενο βράδυ) |
| **Progress** | Τα αστέρια μήνα με μήνα σαν σημάδια ύψους στην πόρτα· ένα **report card** με κάθε τεστ ή dictation, τον βαθμό του και δαχτυλίδι μέσου όρου (μόνο αν το τμήμα καταγράφει αξιολογήσεις)· παρουσίες με τις ημερομηνίες που έλειψε· και το Hero Class, το guild, το επίπεδο και το Gold του παιδιού, με **How the class game works** για τις οικογένειες |
| **Messages** | **Write to the school** με θέμα: **A question**, **Ask to meet**, **Absence note** (ξεκινά την πρόταση με την ημερομηνία του επόμενου μαθήματος) ή **Just a note**. Οι συζητήσεις μοιάζουν με chat· όσες δεν έχουν διαβαστεί σημειώνονται στη μπάρα καρτελών |

Αν το τμήμα **δεν** χρησιμοποιεί tests ή dictations, το Progress το λέει και μιλά μέσα από τα αστέρια και τις παρουσίες.

Μια συζήτηση που ξεκινά μια οικογένεια φτάνει στον δάσκαλο του παιδιού και στο **School Office** (Messages στη γραμματεία). Η γραμματεία μπορεί να απαντήσει εκεί.

## Τι πρέπει να καταλάβουν οι γονείς (για να το λέει ο δάσκαλος)

- Τα αστέρια είναι **χαρακτήρας στο μάθημα των Αγγλικών**, όχι δεύτερος επίσημος βαθμός.
- Τα μηνιαία αστέρια μηδενίζονται· τα αστέρια της χρονιάς και το guild όχι.
- Η εργασία εδώ είναι **το quest του επόμενου μαθήματος**, όχι σωρός από φυλλάδια.
- Τα μηνύματα είναι για συναντήσεις, ερωτήσεις και απουσίες, όχι για να αμφισβητηθεί ένα αποτέλεσμα Prodigy την τελευταία εβδομάδα του μήνα.

## Αξιοπρέπεια

Το portal είναι **ασφαλές για γονείς εκ σχεδιασμού**. Μη δημοσιεύεις σημειώσεις που δεν θα διάβαζες φωναχτά σε ένα γραφείο με το παιδί παρόν. Οι star moments και οι υποσχέσεις που τηρήθηκαν ανήκουν εδώ· οι τακτικές του Skill Tree όχι. Οι διορθώσεις που κάνεις εσύ, όπως η επισκευή ενός σκορ, δεν εμφανίζονται ποτέ ως star moments.

## Σημειώσεις πλάνου

| Starter | Pro | Elite |
|---------|-----|-------|
| Αυτή η πόρτα μένει κλειστή | Ένα login ανά παιδί: η εβδομάδα με μια ματιά, εργασίες, πρόοδος, παρουσίες, μηνύματα | Το ίδιο Family Portal |
`,

  'shared/glossary.md': `# Γλωσσάρι

Πάτα ένα όνομα με στιγμές στον οδηγό. **Ceremony of the Month** ≠ **Grand Guild Ceremony**. **Hero of the Day** ≠ **Prodigy**. **Hall of Heroes** ≠ **Hall of Prodigies**. **Hero’s Boon** ≠ **Teacher Boon**. **Hero Campfire** ≠ μηνιαία τελετή. **Ember Oath** ≠ Quest Assignment.
`,

  'shared/plans-and-features.md': `# Πλάνα και δυνατότητες

Το σχολείο είναι **Starter**, **Pro** ή **Elite**. Τα όρια παρακάτω είναι τα συνηθισμένα. Το πλάνο του σχολείου σου μπορεί να είναι στημένο λίγο διαφορετικά, οπότε αν ένα κουμπί είναι κλειδωμένο στην εφαρμογή, το μήνυμα πάνω του λέει τι περιλαμβάνει το πλάνο σου.

**Starter** — 3 δάσκαλοι / 6 τμήματα. Award Stars, Team Quest, Hero’s Challenge, Ceremony of the Month, Quest Assignment και παρουσίες, bounties, artifacts στο Market, Hero’s Boon, Teacher Boon, Projector Mode.

**Pro** — 6 / 10. Επιπλέον Guild Hall (Wheel, Ledger, sorting quiz), Hero Path, Quest Calendar, Scholar’s Scroll και Starfall, Adventure Log με Hero of the Day και Hall of Heroes, Hero Campfire και Ember Oaths, Attendance Chronicle, Family Access, My Planning, παράκαμψη βαθμών τμήματος.

**Elite** — απεριόριστα. Επιπλέον Training Grounds, Familiars, Quiz of the Week, School Office, και AI (chronicler, εικόνες, Avatar Forge, Oracle, Restock, nameday, πιστοποιητικά).

`
};
